INSERT INTO `escenas` VALUES (1,1,1,'objetivos','Introducción','<div class=\"container my-5\">\n    <div class=\"row g-4\">\n        <!-- Tarjeta de Objetivos Educativos -->\n        <div class=\"col-md-7\">\n            <div class=\"card h-100 border-0 shadow-sm\" style=\"border-radius: 15px; border-left: 5px solid #0d6efd !important;\">\n                <div class=\"card-body p-4\">\n                    <div class=\"d-flex align-items-center mb-3\">\n                        <div class=\"bg-primary bg-opacity-10 p-2 rounded-circle me-3\">\n                            <i class=\"bi bi-journal-check text-primary fs-4\"></i>\n                        </div>\n                        <h2 class=\"card-title mb-0 fw-bold text-dark\">Objetivo educativo del módulo</h2>\n                    </div>\n                    <ul class=\"list-group list-group-flush\">\n                        <li class=\"list-group-item border-0 px-0 d-flex align-items-start\">\n                            <span class=\"badge bg-primary rounded-pill me-2 mt-1\">1</span>\n                            <span>Reconocer los datos clínicos sugestivos de <strong>apendicitis aguda complicada</strong>.</span>\n                        </li>\n                        <li class=\"list-group-item border-0 px-0 d-flex align-items-start\">\n                            <span class=\"badge bg-primary rounded-pill me-2 mt-1\">2</span>\n                            <span>Aplicar escalas clínicas y de riesgo para la toma de decisiones.</span>\n                        </li>\n                        <li class=\"list-group-item border-0 px-0 d-flex align-items-start\">\n                            <span class=\"badge bg-primary rounded-pill me-2 mt-1\">3</span>\n                            <span>Seleccionar estudios diagnósticos adecuados según el contexto.</span>\n                        </li>\n                        <li class=\"list-group-item border-0 px-0 d-flex align-items-start\">\n                            <span class=\"badge bg-primary rounded-pill me-2 mt-1\">4</span>\n                            <span>Integrar un plan terapéutico oportuno.</span>\n                        </li>\n                        <li class=\"list-group-item border-0 px-0 d-flex align-items-start\">\n                            <span class=\"badge bg-primary rounded-pill me-2 mt-1\">5</span>\n                            <span>Identificar hallazgos quirúrgicos y evaluar la evolución posoperatoria.</span>\n                        </li>\n                    </ul>\n                </div>\n            </div>\n        </div>\n\n        <!-- Tarjeta de Perfil del Usuario -->\n        <div class=\"col-md-5\">\n            <div class=\"card h-100 border-0 shadow-sm bg-light\" style=\"border-radius: 15px;\">\n                <div class=\"card-body p-4\">\n                    <div class=\"d-flex align-items-center mb-3\">\n                        <div class=\"bg-secondary bg-opacity-10 p-2 rounded-circle me-3\">\n                            <i class=\"bi bi-people-fill text-secondary fs-4\"></i>\n                        </div>\n                        <h2 class=\"card-title mb-0 fw-bold text-dark\">Perfil del usuario</h2>\n                    </div>\n                    <div class=\"d-flex flex-wrap gap-2\">\n                        <span class=\"badge text-secondary border border-secondary rounded-pill p-2 px-3\">Médicos generales</span>\n                        <span class=\"badge text-secondary border border-secondary rounded-pill p-2 px-3\">Médicos internos de pregrado</span>\n                        <span class=\"badge text-secondary border border-secondary rounded-pill p-2 px-3\">Residentes de urgencias</span>\n                        <span class=\"badge text-secondary border border-secondary rounded-pill p-2 px-3\">Cirugía general</span>\n                        <span class=\"badge text-secondary border border-secondary rounded-pill p-2 px-3\">Personal en formación</span>\n                    </div>\n                    <hr class=\"my-3 opacity-10\">\n                    <p class=\"small text-muted mb-0\">\n                        <i class=\"bi bi-info-circle me-1\"></i> Contenido diseñado para fortalecer la toma de decisiones clínicas.\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>','../img/apendicitis.png',0,NULL),(2,1,2,'Escenario','Escenario clínico','<div class=\"container my-5\">\n    <div class=\"row\">\n        <div class=\"col-12\">\n            <div class=\"card border-0 shadow-lg\" style=\"border-radius: 20px; overflow: hidden;\">\n                <div class=\"row g-0 align-items-center\">\n                    \n                    <div class=\"col-md-6 col-lg-7 bg-black d-flex align-items-center justify-content-center\">\n                        <div class=\"ratio ratio-16x9\">\n                            <video id=\"videoEscenario\" autoplay muted loop playsinline class=\"w-100\" style=\"object-fit: cover;\">\n                                <source src=\"../video/apendicitisIntro.mp4\" type=\"video/mp4\">\n                                Tu navegador no soporta la reproducción de video.\n                            </video>\n                        </div>\n                    </div>\n                    \n                    <div class=\"col-md-6 col-lg-5 p-5 bg-white\">\n                        <div class=\"d-flex align-items-center mb-4\">\n                            \n                            \n\n\n<div class=\"mt-4 d-flex align-items-center text-primary small fw-bold\">\n                            <span class=\"spinner-grow spinner-grow-sm me-2\" role=\"status\"></span>\n                            Análisis en curso...\n                        </div>\n\n\n                        </div>\n                        \n                        <div class=\"p-4 bg-light rounded-3\" style=\"border-left: 4px solid #dee2e6;\">\n                            <p class=\"card-text text-muted mb-0 lh-lg\" style=\"font-size: 1.1rem;\">\n                                Paciente masculino de <strong class=\"text-dark\">20 años</strong> acude a urgencias por <strong class=\"text-dark\">dolor abdominal</strong> de <strong class=\"text-dark\">18 horas de evolución</strong>.\n                            </p>\n                        </div>\n                        \n                        \n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>','',0,NULL),(3,1,3,'texto','Evolución clínica','<div class=\"container my-5\">\n    <div class=\"row\">\n        <div class=\"col-lg-10 mx-auto\">\n            <div class=\"card border-0 shadow-sm\" style=\"border-radius: 20px;\">\n                <div class=\"card-body p-4 p-md-5\">\n                    \n                    <div class=\"d-flex align-items-center mb-5\">\n                        <div class=\"bg-danger bg-opacity-10 p-2 rounded-circle me-3\">\n                            <i class=\"bi bi-activity text-danger fs-3\"></i>\n                        </div>\n                        <h2 class=\"card-title mb-0 fw-bold text-dark\">Historia de la Enfermedad Actual</h2>\n                    </div>\n\n                    <div class=\"row g-4\">\n                        <div class=\"col-md-6\">\n                            <h6 class=\"text-uppercase text-muted fw-bold mb-4 small tracking-wider\">Progreso del Dolor</h6>\n                            \n                            <div class=\"position-relative ps-4 border-start border-2 border-primary border-opacity-25\">\n                                <div class=\"mb-4 position-relative\">\n                                    <div class=\"position-absolute start-0 translate-middle-x bg-primary rounded-circle\" style=\"width: 12px; height: 12px; left: -25px !important; top: 8px;\"></div>\n                                    <h6 class=\"fw-bold mb-1\">Inicio</h6>\n                                    <p class=\"text-muted small mb-0\">Región periumbilical, intensidad moderada <span class=\"badge bg-warning text-dark\">EVA 5/10</span></p>\n                                </div>\n                                \n                                <div class=\"mb-0 position-relative\">\n                                    <div class=\"position-absolute start-0 translate-middle-x bg-danger rounded-circle\" style=\"width: 12px; height: 12px; left: -25px !important; top: 8px;\"></div>\n                                    <h6 class=\"fw-bold mb-1\">Migración</h6>\n                                    <p class=\"text-muted small mb-0\">Hacia fosa ilíaca derecha, aumento de intensidad <span class=\"badge bg-danger\">EVA 8/10</span></p>\n                                </div>\n                            </div>\n                        </div>\n\n                        <div class=\"col-md-6\">\n                            <h6 class=\"text-uppercase text-muted fw-bold mb-4 small tracking-wider\">Hallazgos Clínicos</h6>\n                            \n                            <div class=\"d-flex flex-column gap-3\">\n                                <div class=\"p-3 rounded-3 bg-light d-flex align-items-center\">\n                                    <i class=\"bi bi-plus-circle-fill text-success me-3 fs-5\"></i>\n                                    <div>\n                                        <p class=\"mb-0 fw-medium\">Síntomas asociados</p>\n                                        <small class=\"text-muted\">Anorexia, náusea, fiebre subjetiva.</small>\n                                    </div>\n                                </div>\n\n                                <div class=\"p-3 rounded-3 bg-light d-flex align-items-center\" style=\"border-left: 4px solid #dee2e6;\">\n                                    <i class=\"bi bi-dash-circle-fill text-secondary me-3 fs-5\"></i>\n                                    <div>\n                                        <p class=\"mb-0 fw-medium text-muted\">Negativos funcionales</p>\n                                        <small class=\"text-muted\">Diarrea, sangrado digestivo, síntomas urinarios.</small>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n\n                </div>\n            </div>\n        </div>\n    </div>\n</div>','',0,NULL),(4,1,4,'pregunta','¿Cuál es la presentación clínica sugestiva de apendicitis aguda en la población adulta?','<div id=\"retroalimentacion\" class=\"mt-4\">Retroalimentación</div>\n\n<br><br>\n\n<div class=\"row\">\n    <div class=\"col-md-6\">\n        <button class=\"btn btn-outline-primary text-start p-3 border-2 shadow-sm d-flex align-items-center w-100 h-100\" \n            style=\"border-radius: 12px; transition: 0.3s;\"\n            onclick=\"\n            guardarRespuesta(\'C\',0);\n            respuestaContestada = true;\n            document.getElementById(\'retroalimentacion\').innerHTML = `\n                <div class=\'card border-0 shadow-sm bg-danger bg-opacity-10 p-4\' style=\'border-radius: 15px;\'>\n                    <div class=\'d-flex align-items-center text-danger mb-0\'>\n                        <i class=\'bi bi-check-circle-fill fs-4 me-2\'></i>\n                        <h5 class=\'mb-0 fw-bold\'>Retroalimentación</h5>\n                    </div>\n                    <hr class=\'border-danger opacity-25\'>\n                    <strong>Respuesta correcta: C</strong>\n                    <p class=\'mt-2 mb-0 small text-dark\'>El cuadro típico de dolor abdominal periumbilical de 24-48 horas de evolución que migra y se localiza en la fosa iliaca derecha se presenta en aproximadamente 50% de los casos.</p>\n                </div>\n            `;\">\n            <span class=\"badge bg-dark text-white border me-3 py-2 px-3\">A</span>\n            <span>Dolor de inicio súbito en fosa iliaca derecha</span>\n        </button>\n    </div>\n\n    <div class=\"col-md-6\">\n         <button class=\"btn btn-outline-primary text-start p-3 border-2 shadow-sm d-flex align-items-center w-100 h-100\" \n            style=\"border-radius: 12px; transition: 0.3s;\"\n            onclick=\"\n            guardarRespuesta(\'C\',0);\n            respuestaContestada = true;\n            document.getElementById(\'retroalimentacion\').innerHTML = `\n                <div class=\'card border-0 shadow-sm bg-danger bg-opacity-10 p-4\' style=\'border-radius: 15px;\'>\n                    <div class=\'d-flex align-items-center text-danger mb-0\'>\n                        <i class=\'bi bi-check-circle-fill fs-4 me-2\'></i>\n                        <h5 class=\'mb-0 fw-bold\'>Retroalimentación</h5>\n                    </div>\n                    <hr class=\'border-danger opacity-25\'>\n                    <strong>Respuesta correcta: C</strong>\n                    <p class=\'mt-2 mb-0 small text-dark\'>El cuadro típico de dolor abdominal periumbilical de 24-48 horas de evolución que migra y se localiza en la fosa iliaca derecha se presenta en aproximadamente 50% de los casos.</p>\n                </div>\n            `;\">\n            <span class=\"badge bg-dark text-white border me-3 py-2 px-3\">B</span>\n            <span>Dolor que inicia en región dorsal</span>\n        </button>\n    </div>\n</div>\n\n<br>\n\n<div class=\"row\">\n    <div class=\"col-md-6\">\n        <button class=\"btn btn-outline-primary text-start p-3 border-2 shadow-sm d-flex align-items-center w-100 h-100\" \n            style=\"border-radius: 12px; transition: 0.3s;\"\n            onclick=\"\n            guardarRespuesta(\'C\',1);\n            respuestaContestada = true;\n            document.getElementById(\'retroalimentacion\').innerHTML = `\n                <div class=\'card border-0 shadow-sm bg-success bg-opacity-10 p-4\' style=\'border-radius: 15px;\'>\n                    <div class=\'d-flex align-items-center text-success mb-0\'>\n                        <i class=\'bi bi-check-circle-fill fs-4 me-2\'></i>\n                        <h5 class=\'mb-0 fw-bold\'>¡Correcto!</h5>\n                    </div>\n                </div>\n            `;\">\n            <span class=\"badge bg-dark text-white border me-3 py-2 px-3\">C</span>\n            <span>\n                Dolor abdominal peri umbilical de 24-48 horas de evolución que migra y se localiza en la fosa iliaca derecha\n            </span>\n        </button>\n    </div>\n\n    <div class=\"col-md-6\">\n        <button class=\"btn btn-outline-primary text-start p-3 border-2 shadow-sm d-flex align-items-center w-100 h-100\" \n            style=\"border-radius: 12px; transition: 0.3s;\"\n            onclick=\"\n            guardarRespuesta(\'C\',0);\n            respuestaContestada = true;\n            document.getElementById(\'retroalimentacion\').innerHTML = `\n                <div class=\'card border-0 shadow-sm bg-danger bg-opacity-10 p-4\' style=\'border-radius: 15px;\'>\n                    <div class=\'d-flex align-items-center text-danger mb-0\'>\n                        <i class=\'bi bi-check-circle-fill fs-4 me-2\'></i>\n                        <h5 class=\'mb-0 fw-bold\'>Retroalimentación</h5>\n                    </div>\n                    <hr class=\'border-danger opacity-25\'>\n                    <strong>Respuesta correcta: C</strong>\n                    <p class=\'mt-2 mb-0 small text-dark\'>El cuadro típico de dolor abdominal periumbilical de 24-48 horas de evolución que migra y se localiza en la fosa iliaca derecha se presenta en aproximadamente 50% de los casos.</p>\n                </div>\n            `;\">\n            <span class=\"badge bg-dark text-white border me-3 py-2 px-3\">D</span>\n            <span>Dolor en fosa iliaca izquierda migrante a fosa iliaca derecha</span>\n        </button>\n    </div>\n</div>','',1,'C'),(5,1,5,'pregunta','Exploración física','<div class=\"container mt-5 mb-5\">\n    <div class=\"row justify-content-center\">\n        <div class=\"col-lg-6\">\n            <div class=\"card border-0 shadow-lg overflow-hidden\" style=\"border-radius: 20px;\">\n                <div class=\"bg-dark p-2 text-center text-white-50 small tracking-wider\">\n                    <i class=\"bi bi-activity me-2\"></i> MONITOR DE SIGNOS VITALES\n                </div>\n                <div class=\"bg-light p-3 text-center\">\n                    <img src=\"../img/signosVitales.png\" class=\"img-fluid rounded\" alt=\"Signos Vitales\" style=\"max-height: 400px; width: auto;\">\n                </div>\n            </div>\n        </div>\n        <div class=\"col-lg-6\">\n            <div class=\"text-center mb-4\">\n                <span class=\"badge bg-primary bg-opacity-10 text-white px-3 py-2 rounded-pill mb-3\">Razonamiento Clínico</span>\n                <h3 class=\"fw-bold text-dark\">¿Cuál es el diagnóstico más probable con la información inicial?</h3>\n            </div>\n\n            <div id=\"retroalimentacion\" class=\"mb-4\"></div>\n\n            <div class=\"row mb-4\">\n                <div class=\"col-md-6\">\n                    <button class=\"btn btn-outline-primary text-start p-3 border-2 shadow-sm d-flex align-items-center w-100\" \n                        style=\"border-radius: 12px; transition: 0.3s;\"\n                        onclick=\"\n                        guardarRespuesta(\'B\',0);\n                        respuestaContestada = true;\n                        document.getElementById(\'retroalimentacion\').innerHTML = `\n                            <div class=\'card border-0 shadow-sm bg-danger bg-opacity-10 p-4\' style=\'border-radius: 15px;\'>\n                                <div class=\'d-flex align-items-center text-danger mb-0\'>\n                                    <i class=\'bi bi-check-circle-fill fs-4 me-2\'></i>\n                                    <h5 class=\'mb-0 fw-bold\'>Retroalimentación</h5>\n                                </div>\n                                <hr class=\'border-danger opacity-25\'>\n                                <p class=\'text-dark\'><strong>Respuesta correcta: B. Apendicitis aguda</strong></p>\n                                <p class=\'mb-0 small text-dark opacity-75\'>La gastroenteritis suele acompañarse de diarrea y dolor abdominal difuso. En este caso el dolor migratorio hacia fosa iliaca derecha es altamente sugestivo de apendicitis aguda.</p>\n                            </div>\n                        `;\">\n                        <span class=\"badge bg-dark text-white border me-3 py-2 px-3\">A</span>\n                        <span class=\"fw-medium\">Gastroenteritis</span>\n                    </button>\n                </div>\n\n                <div class=\"col-md-6\">\n                    <button class=\"btn btn-outline-primary text-start p-3 border-2 shadow-sm d-flex align-items-center w-100\" \n                        style=\"border-radius: 12px; transition: 0.3s;\"\n                        onclick=\"\n                        guardarRespuesta(\'B\',1);\n                        respuestaContestada = true;\n                        document.getElementById(\'retroalimentacion\').innerHTML = `\n                            <div class=\'card border-0 shadow-sm bg-success bg-opacity-10 p-4\' style=\'border-radius: 15px;\'>\n                                <div class=\'d-flex align-items-center text-success mb-0\'>\n                                    <i class=\'bi bi-check-circle-fill fs-4 me-2\'></i>\n                                    <h5 class=\'mb-0 fw-bold\'>¡Diagnóstico Correcto!</h5>\n                                </div>\n                                <hr class=\'border-success opacity-25\'>\n                                <p class=\'mb-3 text-dark\'><strong>Secuencia o Tríada de Murphy:</strong> Dolor periumbilical que migra a FID + Anorexia + Náuseas/Vómito.</p>\n                                <p class=\'mb-0 small text-dark opacity-75 italic\'>Explicación fisiopatológica: Inicialmente existe irritación del sistema esplácnico (T8-T10), generando dolor visceral difuso. Al involucrarse el peritoneo parietal, el dolor se localiza en FID.</p>\n                            </div>\n                        `;\">\n                        <span class=\"badge bg-dark text-white border me-3 py-2 px-3\">B</span>\n                        <span class=\"fw-medium\">Apendicitis aguda</span>\n                    </button>\n                </div>\n            </div>\n            \n            <div class=\"row mb-4\">\n                <div class=\"col-md-6\">\n                    <button class=\"btn btn-outline-primary text-start p-3 border-2 shadow-sm d-flex align-items-center w-100\" \n                        style=\"border-radius: 12px; transition: 0.3s;\"\n                        onclick=\"\n                        guardarRespuesta(\'B\',0);\n                        respuestaContestada = true;\n                        document.getElementById(\'retroalimentacion\').innerHTML = `\n                            <div class=\'card border-0 shadow-sm bg-danger bg-opacity-10 p-4\' style=\'border-radius: 15px;\'>\n                                <div class=\'d-flex align-items-center text-danger mb-0\'>\n                                    <i class=\'bi bi-check-circle-fill fs-4 me-2\'></i>\n                                    <h5 class=\'mb-0 fw-bold\'>Retroalimentación</h5>\n                                </div>\n                                <hr class=\'border-danger opacity-25\'>\n                                <p class=\'text-dark\'><strong>Respuesta correcta: B. Apendicitis aguda</strong></p>\n                                <p class=\'mb-0 small text-dark opacity-75\'>El cólico renal suele producir dolor intenso tipo cólico irradiado hacia región lumbar o genitales, frecuentemente acompañado de hematuria.</p>\n                            </div>\n                        `;\">\n                        <span class=\"badge bg-dark text-white border me-3 py-2 px-3\">C</span>\n                        <span class=\"fw-medium\">Cólico renal</span>\n                    </button>\n                </div>\n\n                <div class=\"col-md-6\">\n                    <button class=\"btn btn-outline-primary text-start p-3 border-2 shadow-sm d-flex align-items-center w-100\" \n                        style=\"border-radius: 12px; transition: 0.3s;\"\n                        onclick=\"\n                        guardarRespuesta(\'B\',0);\n                        respuestaContestada = true;\n                        document.getElementById(\'retroalimentacion\').innerHTML = `\n                            <div class=\'card border-0 shadow-sm bg-danger bg-opacity-10 p-4\' style=\'border-radius: 15px;\'>\n                                <div class=\'d-flex align-items-center text-danger mb-0\'>\n                                    <i class=\'bi bi-check-circle-fill fs-4 me-2\'></i>\n                                    <h5 class=\'mb-0 fw-bold\'>Retroalimentación</h5>\n                                </div>\n                                <hr class=\'border-danger opacity-25\'>\n                                <p class=\'text-dark\'><strong>Respuesta correcta: B. Apendicitis aguda</strong></p>\n                                <p class=\'mb-0 small text-dark opacity-75\'>La obstrucción intestinal suele presentarse con distensión abdominal importante, vómitos y ausencia de evacuaciones, datos que no predominan en este escenario.</p>\n                            </div>\n                        `;\">\n                        <span class=\"badge bg-dark text-white border me-3 py-2 px-3\">D</span>\n                        <span class=\"fw-medium\">Obstrucción intestinal</span>\n                    </button>\n                </div>\n            </div>\n\n        </div>\n    </div>\n</div>','',1,'B'),(6,1,6,'texto','Impresión clínica inicial','<div class=\"container my-5\">\n    <div class=\"row justify-content-center\">\n        <div class=\"col-lg-10\">\n            <div class=\"card border-0 shadow-lg\" style=\"border-radius: 20px; background: linear-gradient(145deg, #ffffff, #f8f9ff);\">\n                <div class=\"card-body p-4 p-md-5\">\n                    \n                    <div class=\"d-flex align-items-center mb-4\">\n                        <div class=\"bg-primary p-3 rounded-3 shadow-sm me-4\">\n                            <i class=\"bi bi-clipboard2-pulse text-white fs-2\"></i>\n                        </div>\n                        <div>\n                            <h6 class=\"text-primary fw-bold text-uppercase mb-1\" style=\"letter-spacing: 1px;\">Fase de Análisis</h6>\n                            <h2 class=\"fw-bold text-dark mb-0\">Impresión Clínica Inicial</h2>\n                        </div>\n                    </div>\n\n                    <div class=\"row g-4\">\n                        <div class=\"col-md-6\">\n                            <div class=\"p-4 h-100 rounded-4 border-start border-4 border-primary bg-white shadow-sm\">\n                                <div class=\"d-flex align-items-center mb-3\">\n                                    <span class=\"badge rounded-pill bg-primary me-2\">1</span>\n                                    <h5 class=\"fw-bold mb-0\">Análisis Sindromático</h5>\n                                </div>\n                                <h4 class=\"text-dark fw-bold mb-3\">Abdomen agudo quirúrgico probable</h4>\n                                <p class=\"text-muted small mb-0\">\n                                    Se establece por la presencia de dolor abdominal progresivo, datos de irritación peritoneal y respuesta inflamatoria sistémica en evolución.\n                                </p>\n                            </div>\n                        </div>\n\n                        <div class=\"col-md-6\">\n                            <div class=\"p-4 h-100 rounded-4 border-start border-4 border-danger bg-white shadow-sm\">\n                                <div class=\"d-flex align-items-center mb-3\">\n                                    <span class=\"badge rounded-pill bg-danger me-2\">2</span>\n                                    <h5 class=\"fw-bold mb-0\">Sospecha Diagnóstica</h5>\n                                </div>\n                                <h4 class=\"text-dark fw-bold mb-3\">Apendicitis aguda complicada</h4>\n                                <p class=\"text-muted small mb-0\">\n                                    Basado en la <strong>Cronología de Murphy</strong> positiva y el tiempo de evolución (>18 horas), lo que incrementa el riesgo de perforación o plastrón.\n                                </p>\n                            </div>\n                        </div>\n                    </div>\n\n                    <div class=\"mt-4 p-3 bg-warning bg-opacity-10 border border-warning border-opacity-25 rounded-3\">\n                        <div class=\"d-flex\">\n                            <i class=\"bi bi-exclamation-triangle-fill text-warning me-3 fs-4\"></i>\n                            <div>\n                                <span class=\"fw-bold text-dark d-block\">Nota de Guardia:</span>\n                                <span class=\"small text-white\">Se requiere integración inmediata de estudios paraclínicos y valoración por cirugía general para definir conducta definitiva.</span>\n                            </div>\n                        </div>\n                    </div>\n\n                </div>\n            </div>\n        </div>\n    </div>\n</div>','',0,NULL),(7,1,7,'texto','Estudios de laboratorio','<div class=\"container my-5\">\n    <div class=\"row justify-content-center\">\n        <div class=\"col-lg-11\">\n            <div class=\"card border-0 shadow-lg\" style=\"border-radius: 20px; background-color: #fcfcfc;\">\n                \n                <div class=\"d-flex\">\n                    <div class=\"bg-success text-white px-4 py-2\" style=\"border-radius: 20px 20px 0 0; font-size: 0.85rem; font-weight: bold; letter-spacing: 1px; background-color: #1a4d3a !important;\">\n                        <i class=\"bi bi-file-earmark-medical me-2\"></i>REPORTE DE RESULTADOS: FOLIO 250523\n                    </div>\n                </div>\n\n                <div class=\"card-body p-4 border-top border-success border-4\" style=\"border-radius: 0 15px 15px 15px;\">\n                    <div class=\"row align-items-center\">\n                        \n                        <div class=\"col-xl-7 text-center mb-4 mb-xl-0\">\n                            <div class=\"p-3 bg-white shadow-sm rounded border\">\n                                <img src=\"../img/estudiosLab.png\" class=\"img-fluid rounded\" alt=\"Laboratorio IMSS\" style=\"max-height: 550px; width: auto;\">\n                            </div>\n                        </div>\n\n                        <div class=\"col-xl-5\">\n                            <div class=\"p-4 rounded-4 bg-white border shadow-sm\">\n                                <h5 class=\"fw-bold text-dark mb-4 d-flex align-items-center\">\n                                    <i class=\"bi bi-search me-2 text-success\"></i> Hallazgos Clave\n                                </h5>\n                                \n                                <div class=\"mb-4 p-3 rounded-3 bg-light border-start border-4 border-danger\">\n                                    <div class=\"d-flex justify-content-between align-items-center mb-1\">\n                                        <h6 class=\"fw-bold mb-0 text-danger\">Leucocitosis Severa</h6>\n                                        <span class=\"badge bg-danger\">14,000/mm³</span>\n                                    </div>\n                                    <p class=\"small text-muted mb-0\">Indica una respuesta inmunológica activa ante el proceso infeccioso/inflamatorio.</p>\n                                </div>\n\n                                <div class=\"mb-4 p-3 rounded-3 bg-light border-start border-4 border-warning\">\n                                    <div class=\"d-flex justify-content-between align-items-center mb-1\">\n                                        <h6 class=\"fw-bold mb-0 text-warning text-dark\">Desviación a la izquierda</h6>\n                                        <span class=\"badge bg-warning text-dark\">85% Neutrófilos</span>\n                                    </div>\n                                    <p class=\"small text-muted mb-0\">La predominancia de neutrófilos confirma la etiología bacteriana aguda.</p>\n                                </div>\n\n                                <div class=\"mb-4 p-3 rounded-3 bg-light border-start border-4 border-info\">\n                                    <div class=\"d-flex justify-content-between align-items-center mb-1\">\n                                        <h6 class=\"fw-bold mb-0 text-info\">Reactante de Fase Aguda</h6>\n                                        <span class=\"badge bg-info\">PCR 9 mg/dL</span>\n                                    </div>\n                                    <p class=\"small text-muted mb-0\">La PCR elevada (>5 mg/dL) apoya el diagnóstico de apendicitis en fase avanzada.</p>\n                                </div>\n\n                                <div class=\"p-2 px-3 bg-success bg-opacity-10 rounded-pill text-center mt-2\">\n                                    <small class=\"text-white fw-bold\">\n                                        <i class=\"bi bi-shield-check me-1\"></i> EGO y PFH normales: Se descarta foco urinario y hepatopatía.\n                                    </small>\n                                </div>\n                            </div>\n                        </div>\n\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>','',0,NULL),(8,1,8,'texto','Rayos X de abdomen','<div class=\"container my-5\">\n    <div class=\"row justify-content-center\">\n        <div class=\"col-lg-11\">\n            <div class=\"card border-0 shadow-lg\" style=\"border-radius: 20px; background-color: #212529;\">\n                \n                <div class=\"card-header border-0 bg-dark d-flex justify-content-between align-items-center py-3 px-4\" style=\"border-radius: 20px 20px 0 0;\">\n                    <div class=\"d-flex align-items-center\">\n                        <div class=\"bg-primary bg-opacity-25 p-2 rounded-3 me-3\">\n                            <i class=\"bi bi-person-bounding-box text-primary fs-4\"></i>\n                        </div>\n                        <div>\n                            <h5 class=\"text-white mb-0 fw-bold\">Rayos X de Abdomen</h5>\n                            <small class=\"text-white-50 small\">Proyecciones: AP de pie y Decúbito</small>\n                        </div>\n                    </div>\n                    <span class=\"badge rounded-pill bg-secondary bg-opacity-25 text-white-50 border border-secondary border-opacity-50\">DICOM Viewer v2.0</span>\n                </div>\n\n                <div class=\"card-body p-4 p-md-5\">\n                    <div class=\"row g-4\">\n                        <div class=\"col-md-6\">\n                            <div class=\"p-2 bg-black rounded shadow-sm border border-secondary border-opacity-25\">\n                                <img src=\"../img/rayosX1.png\" class=\"img-fluid rounded\" alt=\"Rayos X Abdomen 1\" style=\"filter: contrast(110%);\">\n                                <div class=\"text-center py-2 text-white-50 small fw-bold\">PROYECCIÓN A</div>\n                            </div>\n                        </div>\n                        \n                        <div class=\"col-md-6\">\n                            <div class=\"p-2 bg-black rounded shadow-sm border border-secondary border-opacity-25\">\n                                <img src=\"../img/rayosX2.png\" class=\"img-fluid rounded\" alt=\"Rayos X Abdomen 2\" style=\"filter: contrast(110%);\">\n                                <div class=\"text-center py-2 text-white-50 small fw-bold\">PROYECCIÓN B</div>\n                            </div>\n                        </div>\n                    </div>\n\n                    <div class=\"mt-5 p-4 rounded-4 bg-white shadow-sm border-start border-4 border-info\">\n                        <h5 class=\"fw-bold text-dark mb-4 d-flex align-items-center\">\n                            <i class=\"bi bi-eyeglasses me-2 text-info\"></i> Correlación Radiológica\n                        </h5>\n                        \n                        <div class=\"row g-4\">\n                            <div class=\"col-md-4\">\n                                <div class=\"d-flex align-items-start\">\n                                    <i class=\"bi bi-1-circle text-info me-2 fs-5\"></i>\n                                    <p class=\"small text-muted mb-0\"><strong class=\"text-dark d-block\">Gas Intestinal:</strong> Discreta dilatación de asas de intestino delgado en cuadrante inferior derecho.</p>\n                                </div>\n                            </div>\n                            <div class=\"col-md-4\">\n                                <div class=\"d-flex align-items-start\">\n                                    <i class=\"bi bi-2-circle text-info me-2 fs-5\"></i>\n                                    <p class=\"small text-muted mb-0\"><strong class=\"text-dark d-block\">Niveles Hidroaéreos:</strong> Presencia de niveles en fosa ilíaca derecha (FID), sugestivos de íleo regional.</p>\n                                </div>\n                            </div>\n                            <div class=\"col-md-4\">\n                                <div class=\"d-flex align-items-start\">\n                                    <i class=\"bi bi-3-circle text-info me-2 fs-5\"></i>\n                                    <p class=\"small text-muted mb-0\"><strong class=\"text-dark d-block\">Signos Opacos:</strong> Ausencia de aire en el colon distal (recto) y posible borramiento de la línea del psoas.</p>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <div class=\"card-footer bg-dark border-0 py-3 text-center\" style=\"border-radius: 0 0 20px 20px;\">\n                    <small class=\"text-warning\">\n                        <i class=\"bi bi-exclamation-triangle me-1\"></i> Recordatorio: La radiografía tiene baja sensibilidad para apendicitis, pero ayuda a descartar obstrucción o perforación.\n                    </small>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>','',0,NULL),(9,1,9,'texto','Tomografía Computarizada (TAC o CT Scan)','<div class=\"container my-5\">\n    <div class=\"row justify-content-center\">\n        <div class=\"col-lg-11\">\n            <div class=\"card border-0 shadow-lg\" style=\"border-radius: 20px; background-color: #111111;\">\n                \n                <div class=\"card-header border-0 bg-black d-flex justify-content-between align-items-center py-3 px-4\" style=\"border-radius: 20px 20px 0 0; border-bottom: 2px solid #333 !important;\">\n                    <div class=\"d-flex align-items-center\">\n                        <div class=\"bg-success bg-opacity-25 p-2 rounded-3 me-3\">\n                            <i class=\"bi bi-box-seam-fill text-success fs-4\"></i>\n                        </div>\n                        <div>\n                            <h5 class=\"text-black mb-0 fw-bold\">Tomografía Computarizada de Abdomen</h5>\n                            <small class=\"text-black-50\">Visualización Avanzada con Contraste</small>\n                        </div>\n                    </div>\n                    <div class=\"text-end\">\n                        <span class=\"badge bg-secondary bg-opacity-25 text-white-50 border border-secondary border-opacity-50\">3D Reconst. v4.1</span>\n                    </div>\n                </div>\n\n                <div class=\"card-body p-4 p-md-5\">\n                    <div class=\"row g-0\">\n                        \n                        <div class=\"col-xl-7 order-xl-1 pe-xl-4 mb-4 mb-xl-0\">\n                            <div class=\"row g-3\">\n                                <div class=\"col-md-7 col-xl-12\">\n                                    <div class=\"p-2 bg-black rounded shadow-sm border border-secondary border-opacity-25 position-relative\">\n                                        <img src=\"../img/rayosX3.png\" class=\"img-fluid rounded\" alt=\"TAC Abdomen Coronal\" style=\"filter: contrast(110%) brightness(105%);\">\n                                        <div class=\"position-absolute bottom-0 start-0 m-2 badge bg-dark bg-opacity-75 text-white-50 small fw-bold\">CORONAL</div>\n                                    </div>\n                                </div>\n                                \n                                <div class=\"col-md-5 col-xl-12\">\n                                    <div class=\"p-2 bg-black rounded shadow-sm border border-secondary border-opacity-25 position-relative\">\n                                        <img src=\"../img/rayosX4.png\" class=\"img-fluid rounded\" alt=\"TAC Abdomen Axial\" style=\"filter: contrast(110%) brightness(105%);\">\n                                        <div class=\"position-absolute bottom-0 start-0 m-2 badge bg-dark bg-opacity-75 text-white-50 small fw-bold\">AXIAL</div>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n\n                        <div class=\"col-xl-5 order-xl-2\">\n                            <div class=\"h-100 p-4 rounded-4 bg-white shadow-sm\">\n                                <div class=\"d-flex align-items-center mb-4 border-bottom pb-3\">\n                                    <i class=\"bi bi- eyeglasses me-3 text-success fs-3\"></i>\n                                    <div>\n                                        <h5 class=\"fw-bold text-dark mb-0 tracking-tight\">Análisis de Imagen</h5>\n                                        <p class=\"text-muted small mb-0 mt-1\">Haga correlación clínica con los siguientes hallazgos</p>\n                                    </div>\n                                </div>\n                                \n                                <div class=\"d-flex flex-column gap-3\">\n                                    \n                                    <div class=\"d-flex align-items-start p-3 bg-light rounded-3 border-start border-4 border-danger\">\n                                        <i class=\"bi bi-arrows-expand text-danger me-3 fs-5 mt-1\"></i>\n                                        <div>\n                                            <h6 class=\"fw-bold mb-1 text-danger d-flex align-items-center justify-content-between\">\n                                                <span>Diámetro Aumentado</span>\n                                                <span class=\"badge bg-danger rounded-pill\">10 mm</span>\n                                            </td>\n                                            </h6>\n                                            <p class=\"small text-muted mb-0\">Un diámetro >7 mm en la TAC es altamente predictivo de apendicitis aguda en el contexto clínico adecuado.</p>\n                                        </div>\n                                    </div>\n\n                                    <div class=\"d-flex align-items-start p-3 bg-light rounded-3 border-start border-4 border-warning\">\n                                        <i class=\"bi bi-layers-half text-warning text-dark me-3 fs-5 mt-1\"></i>\n                                        <div>\n                                            <h6 class=\"fw-bold mb-1 text-warning text-dark\">Engrosamiento Mural</h6>\n                                            <p class=\"small text-muted mb-0\">Sugiere inflamación y edema de la mucosa apendicular, a menudo con realce al contraste.</p>\n                                        </div>\n                                    </div>\n\n                                    <div class=\"d-flex align-items-start p-3 bg-light rounded-3 border-start border-4 border-info\">\n                                        <i class=\"bi bi-droplet-fill text-info me-3 fs-5 mt-1\"></i>\n                                        <div>\n                                            <h6 class=\"fw-bold mb-1 text-info\">Estriación de Grasa</h6>\n                                            <p class=\"small text-muted mb-0\">\"Grasa sucia\" (aumento de la densidad peri-apendicular), indicativo de inflamación circundante.</p>\n                                        </div>\n                                    </div>\n\n                                    <div class=\"d-flex align-items-start p-3 bg-light rounded-3 border-start border-4 border-primary\">\n                                        <i class=\"bi bi-moisture text-primary me-3 fs-5 mt-1\"></i>\n                                        <div>\n                                            <h6 class=\"fw-bold mb-1 text-primary\">Líquido Libre Pericecal</h6>\n                                            <p class=\"small text-muted mb-0\">Pequeña colección fluida cerca del ciego, sugiriendo complicación en fase temprana.</p>\n                                        </div>\n                                    </div>\n\n                                    <div class=\"d-flex align-items-start p-3 bg-light rounded-3 border-start border-4 border-secondary\">\n                                        <i class=\"bi bi-shield-slash text-secondary me-3 fs-5 mt-1\"></i>\n                                        <div>\n                                            <h6 class=\"fw-bold mb-1 text-secondary\">Ausencia de Absceso</h6>\n                                            <p class=\"small text-muted mb-0\">Dato crucial para la planificación quirúrgica: no se visualiza colección organizada.</p>\n                                        </div>\n                                    </div>\n\n                                </div>\n                            </div>\n                        </div>\n\n                    </div>\n                </div>\n\n                <div class=\"card-footer bg-black border-0 py-3 text-center\" style=\"border-radius: 0 0 20px 20px;\">\n                    <small class=\"text-success fw-bold\">\n                        <i class=\"bi bi-shield-check me-1\"></i> La TAC de Abdomen con contraste es el estándar de oro diagnóstico con sensibilidad y especificidad >95%.\n                    </small>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>','',0,NULL),(10,1,10,'texto','Conclusión radiológica','<div class=\"container my-5\">\n    <div class=\"row justify-content-center\">\n        <div class=\"col-lg-10\">\n            <div class=\"card border-0 shadow-lg overflow-hidden\" style=\"border-radius: 25px;\">\n                <div class=\"row g-0\">\n                    \n                    <div class=\"col-md-4 bg-dark d-flex flex-column align-items-center justify-content-center p-4 text-center\">\n                        <div class=\"bg-success bg-opacity-10 p-4 rounded-circle mb-3 border border-success border-opacity-25\">\n                            <i class=\"bi bi-journal-check text-success display-4\"></i>\n                        </div>\n                        <h4 class=\"text-white fw-bold\">Dictamen Final</h4>\n                        <div class=\"badge bg-success px-3 py-2 rounded-pill mt-2\">Hallazgos Concluyentes</div>\n                    </div>\n\n                    <div class=\"col-md-8 bg-white p-4 p-md-5\">\n                        <div class=\"d-flex justify-content-between align-items-start mb-4\">\n                            <div>\n                                <h6 class=\"text-muted text-uppercase fw-bold mb-1\" style=\"letter-spacing: 1px;\">Servicio de Radiodiagnóstico</h6>\n                                <h2 class=\"fw-bold text-dark\">Conclusión Radiológica</h2>\n                            </div>\n                            <img src=\"https://cdn-icons-png.flaticon.com/512/3774/3774299.png\" alt=\"Sello\" style=\"width: 60px; opacity: 0.8; filter: grayscale(100%);\">\n                        </div>\n\n                        <div class=\"space-y-4\">\n                            <div class=\"d-flex align-items-center p-3 mb-3 rounded-4 bg-danger bg-opacity-10 border-start border-4 border-danger\">\n                                <i class=\"bi bi-exclamation-diamond-fill text-danger fs-3 me-3\"></i>\n                                <div>\n                                    <h5 class=\"fw-bold text-dark mb-0\">Apendicitis aguda complicada</h5>\n                                    <span class=\"badge bg-danger bg-opacity-75\">Fase III (Fibrinopurulenta)</span>\n                                </div>\n                            </div>\n\n                            <div class=\"d-flex align-items-center p-3 rounded-4 bg-dark bg-opacity-10 border-start border-4 border-dark\">\n                                <i class=\"bi bi-virus2 text-dark fs-3 me-3\"></i>\n                                <div>\n                                    <h5 class=\"fw-bold text-white mb-0\">Probable apendicitis gangrenosa</h5>\n                                    <p class=\"small text-white mb-0\">Correlación con estriación grasa y líquido libre pericecal.</p>\n                                </div>\n                            </div>\n                        </div>\n\n                        <div class=\"mt-5 pt-4 border-top d-flex align-items-center justify-content-between\">\n                            <div>\n                                <p class=\"mb-0 fw-bold text-dark\">Dr. Radiólogo de Turno</p>\n                                <small class=\"text-muted\">Céd. Especialidad 7654321</small>\n                            </div>\n                            <div class=\"text-end\">\n                                <small class=\"d-block text-muted mb-1\">Validación Electrónica</small>\n                                <i class=\"bi bi-qr-code fs-2 text-dark\"></i>\n                            </div>\n                        </div>\n                    </div>\n\n                </div>\n            </div>\n\n        </div>\n    </div>\n</div>','',0,NULL),(11,2,1,'texto','Caso Simulado','<video width=\"100%\" controls autoplay>\n\n    <source\n        src=\"../video/caso.mp4\"\n        type=\"video/mp4\">\n\n</video>\n\n','',0,NULL),(12,3,1,'Objetivos','Introducción','<div class=\"container my-5\">\n    <div class=\"row g-4\">\n        <!-- Tarjeta de Objetivos Educativos -->\n        <div class=\"col-md-7\">\n            <div class=\"card h-100 border-0 shadow-sm\" style=\"border-radius: 15px; border-left: 5px solid #0d6efd !important;\">\n                <div class=\"card-body p-4\">\n                    <div class=\"d-flex align-items-center mb-3\">\n                        <div class=\"bg-primary bg-opacity-10 p-2 rounded-circle me-3\">\n                            <i class=\"bi bi-journal-check text-primary fs-4\"></i>\n                        </div>\n                        <h2 class=\"card-title mb-0 fw-bold text-dark\">Objetivo educativo del módulo</h2>\n                    </div>\n                    <ul class=\"list-group list-group-flush\">\n                        <li class=\"list-group-item border-0 px-0 d-flex align-items-start\">\n                            <span class=\"badge bg-primary rounded-pill me-2 mt-1\">1</span>\n                            <span>Reconocer los datos clínicos sugestivos de <strong>apendicitis aguda complicada</strong>.</span>\n                        </li>\n                        <li class=\"list-group-item border-0 px-0 d-flex align-items-start\">\n                            <span class=\"badge bg-primary rounded-pill me-2 mt-1\">2</span>\n                            <span>Aplicar escalas clínicas y de riesgo para la toma de decisiones.</span>\n                        </li>\n                        <li class=\"list-group-item border-0 px-0 d-flex align-items-start\">\n                            <span class=\"badge bg-primary rounded-pill me-2 mt-1\">3</span>\n                            <span>Seleccionar estudios diagnósticos adecuados según el contexto.</span>\n                        </li>\n                        <li class=\"list-group-item border-0 px-0 d-flex align-items-start\">\n                            <span class=\"badge bg-primary rounded-pill me-2 mt-1\">4</span>\n                            <span>Integrar un plan terapéutico oportuno.</span>\n                        </li>\n                        <li class=\"list-group-item border-0 px-0 d-flex align-items-start\">\n                            <span class=\"badge bg-primary rounded-pill me-2 mt-1\">5</span>\n                            <span>Identificar hallazgos quirúrgicos y evaluar la evolución posoperatoria.</span>\n                        </li>\n                    </ul>\n                </div>\n            </div>\n        </div>\n\n        <!-- Tarjeta de Perfil del Usuario -->\n        <div class=\"col-md-5\">\n            <div class=\"card h-100 border-0 shadow-sm bg-light\" style=\"border-radius: 15px;\">\n                <div class=\"card-body p-4\">\n                    <div class=\"d-flex align-items-center mb-3\">\n                        <div class=\"bg-secondary bg-opacity-10 p-2 rounded-circle me-3\">\n                            <i class=\"bi bi-people-fill text-secondary fs-4\"></i>\n                        </div>\n                        <h2 class=\"card-title mb-0 fw-bold text-dark\">Perfil del usuario</h2>\n                    </div>\n                    <div class=\"d-flex flex-wrap gap-2\">\n                        <span class=\"badge text-secondary border border-secondary rounded-pill p-2 px-3\">Médicos generales</span>\n                        <span class=\"badge text-secondary border border-secondary rounded-pill p-2 px-3\">Médicos internos de pregrado</span>\n                        <span class=\"badge text-secondary border border-secondary rounded-pill p-2 px-3\">Residentes de urgencias</span>\n                        <span class=\"badge text-secondary border border-secondary rounded-pill p-2 px-3\">Cirugía general</span>\n                        <span class=\"badge text-secondary border border-secondary rounded-pill p-2 px-3\">Personal en formación</span>\n                    </div>\n                    <hr class=\"my-3 opacity-10\">\n                    <p class=\"small text-muted mb-0\">\n                        <i class=\"bi bi-info-circle me-1\"></i> Contenido diseñado para fortalecer la toma de decisiones clínicas.\n                    </p>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>','',0,NULL),(13,1,11,'pregunta','¿Cuál es la  posición anatómica más frecuente del apéndice?','<div class=\"container my-5\">\n\n    <div class=\"mb-4\">\n\n        <p class=\"text-muted small\">\n\n            Seleccione la opción que considere correcta basándose en la incidencia epidemiológica.\n\n        </p>\n\n    </div>\n\n    <div id=\"retroalimentacion\" class=\"mb-4\"></div>\n\n    <div class=\"d-grid gap-3\">\n\n        <!-- A -->\n        <button\n\n            class=\"btn btn-outline-primary text-start p-3 border-2 shadow-sm d-flex align-items-center\"\n\n            style=\"border-radius: 12px; transition: 0.3s;\"\n\n            onclick=\"\n\n    guardarRespuesta(\'A\',1);\n\n    document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                    <div class=\'card border-0 shadow-sm bg-success bg-opacity-10 p-4 animate__animated animate__fadeIn\' style=\'border-radius: 15px;\'>\n\n                        <div class=\'d-flex align-items-center text-success mb-2\'>\n\n                            <i class=\'bi bi-check-circle-fill fs-4 me-2\'></i>\n\n                            <h5 class=\'mb-0 fw-bold\'>\n\n                                ¡Correcto!\n\n                            </h5>\n\n                        </div>\n\n                        <hr class=\'border-success opacity-25\'>\n\n                        <p class=\'text-dark\'>\n\n                            <strong>\n\n                                Respuesta correcta: A. Retrocecal\n\n                            </strong>\n\n                        </p>\n\n                        <p class=\'mb-2 small text-dark\'>\n\n                            La posición anatómica más frecuente del apéndice cecal es la <strong>retrocecal</strong>.\n\n                        </p>\n\n                        <div class=\'row g-2 mt-1\'>\n\n                            <div class=\'col-6\'>\n\n                                <span class=\'badge bg-success w-100 py-2\'>\n\n                                    74% Retrocecal\n\n                                </span>\n\n                            </div>\n\n                            <div class=\'col-6\'>\n\n                                <span class=\'badge bg-secondary w-100 py-2\'>\n\n                                    21% Pélvica\n\n                                </span>\n\n                            </div>\n\n                            <div class=\'col-4\'>\n\n                                <span class=\'badge bg-light text-dark border w-100 py-2\'>\n\n                                    2% Paracecal\n\n                                </span>\n\n                            </div>\n\n                            <div class=\'col-4\'>\n\n                                <span class=\'badge bg-light text-dark border w-100 py-2\'>\n\n                                    1.5% Subcecal\n\n                                </span>\n\n                            </div>\n\n                            <div class=\'col-4\'>\n\n                                <span class=\'badge bg-light text-dark border w-100 py-2\'>\n\n                                    1.5% Pre/Postileal\n\n                                </span>\n\n                            </div>\n\n                        </div>\n\n                    </div>\n\n                `;\n\n            \">\n\n            <span class=\"badge bg-light text-primary border me-3 py-2 px-3\">\n\n                A\n\n            </span>\n\n            <span class=\"fw-medium\">\n\n                Retrocecal\n\n            </span>\n\n        </button>\n\n        <!-- B -->\n        <button\n\n            class=\"btn btn-outline-primary text-start p-3 border-2 shadow-sm d-flex align-items-center\"\n\n            style=\"border-radius: 12px; transition: 0.3s;\"\n\n            onclick=\"\n\n                if(respuestaContestada) return;\n\n                respuestaContestada = true;\n\n                guardarRespuesta(\'B\',0);\n\n                document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                    <div class=\'card border-0 shadow-sm bg-danger bg-opacity-10 p-4 animate__animated animate__fadeIn\' style=\'border-radius: 15px;\'>\n\n                        <div class=\'d-flex align-items-center text-danger mb-2\'>\n\n                            <i class=\'bi bi-info-circle-fill fs-4 me-2\'></i>\n\n                            <h5 class=\'mb-0 fw-bold\'>\n\n                                Retroalimentación\n\n                            </h5>\n\n                        </div>\n\n                        <hr class=\'border-danger opacity-25\'>\n\n                        <p class=\'text-dark\'>\n\n                            <strong>\n\n                                Respuesta correcta: A\n\n                            </strong>\n\n                        </p>\n\n                        <p class=\'mb-0 small text-dark opacity-75\'>\n\n                            La posición anatómica más frecuente del apéndice cecal es la retrocecal, presente en aproximadamente el 74% de los pacientes.\n\n                        </p>\n\n                    </div>\n\n                `;\n\n            \">\n\n            <span class=\"badge bg-light text-primary border me-3 py-2 px-3\">\n\n                B\n\n            </span>\n\n            <span class=\"fw-medium\">\n\n                Pélvica\n\n            </span>\n\n        </button>\n\n        <!-- C -->\n        <button\n\n            class=\"btn btn-outline-primary text-start p-3 border-2 shadow-sm d-flex align-items-center\"\n\n            style=\"border-radius: 12px; transition: 0.3s;\"\n\n            onclick=\"\n\n                if(respuestaContestada) return;\n\n                respuestaContestada = true;\n\n                guardarRespuesta(\'C\',0);\n\n                document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                    <div class=\'card border-0 shadow-sm bg-danger bg-opacity-10 p-4 animate__animated animate__fadeIn\' style=\'border-radius: 15px;\'>\n\n                        <div class=\'d-flex align-items-center text-danger mb-2\'>\n\n                            <i class=\'bi bi-info-circle-fill fs-4 me-2\'></i>\n\n                            <h5 class=\'mb-0 fw-bold\'>\n\n                                Retroalimentación\n\n                            </h5>\n\n                        </div>\n\n                        <hr class=\'border-danger opacity-25\'>\n\n                        <p class=\'text-dark\'>\n\n                            <strong>\n\n                                Respuesta correcta: A\n\n                            </strong>\n\n                        </p>\n\n                        <p class=\'mb-0 small text-dark opacity-75\'>\n\n                            Incorrecto. La posición paracecal representa únicamente cerca del 2% de los casos observados.\n\n                        </p>\n\n                    </div>\n\n                `;\n\n            \">\n\n            <span class=\"badge bg-light text-primary border me-3 py-2 px-3\">\n\n                C\n\n            </span>\n\n            <span class=\"fw-medium\">\n\n                Paracecal\n\n            </span>\n\n        </button>\n\n        <!-- D -->\n        <button\n\n            class=\"btn btn-outline-primary text-start p-3 border-2 shadow-sm d-flex align-items-center\"\n\n            style=\"border-radius: 12px; transition: 0.3s;\"\n\n            onclick=\"\n\n                if(respuestaContestada) return;\n\n                respuestaContestada = true;\n\n                guardarRespuesta(\'D\',0);\n\n                document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                    <div class=\'card border-0 shadow-sm bg-danger bg-opacity-10 p-4 animate__animated animate__fadeIn\' style=\'border-radius: 15px;\'>\n\n                        <div class=\'d-flex align-items-center text-danger mb-2\'>\n\n                            <i class=\'bi bi-info-circle-fill fs-4 me-2\'></i>\n\n                            <h5 class=\'mb-0 fw-bold\'>\n\n                                Retroalimentación\n\n                            </h5>\n\n                        </div>\n\n                        <hr class=\'border-danger opacity-25\'>\n\n                        <p class=\'text-dark\'>\n\n                            <strong>\n\n                                Respuesta correcta: A\n\n                            </strong>\n\n                        </p>\n\n                        <p class=\'mb-0 small text-dark opacity-75\'>\n\n                            La posición subcecal es poco frecuente, ocurriendo en aproximadamente el 1.5% de los casos clínicos.\n\n                        </p>\n\n                    </div>\n\n                `;\n\n            \">\n\n            <span class=\"badge bg-light text-primary border me-3 py-2 px-3\">\n\n                D\n\n            </span>\n\n            <span class=\"fw-medium\">\n\n                Subcecal\n\n            </span>\n\n        </button>\n\n    </div>\n\n</div>','',1,'A'),(14,1,12,'texto','Integración diagnóstica','<div class=\"container my-5\">\n    <div class=\"row justify-content-center\">\n        <div class=\"col-lg-10\">\n            <div class=\"card border-0 shadow-lg\" style=\"border-radius: 25px; background: linear-gradient(135deg, #ffffff 0%, #f9faff 100%);\">\n                <div class=\"card-body p-4 p-md-5\">\n                    \n                    <div class=\"text-center mb-5\">\n                        <span class=\"badge bg-primary bg-opacity-10 text-white px-3 py-2 rounded-pill mb-2 fw-bold\">Fase Final de Diagnóstico</span>\n                        <h2 class=\"fw-bold text-dark\">Integración Diagnóstica</h2>\n                        <div class=\"mx-auto bg-primary opacity-25\" style=\"height: 3px; width: 60px; border-radius: 2px;\"></div>\n                    </div>\n\n                    <div class=\"position-relative\">\n                        <div class=\"position-absolute start-50 translate-middle-x h-100 bg-light d-none d-md-block\" style=\"width: 4px; top: 0;\"></div>\n\n                        <div class=\"row g-4 position-relative\">\n                            \n                            <div class=\"col-md-6 text-md-end\">\n                                <div class=\"p-4 rounded-4 bg-white shadow-sm border-end border-4 border-primary animate__animated animate__fadeInLeft\">\n                                    <div class=\"d-flex align-items-center justify-content-md-end mb-2\">\n                                        <h5 class=\"fw-bold mb-0 me-3 order-2 order-md-1\">Diagnóstico Clínico</h5>\n                                        <div class=\"bg-primary text-white rounded-circle d-flex align-items-center justify-content-center order-1 order-md-2\" style=\"width: 40px; height: 40px;\">\n                                            <i class=\"bi bi-person-check-fill\"></i>\n                                        </div>\n                                    </div>\n                                    <p class=\"small text-muted mb-0\">Basado en la tríada de Murphy y los hallazgos de irritación peritoneal localizados en fosa ilíaca derecha.</p>\n                                </div>\n                            </div>\n\n                            <div class=\"col-md-6 d-none d-md-block\"></div> <div class=\"col-md-6 d-none d-md-block\"></div> <div class=\"col-md-6\">\n                                <div class=\"p-4 rounded-4 bg-white shadow-sm border-start border-4 border-warning animate__animated animate__fadeInRight\">\n                                    <div class=\"d-flex align-items-center mb-2\">\n                                        <div class=\"bg-warning text-dark rounded-circle d-flex align-items-center justify-content-center me-3\" style=\"width: 40px; height: 40px;\">\n                                            <i class=\"bi bi-bar-chart-line-fill\"></i>\n                                        </div>\n                                        <h5 class=\"fw-bold mb-0\">Escala AIR: Alto Riesgo</h5>\n                                    </div>\n                                    <p class=\"small text-muted mb-0\">Puntuación sugerente de alta probabilidad de apendicitis aguda, justificando la intervención inmediata.</p>\n                                </div>\n                            </div>\n\n                            <div class=\"col-md-6 text-md-end\">\n                                <div class=\"p-4 rounded-4 bg-white shadow-sm border-end border-4 border-info animate__animated animate__fadeInLeft\">\n                                    <div class=\"d-flex align-items-center justify-content-md-end mb-2\">\n                                        <h5 class=\"fw-bold mb-0 me-3 order-2 order-md-1\">TC Confirmatoria</h5>\n                                        <div class=\"bg-info text-white rounded-circle d-flex align-items-center justify-content-center order-1 order-md-2\" style=\"width: 40px; height: 40px;\">\n                                            <i class=\"bi bi-scan\"></i>\n                                        </div>\n                                    </div>\n                                    <p class=\"small text-muted mb-0\">Evidencia de proceso inflamatorio apendicular (10mm), estriación de grasa y ausencia de gas distal.</p>\n                                </div>\n                            </div>\n\n                        </div>\n                    </div>\n\n                    <div class=\"mt-5 p-4 bg-dark text-white rounded-4 shadow-sm\">\n                        <div class=\"row align-items-center\">\n                            <div class=\"col-md-8\">\n                                <p class=\"mb-0 italic opacity-75\">\n                                    \"La correlación de los tres pilares diagnósticos establece una indicación quirúrgica absoluta, minimizando el riesgo de una laparotomía negativa.\"\n                                </p>\n                            </div>\n                            <div class=\"col-md-4 text-md-end mt-3 mt-md-0\">\n                                <span class=\"badge bg-light text-dark px-4 py-2 fw-bold\">CASO INTEGRADO</span>\n                            </div>\n                        </div>\n                    </div>\n\n                </div>\n            </div>\n        </div>\n    </div>\n</div>','',0,NULL),(15,1,13,'pregunta','¿Cuál de las siguientes escalas incorpora proteína C reactiva (PCR) como parte de sus variables para predecir apendicitis complicada?','<div class=\"container my-4\">\n\n    <!-- BOTONES SUPERIORES -->\n    <div class=\"row g-2 mb-4 justify-content-center\">\n\n        <div class=\"col-6 col-md-3\">\n\n            <button\n                class=\"btn btn-outline-info w-100 py-2 shadow-sm border-2\"\n                style=\"border-radius:15px;\"\n                onclick=\"window.open(\'https://www.sasappendicitis.com/\',\'_blank\')\">\n\n                <i class=\"bi bi-calculator d-block fs-4\"></i>\n\n                <span class=\"fw-bold small\">\n                    SAS 2.0\n                </span>\n\n            </button>\n\n        </div>\n\n        <div class=\"col-6 col-md-3\">\n\n            <button\n                class=\"btn btn-outline-success w-100 py-2 shadow-sm border-2\"\n                style=\"border-radius:15px;\"\n                onclick=\"window.open(\'https://www.mdcalc.com/calc/617/alvarado-score-acute-appendicitis\',\'_blank\')\">\n\n                <i class=\"bi bi-activity d-block fs-4\"></i>\n\n                <span class=\"fw-bold small\">\n                    Alvarado\n                </span>\n\n            </button>\n\n        </div>\n\n        <div class=\"col-6 col-md-3\">\n\n            <button\n                class=\"btn btn-outline-primary w-100 py-2 shadow-sm border-2\"\n                style=\"border-radius:15px;\"\n                onclick=\"window.open(\'https://www.mdcalc.com/calc/3984/appendicitis-inflammatory-response-air-score\',\'_blank\')\">\n\n                <i class=\"bi bi-moisture d-block fs-4\"></i>\n\n                <span class=\"fw-bold small\">\n                    AIR Score\n                </span>\n\n            </button>\n\n        </div>\n\n        <div class=\"col-6 col-md-3\">\n\n            <button\n                class=\"btn btn-outline-dark w-100 py-2 shadow-sm border-2\"\n                style=\"border-radius:15px;\"\n                onclick=\"window.open(\'https://www.mdcalc.com/calc/3166/ripasa-score-acute-appendicitis\',\'_blank\')\">\n\n                <i class=\"bi bi-clipboard2-pulse d-block fs-4\"></i>\n\n                <span class=\"fw-bold small\">\n                    RIPASA\n                </span>\n\n            </button>\n\n        </div>\n\n    </div>\n\n    <!-- TITULO -->\n    <div class=\"text-center mb-4\">\n\n        <h5\n            class=\"fw-bold text-muted text-uppercase small\"\n            style=\"letter-spacing: 1px;\">\n\n            Evaluación de Riesgo\n\n        </h5>\n\n    </div>\n\n    <!-- RETRO -->\n    <div id=\"retroalimentacion\" class=\"mb-4\"></div>\n\n    <!-- RESPUESTAS -->\n    <div class=\"row g-3\">\n\n        <!-- A -->\n        <div class=\"col-md-6\">\n\n            <button\n                class=\"btn btn-outline-primary text-start p-3 w-100 shadow-sm\"\n                style=\"border-radius: 12px;\"\n\n                onclick=\"\n\n                    guardarRespuesta(\'A\',1);\n\n                    document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                    <div\n                        class=\'alert alert-success border-0 shadow-sm animate__animated animate__fadeIn\'\n                        style=\'border-radius:15px;\'>\n\n                        <h4 class=\'fw-bold\'>\n\n                            <i class=\'bi bi-check-circle-fill me-2\'></i>\n\n                            ¡Correcto!\n\n                        </h4>\n\n                        <hr>\n\n                        <p class=\'mb-2\'>\n\n                            <strong>\n                                Respuesta correcta: A\n                            </strong>\n\n                        </p>\n\n                        <p class=\'small mb-0\'>\n\n                            La escala AIR incorpora la\n                            <strong>PCR</strong>\n                            como variable importante.\n                            Su elevación se asocia con\n                            cuadros complicados y gangrenosos.\n\n                        </p>\n\n                    </div>\n\n                    `;\n                \">\n\n                <span class=\"badge bg-dark me-2\">\n                    A\n                </span>\n\n                Escala AIR\n\n            </button>\n\n        </div>\n\n        <!-- B -->\n        <div class=\"col-md-6\">\n\n            <button\n                class=\"btn btn-outline-primary text-start p-3 w-100 shadow-sm\"\n                style=\"border-radius: 12px;\"\n\n                onclick=\"\n\n                    guardarRespuesta(\'B\',0);\n\n                    document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                    <div\n                        class=\'alert alert-danger border-0 shadow-sm animate__animated animate__fadeIn\'\n                        style=\'border-radius:15px;\'>\n\n                        <h4 class=\'fw-bold\'>\n\n                            <i class=\'bi bi-x-circle-fill me-2\'></i>\n\n                            Retroalimentación\n\n                        </h4>\n\n                        <hr>\n\n                        <p class=\'mb-2\'>\n\n                            <strong>\n                                Respuesta correcta: A\n                            </strong>\n\n                        </p>\n\n                        <p class=\'small mb-0\'>\n\n                            La escala de Alvarado no incluye PCR.\n                            Se basa principalmente en clínica\n                            y leucocitosis.\n\n                        </p>\n\n                    </div>\n\n                    `;\n                \">\n\n                <span class=\"badge bg-dark me-2\">\n                    B\n                </span>\n\n                Escala Alvarado\n\n            </button>\n\n        </div>\n\n        <!-- C -->\n        <div class=\"col-md-6\">\n\n            <button\n                class=\"btn btn-outline-primary text-start p-3 w-100 shadow-sm\"\n                style=\"border-radius: 12px;\"\n\n                onclick=\"\n\n                    guardarRespuesta(\'C\',0);\n\n                    document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                    <div\n                        class=\'alert alert-danger border-0 shadow-sm animate__animated animate__fadeIn\'\n                        style=\'border-radius:15px;\'>\n\n                        <h4 class=\'fw-bold\'>\n\n                            <i class=\'bi bi-x-circle-fill me-2\'></i>\n\n                            Retroalimentación\n\n                        </h4>\n\n                        <hr>\n\n                        <p class=\'mb-2\'>\n\n                            <strong>\n                                Respuesta correcta: A\n                            </strong>\n\n                        </p>\n\n                        <p class=\'small mb-0\'>\n\n                            La escala de Fenyo no utiliza\n                            proteína C reactiva como parte\n                            central de su algoritmo.\n\n                        </p>\n\n                    </div>\n\n                    `;\n                \">\n\n                <span class=\"badge bg-dark me-2\">\n                    C\n                </span>\n\n                Escala de Fenyo\n\n            </button>\n\n        </div>\n\n        <!-- D -->\n        <div class=\"col-md-6\">\n\n            <button\n                class=\"btn btn-outline-primary text-start p-3 w-100 shadow-sm\"\n                style=\"border-radius: 12px;\"\n\n                onclick=\"\n\n                    guardarRespuesta(\'D\',0);\n\n                    document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                    <div\n                        class=\'alert alert-danger border-0 shadow-sm animate__animated animate__fadeIn\'\n                        style=\'border-radius:15px;\'>\n\n                        <h4 class=\'fw-bold\'>\n\n                            <i class=\'bi bi-x-circle-fill me-2\'></i>\n\n                            Retroalimentación\n\n                        </h4>\n\n                        <hr>\n\n                        <p class=\'mb-2\'>\n\n                            <strong>\n                                Respuesta correcta: A\n                            </strong>\n\n                        </p>\n\n                        <p class=\'small mb-0\'>\n\n                            La escala de Ohmann evalúa\n                            variables clínicas, pero no\n                            utiliza PCR como predictor principal.\n\n                        </p>\n\n                    </div>\n\n                    `;\n                \">\n\n                <span class=\"badge bg-dark me-2\">\n                    D\n                </span>\n\n                Escala de Ohmann\n\n            </button>\n\n        </div>\n\n    </div>\n\n</div>','',1,'A'),(16,1,14,'texto','Diagnóstico final','<div class=\"container my-5\">\n    <div class=\"row justify-content-center\">\n        <div class=\"col-lg-10\">\n            \n            <div class=\"card border-0 shadow-lg overflow-hidden\" style=\"border-radius: 25px;\">\n                <div class=\"row g-0\">\n                    \n                    <div class=\"col-md-1 bg-danger d-flex align-items-center justify-content-center\">\n                        <div class=\"text-white fw-bold\" style=\"writing-mode: vertical-lr; transform: rotate(180deg); letter-spacing: 2px;\">\n                            CRÍTICO • QUIRÚRGICO\n                        </div>\n                    </div>\n\n                    <div class=\"col-md-11 bg-white p-4 p-md-5\">\n                        <div class=\"d-flex align-items-start justify-content-between mb-4\">\n                            <div>\n                                <h6 class=\"text-danger fw-bold text-uppercase mb-1\" style=\"letter-spacing: 1px;\">Correlación Anatomopatológica</h6>\n                                <h2 class=\"fw-bold text-dark\">Diagnóstico Final</h2>\n                            </div>\n                            <div class=\"bg-danger bg-opacity-10 p-3 rounded-4\">\n                                <i class=\"bi bi-clipboard-pulse text-danger fs-1\"></i>\n                            </div>\n                        </div>\n\n                        <div class=\"p-4 rounded-4 mb-4\" style=\"background-color: #fff5f5; border-left: 6px solid #dc3545;\">\n                            <h4 class=\"fw-bold text-danger mb-2\">Apendicitis aguda fase III (gangrenosa)</h4>\n                            <div class=\"d-flex align-items-center\">\n                                <span class=\"badge bg-danger px-3 py-2 rounded-pill me-2\">Compromiso Vascular</span>\n                                <span class=\"badge bg-outline-danger border border-danger text-danger px-3 py-2 rounded-pill\">Urgencia Quirúrgica</span>\n                            </div>\n                        </div>\n\n                        <div class=\"row align-items-center bg-light p-3 rounded-4 mx-0\">\n                            <div class=\"col-auto\">\n                                <div class=\"bg-white p-2 rounded-circle shadow-sm\">\n                                    <i class=\"bi bi-shield-check text-success fs-4\"></i>\n                                </div>\n                            </div>\n                            <div class=\"col\">\n                                <h6 class=\"fw-bold mb-0 text-dark\">Sin perforación evidente</h6>\n                                <p class=\"small text-muted mb-0\">Integridad de la pared apendicular conservada a pesar de la necrosis transmural.</p>\n                            </div>\n                        </div>\n\n                        <div class=\"mt-5 d-flex justify-content-between align-items-end\">\n                            <div class=\"text-muted small\">\n                                <p class=\"mb-1\"><i class=\"bi bi-calendar3 me-2\"></i>Fecha de registro: 10 de Mayo, 2026</p>\n                                <p class=\"mb-0\"><i class=\"bi bi-clock me-2\"></i>Estatus: Confirmado por hallazgo macroscópico</p>\n                            </div>\n                            <div class=\"opacity-50\">\n                                <i class=\"bi bi-fingerprint fs-1\"></i>\n                            </div>\n                        </div>\n                    </div>\n\n                </div>\n            </div>\n\n            <div class=\"alert mt-4 border-0 bg-dark text-white text-center shadow-sm\" style=\"border-radius: 15px;\">\n                <i class=\"bi bi-info-circle text-warning me-2\"></i>\n                La <strong>Fase III</strong> se caracteriza por la presencia de microperforaciones y compromiso del retorno venoso/arterial.\n            </div>\n\n        </div>\n    </div>\n</div>','',0,NULL),(17,1,15,'pregunta','¿Cuál es el siguiente paso terapéutico ideal?','<div class=\"container my-4\">\n\n    <div class=\"row justify-content-center mb-4\">\n\n        <div class=\"col-md-10 text-center\">\n\n            <span\n                class=\"badge bg-white bg-opacity-10 text-danger px-3 py-2 rounded-pill mb-2 fw-bold\">\n\n                Fase de Resolución\n\n            </span>\n\n\n        </div>\n\n    </div>\n\n    <!-- RETRO -->\n    <div id=\"retroalimentacion\" class=\"mb-4\"></div>\n\n    <!-- RESPUESTAS -->\n    <div class=\"row g-3\">\n\n        <!-- A -->\n        <div class=\"col-md-6\">\n\n            <button\n                class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2 d-flex align-items-center\"\n                style=\"border-radius: 15px;\"\n\n                onclick=\"\n\n                    guardarRespuesta(\'A\',0);\n\n                    document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                    <div\n                        class=\'alert alert-danger border-0 shadow-sm animate__animated animate__fadeInUp\'\n                        style=\'border-radius:20px; background-color:#fff5f5;\'>\n\n                        <div class=\'d-flex align-items-center mb-2\'>\n\n                            <i class=\'bi bi-x-circle-fill text-danger fs-4 me-2\'></i>\n\n                            <h5 class=\'fw-bold mb-0\'>\n                                Retroalimentación\n                            </h5>\n\n                        </div>\n\n                        <hr>\n\n                        <p class=\'mb-2\'>\n\n                            <strong>\n                                Respuesta correcta: B\n                            </strong>\n\n                        </p>\n\n                        <p class=\'small mb-0 text-dark\'>\n\n                            La apendicitis complicada requiere\n                            manejo hospitalario y quirúrgico.\n                            El alta únicamente con analgésicos\n                            representa un alto riesgo de progresión\n                            a sepsis y perforación.\n\n                        </p>\n\n                    </div>\n\n                    `;\n                \">\n\n                <span class=\"badge bg-dark me-3 py-2 px-3\">\n                    A\n                </span>\n\n                <span>\n                    Alta médica con analgésicos\n                </span>\n\n            </button>\n\n        </div>\n\n        <!-- B -->\n        <div class=\"col-md-6\">\n\n            <button\n                class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2 d-flex align-items-center\"\n                style=\"border-radius: 15px;\"\n\n                onclick=\"\n\n                    guardarRespuesta(\'B\',1);\n\n                    document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                    <div\n                        class=\'alert alert-success border-0 shadow-sm animate__animated animate__fadeInUp\'\n                        style=\'border-radius:20px; background-color:#f6fff9;\'>\n\n                        <div class=\'d-flex align-items-center mb-2\'>\n\n                            <i class=\'bi bi-check-circle-fill text-success fs-4 me-2\'></i>\n\n                            <h5 class=\'fw-bold mb-0\'>\n                                ¡Decisión Correcta!\n                            </h5>\n\n                        </div>\n\n                        <hr>\n\n                        <p class=\'mb-2\'>\n\n                            <strong>\n                                Respuesta correcta: B\n                            </strong>\n\n                        </p>\n\n                        <p class=\'small mb-0 text-dark\'>\n\n                            El manejo ideal consiste en iniciar\n                            cobertura antibiótica y preparar para\n                            <strong>apendicectomía inmediata</strong>,\n                            disminuyendo el riesgo de perforación,\n                            abscesos y sepsis.\n\n                        </p>\n\n                    </div>\n\n                    `;\n                \">\n\n                <span class=\"badge bg-dark me-3 py-2 px-3\">\n                    B\n                </span>\n\n                <span>\n                    Antibióticos y preparación quirúrgica\n                </span>\n\n            </button>\n\n        </div>\n\n        <!-- C -->\n        <div class=\"col-md-6\">\n\n            <button\n                class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2 d-flex align-items-center\"\n                style=\"border-radius: 15px;\"\n\n                onclick=\"\n\n                    guardarRespuesta(\'C\',0);\n\n                    document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                    <div\n                        class=\'alert alert-danger border-0 shadow-sm animate__animated animate__fadeInUp\'\n                        style=\'border-radius:20px; background-color:#fff5f5;\'>\n\n                        <div class=\'d-flex align-items-center mb-2\'>\n\n                            <i class=\'bi bi-x-circle-fill text-danger fs-4 me-2\'></i>\n\n                            <h5 class=\'fw-bold mb-0\'>\n                                Retroalimentación\n                            </h5>\n\n                        </div>\n\n                        <hr>\n\n                        <p class=\'mb-2\'>\n\n                            <strong>\n                                Respuesta correcta: B\n                            </strong>\n\n                        </p>\n\n                        <p class=\'small mb-0 text-dark\'>\n\n                            La observación pasiva en una fase\n                            gangrenosa favorece la progresión\n                            inevitable hacia perforación y\n                            peritonitis purulenta.\n\n                        </p>\n\n                    </div>\n\n                    `;\n                \">\n\n                <span class=\"badge bg-dark me-3 py-2 px-3\">\n                    C\n                </span>\n\n                <span>\n                    Observación sin intervención\n                </span>\n\n            </button>\n\n        </div>\n\n        <!-- D -->\n        <div class=\"col-md-6\">\n\n            <button\n                class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2 d-flex align-items-center\"\n                style=\"border-radius: 15px;\"\n\n                onclick=\"\n\n                    guardarRespuesta(\'D\',0);\n\n                    document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                    <div\n                        class=\'alert alert-danger border-0 shadow-sm animate__animated animate__fadeInUp\'\n                        style=\'border-radius:20px; background-color:#fff5f5;\'>\n\n                        <div class=\'d-flex align-items-center mb-2\'>\n\n                            <i class=\'bi bi-x-circle-fill text-danger fs-4 me-2\'></i>\n\n                            <h5 class=\'fw-bold mb-0\'>\n                                Retroalimentación\n                            </h5>\n\n                        </div>\n\n                        <hr>\n\n                        <p class=\'mb-2\'>\n\n                            <strong>\n                                Respuesta correcta: B\n                            </strong>\n\n                        </p>\n\n                        <p class=\'small mb-0 text-dark\'>\n\n                            Aunque los antibióticos son esenciales,\n                            en esta etapa no sustituyen la necesidad\n                            de remover el foco infeccioso mediante\n                            apendicectomía.\n\n                        </p>\n\n                    </div>\n\n                    `;\n                \">\n\n                <span class=\"badge bg-dark me-3 py-2 px-3\">\n                    D\n                </span>\n\n                <span>\n                    Solo antibióticos y alta médica\n                </span>\n\n            </button>\n\n        </div>\n\n    </div>\n\n</div>','',1,'B'),(18,1,16,'texto','Tratamiento instaurado','<div class=\"container my-5\">\n    <div class=\"row justify-content-center\">\n        <div class=\"col-lg-10\">\n            \n            <div class=\"card border-0 shadow-lg\" style=\"border-radius: 20px; border-top: 8px solid #198754 !important;\">\n                <div class=\"card-body p-4 p-md-5\">\n                    \n                    <div class=\"d-flex align-items-center justify-content-between mb-4 pb-3 border-bottom\">\n                        <div>\n                            <h6 class=\"text-success fw-bold text-uppercase mb-1\" style=\"letter-spacing: 1px;\">Conducta Terapéutica</h6>\n                            <h2 class=\"fw-bold text-dark mb-0\">Tratamiento Instaurado</h2>\n                        </div>\n                        <div class=\"text-end d-none d-md-block\">\n                            <span class=\"badge bg-success px-3 py-2 rounded-pill\">Estatus: Prioridad Quirúrgica</span>\n                        </div>\n                    </div>\n\n                    <div class=\"mb-5\">\n                        <div class=\"d-flex align-items-center mb-4\">\n                            <div class=\"bg-success bg-opacity-10 p-2 rounded-circle me-3\">\n                                <i class=\"bi bi-hospital text-success fs-3\"></i>\n                            </div>\n                            <h4 class=\"fw-bold mb-0\">Resolución vía quirúrgica</h4>\n                        </div>\n\n                        <div class=\"row g-4\">\n                            <div class=\"col-md-6\">\n                                <div class=\"p-3 border border-start-0 border-end-0 border-top-0 d-flex align-items-center\">\n                                    <i class=\"bi bi-check2-square text-success fs-4 me-3\"></i>\n                                    <div>\n                                        <span class=\"d-block fw-bold small text-muted text-uppercase\">Régimen</span>\n                                        <span class=\"text-dark fw-bold\">Ayuno absoluto</span>\n                                    </div>\n                                </div>\n                            </div>\n                            \n                            <div class=\"col-md-6\">\n                                <div class=\"p-3 border border-start-0 border-end-0 border-top-0 d-flex align-items-center\">\n                                    <i class=\"bi bi-droplet-half text-primary fs-4 me-3\"></i>\n                                    <div>\n                                        <span class=\"d-block fw-bold small text-muted text-uppercase\">Vía Parenteral</span>\n                                        <span class=\"text-dark fw-bold\">Solución Hartmann (IV)</span>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <div class=\"col-md-6\">\n                                <div class=\"p-3 border border-start-0 border-end-0 border-top-0 d-flex align-items-center\">\n                                    <i class=\"bi bi-capsule text-danger fs-4 me-3\"></i>\n                                    <div>\n                                        <span class=\"d-block fw-bold small text-muted text-uppercase\">Manejo de Dolor</span>\n                                        <span class=\"text-dark fw-bold\">Ketorolaco (IV)</span>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <div class=\"col-md-6\">\n                                <div class=\"p-3 border border-start-0 border-end-0 border-top-0 d-flex align-items-center\">\n                                    <i class=\"bi bi-shield-plus text-info fs-4 me-3\"></i>\n                                    <div>\n                                        <span class=\"d-block fw-bold small text-muted text-uppercase\">Profilaxis</span>\n                                        <span class=\"text-dark fw-bold\">Tromboprofilaxis mecánica</span>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n\n                    <div class=\"card bg-light border-0\" style=\"border-radius: 15px;\">\n                        <div class=\"card-body p-4 border-start border-success border-5\" style=\"border-radius: 0 15px 15px 0;\">\n                            <div class=\"d-flex align-items-center\">\n                                <i class=\"bi bi-virus text-success fs-2 me-3\"></i>\n                                <div>\n                                    <h6 class=\"fw-bold text-success mb-1\">Esquema Antibiótico Empírico</h6>\n                                    <h5 class=\"fw-bold text-dark mb-0 italic\">Ceftriaxona + Metronidazol (IV)</h5>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n\n                    <div class=\"mt-5 pt-3 border-top d-flex justify-content-between align-items-center\">\n                        <div class=\"small text-muted italic\">\n                            Documento generado según protocolo IMSS\n                        </div>\n                        <img src=\"../img/tratamiento.png\" alt=\"IMSS\" style=\"height: 35px; filter: grayscale(1); opacity: 0.5;\">\n                    </div>\n\n                </div>\n            </div>\n\n        </div>\n    </div>\n</div>','../img/tratamiento.png',0,NULL),(19,1,17,'pregunta','¿Cuál es el principal objetivo de utilizar escalas de riesgo en pacientes con sospecha de apendicitis aguda complicada?','<div class=\"container my-4\">\n\n    <div class=\"text-center mb-4\">\n\n        <h5\n            class=\"fw-bold text-muted text-uppercase small\"\n            style=\"letter-spacing: 1px;\">\n\n            Estratificación de Riesgo\n\n        </h5>\n\n    </div>\n\n    <!-- RETRO -->\n    <div id=\"retroalimentacion\" class=\"mb-4\"></div>\n\n    <!-- RESPUESTAS -->\n    <div class=\"row g-3\">\n\n        <!-- A -->\n        <div class=\"col-md-6\">\n\n            <button\n                class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2\"\n                style=\"border-radius: 15px;\"\n\n                onclick=\"\n\n                    guardarRespuesta(\'A\',0);\n\n                    document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                    <div\n                        class=\'alert alert-danger border-0 shadow animate__animated animate__fadeIn\'\n                        style=\'border-radius:20px; background-color:#fff5f5;\'>\n\n                        <h5 class=\'fw-bold\'>\n\n                            <i class=\'bi bi-info-circle-fill me-2\'></i>\n\n                            Retroalimentación\n\n                        </h5>\n\n                        <hr>\n\n                        <p class=\'mb-1\'>\n\n                            <strong>\n                                Respuesta correcta: C\n                            </strong>\n\n                        </p>\n\n                        <p class=\'small mb-0 text-dark\'>\n\n                            Las escalas no sustituyen los estudios\n                            de imagen; ayudan a identificar qué\n                            pacientes requieren estudios adicionales,\n                            evitando radiación o costos innecesarios.\n\n                        </p>\n\n                    </div>\n\n                    `;\n                \">\n\n                <span class=\"badge bg-dark me-2\">\n                    A\n                </span>\n\n                Sustituir estudios de imagen\n\n            </button>\n\n        </div>\n\n        <!-- B -->\n        <div class=\"col-md-6\">\n\n            <button\n                class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2\"\n                style=\"border-radius: 15px;\"\n\n                onclick=\"\n\n                    guardarRespuesta(\'B\',0);\n\n                    document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                    <div\n                        class=\'alert alert-danger border-0 shadow animate__animated animate__fadeIn\'\n                        style=\'border-radius:20px; background-color:#fff5f5;\'>\n\n                        <h5 class=\'fw-bold\'>\n\n                            <i class=\'bi bi-info-circle-fill me-2\'></i>\n\n                            Retroalimentación\n\n                        </h5>\n\n                        <hr>\n\n                        <p class=\'mb-1\'>\n\n                            <strong>\n                                Respuesta correcta: C\n                            </strong>\n\n                        </p>\n\n                        <p class=\'small mb-0 text-dark\'>\n\n                            La histopatología es el estándar de oro\n                            postquirúrgico. Las escalas están diseñadas\n                            para apoyar la decisión diagnóstica\n                            preoperatoria.\n\n                        </p>\n\n                    </div>\n\n                    `;\n                \">\n\n                <span class=\"badge bg-dark me-2\">\n                    B\n                </span>\n\n                Confirmar diagnóstico histopatológico\n\n            </button>\n\n        </div>\n\n        <!-- C -->\n        <div class=\"col-md-6\">\n\n            <button\n                class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2\"\n                style=\"border-radius: 15px;\"\n\n                onclick=\"\n\n                    guardarRespuesta(\'C\',1);\n\n                    document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                    <div\n                        class=\'alert alert-success border-0 shadow animate__animated animate__fadeIn\'\n                        style=\'border-radius:20px; background-color:#f6fff9;\'>\n\n                        <h5 class=\'fw-bold\'>\n\n                            <i class=\'bi bi-check-circle-fill me-2\'></i>\n\n                            ¡Correcto!\n\n                        </h5>\n\n                        <hr>\n\n                        <p class=\'mb-1\'>\n\n                            <strong>\n                                Respuesta correcta: C\n                            </strong>\n\n                        </p>\n\n                        <p class=\'small mb-0 text-dark\'>\n\n                            Las escalas permiten clasificar pacientes\n                            en grupos de <strong>bajo, mediano o alto riesgo</strong>,\n                            optimizando recursos diagnósticos,\n                            tiempos quirúrgicos y toma de decisiones.\n\n                        </p>\n\n                    </div>\n\n                    `;\n                \">\n\n                <span class=\"badge bg-dark me-2\">\n                    C\n                </span>\n\n                Estratificar riesgo y guiar conducta\n\n            </button>\n\n        </div>\n\n        <!-- D -->\n        <div class=\"col-md-6\">\n\n            <button\n                class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2\"\n                style=\"border-radius: 15px;\"\n\n                onclick=\"\n\n                    guardarRespuesta(\'D\',0);\n\n                    document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                    <div\n                        class=\'alert alert-danger border-0 shadow animate__animated animate__fadeIn\'\n                        style=\'border-radius:20px; background-color:#fff5f5;\'>\n\n                        <h5 class=\'fw-bold\'>\n\n                            <i class=\'bi bi-info-circle-fill me-2\'></i>\n\n                            Retroalimentación\n\n                        </h5>\n\n                        <hr>\n\n                        <p class=\'mb-1\'>\n\n                            <strong>\n                                Respuesta correcta: C\n                            </strong>\n\n                        </p>\n\n                        <p class=\'small mb-0 text-dark\'>\n\n                            El tipo de incisión es una decisión\n                            técnica basada en anatomía y hallazgos\n                            intraoperatorios, no en el puntaje\n                            de una escala clínica.\n\n                        </p>\n\n                    </div>\n\n                    `;\n                \">\n\n                <span class=\"badge bg-dark me-2\">\n                    D\n                </span>\n\n                Determinar tipo de incisión\n\n            </button>\n\n        </div>\n\n    </div>\n\n</div>','',1,'C'),(20,1,18,'texto','Tratamiento quirúrgico','<div class=\"container my-5\">\n    <div class=\"row justify-content-center\">\n        <div class=\"col-lg-10\">\n            \n            <div class=\"d-flex align-items-center mb-4\">\n                <div class=\"bg-dark p-3 rounded-4 me-3 shadow-sm\">\n                    <i class=\"bi bi-camera-video text-white fs-3\"></i>\n                </div>\n                <div>\n                    <h6 class=\"text-muted fw-bold text-uppercase mb-0\" style=\"letter-spacing: 1px;\">Procedimiento en Curso</h6>\n                    <h3 class=\"fw-bold text-dark\">Apendicectomía Laparoscópica de Urgencia</h3>\n                </div>\n            </div>\n\n            <div class=\"card border-0 shadow-lg overflow-hidden\" style=\"border-radius: 25px; background-color: #000;\">\n                <div class=\"card-header bg-dark border-0 d-flex justify-content-between align-items-center py-3 px-4\">\n                    <div class=\"d-flex align-items-center\">\n                        <span class=\"badge border border-danger text-danger px-2 py-1 me-2 animate__animated animate__flash animate__infinite\">● REC</span>\n                        <small class=\"text-white-50 fw-bold text-uppercase\">Cam_01 / Laparoscopía</small>\n                    </div>\n                    <div class=\"text-white-50\">\n                        <i class=\"bi bi-fullscreen-exit me-2\"></i>\n                        <i class=\"bi bi-gear\"></i>\n                    </div>\n                </div>\n                \n                <div class=\"ratio ratio-16x9\">\n                    <video controls poster=\"https://img.freepik.com/premium-photo/surgeons-operating-room_1048944-11884488.jpg\" style=\"object-fit: cover;\">\n                        <source src=\"../video/Apendicectomía_laparoscópica_de_urgencia.mp4\" type=\"video/mp4\">\n                        Tu navegador no soporta la reproducción de video.\n                    </video>\n                </div>\n\n                <div class=\"card-footer bg-dark border-0 p-4\">\n                    <div class=\"row text-white\">\n                        <div class=\"col-md-4 mb-3 mb-md-0\">\n                            <div class=\"d-flex align-items-center\">\n                                <i class=\"bi bi-intersex text-info fs-4 me-3\"></i>\n                                <div>\n                                    <small class=\"d-block text-white-50 text-uppercase\" style=\"font-size: 0.7rem;\">Técnica</small>\n                                    <span class=\"fw-bold\">Tri-Port (3 Trocares)</span>\n                                </div>\n                            </div>\n                        </div>\n                        <div class=\"col-md-4 mb-3 mb-md-0\">\n                            <div class=\"d-flex align-items-center\">\n                                <i class=\"bi bi-scissors text-info fs-4 me-3\"></i>\n                                <div>\n                                    <small class=\"d-block text-white-50 text-uppercase\" style=\"font-size: 0.7rem;\">Hallazgo</small>\n                                    <span class=\"fw-bold\">Fase III (Gangrenosa)</span>\n                                </div>\n                            </div>\n                        </div>\n                        <div class=\"col-md-4\">\n                            <div class=\"d-flex align-items-center\">\n                                <i class=\"bi bi-shield-shaded text-info fs-4 me-3\"></i>\n                                <div>\n                                    <small class=\"d-block text-white-50 text-uppercase\" style=\"font-size: 0.7rem;\">Seguridad</small>\n                                    <span class=\"fw-bold\">Aseo Peritoneal</span>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"alert mt-4 border-0 shadow-sm d-flex align-items-center\" style=\"border-radius: 15px; background-color: #eef2f7;\">\n                <i class=\"bi bi-lightbulb text-primary fs-3 me-3\"></i>\n                <p class=\"mb-0 small text-dark\">\n                    <strong>Paso Clave:</strong> Observa la identificación de la <strong>base apendicular</strong> y el uso de energía ultrasónica o clips para el control del mesoapéndice.\n                </p>\n            </div>\n\n        </div>\n    </div>\n</div>\n                    ','',0,NULL),(21,1,19,'texto','Hallazgos trans operatorios','<div class=\"container my-4\">\n    <div class=\"row justify-content-center\">\n        <div class=\"col-lg-10\">\n            \n            <div class=\"card border-0 shadow-sm\" style=\"border-radius: 20px; background: #f8f9fa;\">\n                <div class=\"card-body p-4\">\n                    \n                    <div class=\"d-flex align-items-center mb-4\">\n                        <div class=\"bg-primary bg-opacity-10 p-2 rounded-3 me-3\">\n                            <i class=\"bi bi-eye text-primary fs-4\"></i>\n                        </div>\n                        <h5 class=\"fw-bold mb-0 text-dark\">Descripción Macroscópica</h5>\n                    </div>\n\n                    <div class=\"row g-3\">\n                        <div class=\"col-md-6\">\n                            <div class=\"bg-white p-3 rounded-4 shadow-sm h-100 border-start border-danger border-4\">\n                                <h6 class=\"fw-bold text-danger small text-uppercase mb-3\">Estado del Órgano</h6>\n                                <ul class=\"list-unstyled mb-0\">\n                                    <li class=\"mb-2 d-flex align-items-start\">\n                                        <i class=\"bi bi-dot text-danger fs-4 lh-1\"></i>\n                                        <span>Apéndice <strong>edematoso y congestivo</strong> con áreas necróticas.</span>\n                                    </li>\n                                    <li class=\"d-flex align-items-start\">\n                                        <i class=\"bi bi-dot text-danger fs-4 lh-1\"></i>\n                                        <span>Serosa <strong>opaca y friable</strong> al tacto instrumental.</span>\n                                    </li>\n                                </ul>\n                            </div>\n                        </div>\n\n                        <div class=\"col-md-6\">\n                            <div class=\"bg-white p-3 rounded-4 shadow-sm h-100 border-start border-primary border-4\">\n                                <h6 class=\"fw-bold text-primary small text-uppercase mb-3\">Cavidad y Adyacentes</h6>\n                                <ul class=\"list-unstyled mb-0\">\n                                    <li class=\"mb-2 d-flex align-items-start\">\n                                        <i class=\"bi bi-droplet-fill text-primary fs-6 me-2 mt-1\"></i>\n                                        <span>Presencia de <strong>líquido inflamatorio</strong> pericecal.</span>\n                                    </li>\n                                    <li class=\"mb-2 d-flex align-items-start\">\n                                        <i class=\"bi bi-check-circle-fill text-success fs-6 me-2 mt-1\"></i>\n                                        <span>Ciego sin lesiones aparentes.</span>\n                                    </li>\n                                    <li class=\"d-flex align-items-start\">\n                                        <i class=\"bi bi-shield-check text-success fs-6 me-2 mt-1\"></i>\n                                        <span>Sin evidencia de perforación o abscesos.</span>\n                                    </li>\n                                </ul>\n                            </div>\n                        </div>\n                    </div>\n\n                    <div class=\"alert alert-danger mt-4 border-0 shadow-sm\" style=\"border-radius: 15px;\">\n                        <div class=\"d-flex align-items-center\">\n                            <div class=\"me-3\">\n                                <i class=\"bi bi-exclamation-triangle-fill fs-2\"></i>\n                            </div>\n                            <div>\n                                <h5 class=\"fw-bold mb-1\">Clasificación Intraoperatoria</h5>\n                                <p class=\"fs-5 mb-0\">Apendicitis <strong>gangrenosa (Fase III)</strong></p>\n                            </div>\n                        </div>\n                    </div>\n\n                </div>\n            </div>\n\n        </div>\n    </div>\n</div>','',0,NULL),(22,1,20,'pregunta','¿Cuál es la complicación más grave de una apendicitis no tratada?','<div class=\"container my-4\">\n\n    <div class=\"text-center mb-4\">\n\n        <span\n            class=\"badge bg-warning bg-opacity-10 text-dark px-3 py-2 rounded-pill mb-2 fw-bold\">\n\n            Análisis de Riesgo\n\n        </span>\n\n        <p class=\"text-muted small mb-0\">\n\n            ¿Cuál es la principal complicación de una\n            apendicitis aguda no tratada?\n\n        </p>\n\n    </div>\n\n    <!-- RETRO -->\n    <div id=\"retroalimentacion\" class=\"mb-4\"></div>\n\n    <!-- RESPUESTAS -->\n    <div class=\"row g-3\">\n\n        <!-- A -->\n        <div class=\"col-md-6\">\n\n            <button\n                class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2 d-flex align-items-center\"\n                style=\"border-radius: 15px;\"\n\n                onclick=\"\n\n                    guardarRespuesta(\'A\',0);\n\n                    document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                    <div\n                        class=\'alert alert-danger border-0 shadow animate__animated animate__shakeX\'\n                        style=\'border-radius:20px; background-color:#fff5f5;\'>\n\n                        <div class=\'d-flex align-items-center mb-2\'>\n\n                            <i class=\'bi bi-x-circle-fill text-danger fs-4 me-2\'></i>\n\n                            <h5 class=\'fw-bold mb-0\'>\n                                Retroalimentación\n                            </h5>\n\n                        </div>\n\n                        <hr>\n\n                        <p class=\'mb-1\'>\n\n                            <strong>\n                                Respuesta correcta: B\n                            </strong>\n\n                        </p>\n\n                        <p class=\'small mb-0 text-dark\'>\n\n                            La pancreatitis es una enfermedad\n                            distinta; aunque comparte síntomas\n                            abdominales, no es una complicación\n                            directa de la apendicitis aguda.\n\n                        </p>\n\n                    </div>\n\n                    `;\n                \">\n\n                <span class=\"badge bg-dark me-3\">\n                    A\n                </span>\n\n                <span>\n                    Pancreatitis\n                </span>\n\n            </button>\n\n        </div>\n\n        <!-- B -->\n        <div class=\"col-md-6\">\n\n            <button\n                class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2 d-flex align-items-center\"\n                style=\"border-radius: 15px;\"\n\n                onclick=\"\n\n                    guardarRespuesta(\'B\',1);\n\n                    document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                    <div\n                        class=\'alert alert-success border-0 shadow animate__animated animate__bounceIn\'\n                        style=\'border-radius:20px; background-color:#f6fff9;\'>\n\n                        <div class=\'d-flex align-items-center mb-2\'>\n\n                            <i class=\'bi bi-check-circle-fill text-success fs-4 me-2\'></i>\n\n                            <h5 class=\'fw-bold mb-0\'>\n                                ¡Excelente!\n                            </h5>\n\n                        </div>\n\n                        <hr>\n\n                        <p class=\'mb-1\'>\n\n                            <strong>\n                                Respuesta correcta: B\n                            </strong>\n\n                        </p>\n\n                        <p class=\'small mb-0 text-dark\'>\n\n                            La <strong>perforación apendicular</strong>\n                            puede evolucionar rápidamente hacia\n                            peritonitis, abscesos intraabdominales\n                            y sepsis, aumentando considerablemente\n                            la morbimortalidad.\n\n                        </p>\n\n                    </div>\n\n                    `;\n                \">\n\n                <span class=\"badge bg-dark me-3\">\n                    B\n                </span>\n\n                <span>\n                    Perforación y peritonitis\n                </span>\n\n            </button>\n\n        </div>\n\n        <!-- C -->\n        <div class=\"col-md-6\">\n\n            <button\n                class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2 d-flex align-items-center\"\n                style=\"border-radius: 15px;\"\n\n                onclick=\"\n\n                    guardarRespuesta(\'C\',0);\n\n                    document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                    <div\n                        class=\'alert alert-danger border-0 shadow animate__animated animate__shakeX\'\n                        style=\'border-radius:20px; background-color:#fff5f5;\'>\n\n                        <div class=\'d-flex align-items-center mb-2\'>\n\n                            <i class=\'bi bi-x-circle-fill text-danger fs-4 me-2\'></i>\n\n                            <h5 class=\'fw-bold mb-0\'>\n                                Retroalimentación\n                            </h5>\n\n                        </div>\n\n                        <hr>\n\n                        <p class=\'mb-1\'>\n\n                            <strong>\n                                Respuesta correcta: B\n                            </strong>\n\n                        </p>\n\n                        <p class=\'small mb-0 text-dark\'>\n\n                            La cirrosis hepática es una enfermedad\n                            crónica del hígado y no guarda relación\n                            fisiopatológica con la apendicitis aguda.\n\n                        </p>\n\n                    </div>\n\n                    `;\n                \">\n\n                <span class=\"badge bg-dark me-3\">\n                    C\n                </span>\n\n                <span>\n                    Cirrosis hepática\n                </span>\n\n            </button>\n\n        </div>\n\n        <!-- D -->\n        <div class=\"col-md-6\">\n\n            <button\n                class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2 d-flex align-items-center\"\n                style=\"border-radius: 15px;\"\n\n                onclick=\"\n\n                    guardarRespuesta(\'D\',0);\n\n                    document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                    <div\n                        class=\'alert alert-danger border-0 shadow animate__animated animate__shakeX\'\n                        style=\'border-radius:20px; background-color:#fff5f5;\'>\n\n                        <div class=\'d-flex align-items-center mb-2\'>\n\n                            <i class=\'bi bi-x-circle-fill text-danger fs-4 me-2\'></i>\n\n                            <h5 class=\'fw-bold mb-0\'>\n                                Retroalimentación\n                            </h5>\n\n                        </div>\n\n                        <hr>\n\n                        <p class=\'mb-1\'>\n\n                            <strong>\n                                Respuesta correcta: B\n                            </strong>\n\n                        </p>\n\n                        <p class=\'small mb-0 text-dark\'>\n\n                            El aneurisma aórtico corresponde a una\n                            patología vascular independiente y no\n                            constituye una complicación derivada\n                            de infección apendicular.\n\n                        </p>\n\n                    </div>\n\n                    `;\n                \">\n\n                <span class=\"badge bg-dark me-3\">\n                    D\n                </span>\n\n                <span>\n                    Aneurisma aórtico\n                </span>\n\n            </button>\n\n        </div>\n\n    </div>\n\n</div>','',1,'B'),(23,1,21,'texto','Evolución Postquirúrgica','<div class=\"container my-5\">\n    <div class=\"row justify-content-center\">\n        <div class=\"col-lg-10\">\n            \n            <div class=\"d-flex align-items-center mb-4\">\n                <div class=\"bg-success p-3 rounded-4 me-3 shadow-sm\">\n                    <i class=\"bi bi-graph-up-arrow text-white fs-3\"></i>\n                </div>\n                <div>\n                    <h6 class=\"text-muted fw-bold text-uppercase mb-0\" style=\"letter-spacing: 1px;\">Seguimiento Hospitalario</h6>\n                </div>\n            </div>\n\n            <div class=\"row g-4\">\n                <div class=\"col-md-6\">\n                    <div class=\"card border-0 shadow-sm h-100\" style=\"border-radius: 20px; background: #fdfdfd;\">\n                        <div class=\"card-header bg-white border-0 pt-4 px-4\">\n                            <h5 class=\"fw-bold text-dark\"><i class=\"bi bi-clock-history text-primary me-2\"></i>Primeras 24–48 horas</h5>\n                        </div>\n                        <div class=\"card-body px-4 pb-4\">\n                            <div class=\"d-flex flex-column gap-3\">\n                                <div class=\"d-flex align-items-center p-2 bg-success bg-opacity-10 rounded-3\">\n                                    <i class=\"bi bi-person-check-fill text-success fs-4 me-3\"></i>\n                                    <span class=\"fw-bold text-dark\">Evolución clínica favorable</span>\n                                </div>\n                                <div class=\"d-flex align-items-center p-2 bg-light rounded-3\">\n                                    <i class=\"bi bi-thermometer-low text-info fs-4 me-3\"></i>\n                                    <span class=\"text-dark\">Paciente <strong>afebril</strong></span>\n                                </div>\n                                <div class=\"d-flex align-items-center p-2 bg-light rounded-3\">\n                                    <i class=\"bi bi-capsule-pill text-primary fs-4 me-3\"></i>\n                                    <span class=\"text-dark\">Dolor controlado (Analgesia)</span>\n                                </div>\n                                <div class=\"d-flex align-items-center p-2 bg-light rounded-3\">\n                                    <i class=\"bi bi-cup-hot text-warning fs-4 me-3\"></i>\n                                    <span class=\"text-dark\">Vía oral progresiva iniciada</span>\n                                </div>\n                                <div class=\"d-flex align-items-center p-2 bg-light rounded-3\">\n                                    <i class=\"bi bi-droplet-half text-danger fs-4 me-3\"></i>\n                                    <span class=\"text-dark small\">Leucocitos en descenso gradual</span>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <div class=\"col-md-6\">\n                    <div class=\"card border-0 shadow-sm h-100\" style=\"border-radius: 20px; background: #fdfdfd;\">\n                        <div class=\"card-header bg-white border-0 pt-4 px-4\">\n                            <h5 class=\"fw-bold text-dark\"><i class=\"bi bi-clipboard2-pulse text-danger me-2\"></i>Manejo Terapéutico</h5>\n                        </div>\n                        <div class=\"card-body px-4 pb-4\">\n                            <ul class=\"list-group list-group-flush\">\n                                <li class=\"list-group-item border-0 px-0 d-flex align-items-start mb-2\">\n                                    <i class=\"bi bi-shield-check text-success fs-5 me-3\"></i>\n                                    <div>\n                                        <span class=\"fw-bold d-block\">Antibioticoterapia IV</span>\n                                        <small class=\"text-muted\">Continuación por 48 h (Esquema dirigido)</small>\n                                    </div>\n                                </li>\n                                <li class=\"list-group-item border-0 px-0 d-flex align-items-start mb-2\">\n                                    <i class=\"bi bi-layers text-primary fs-5 me-3\"></i>\n                                    <div>\n                                        <span class=\"fw-bold d-block\">Analgesia Multimodal</span>\n                                        <small class=\"text-muted\">Combinación de fármacos para optimizar confort</small>\n                                    </div>\n                                </li>\n                                <li class=\"list-group-item border-0 px-0 d-flex align-items-start\">\n                                    <i class=\"bi bi-walking text-info fs-5 me-3\"></i>\n                                    <div>\n                                        <span class=\"fw-bold d-block\">Movilización Temprana</span>\n                                        <small class=\"text-muted\">Prevención de íleo y eventos trombóticos</small>\n                                    </div>\n                                </li>\n                            </ul>\n                        </div>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"alert mt-4 bg-dark text-white border-0 d-flex align-items-center\" style=\"border-radius: 15px;\">\n                <i class=\"bi bi-info-circle-fill text-warning fs-3 me-3\"></i>\n                <div class=\"small\">\n                    La recuperación exitosa en una <strong>Apendicitis Fase III</strong> depende estrictamente del cumplimiento del esquema antibiótico y la deambulación precoz.\n                </div>\n            </div>\n\n        </div>\n    </div>\n</div>','',0,NULL),(24,1,22,'texto','Egreso hospitalario','<div class=\"container my-5\">\n    <div class=\"row justify-content-center\">\n        <div class=\"col-lg-10\">\n            \n            <div class=\"card border-0 shadow-lg overflow-hidden\" style=\"border-radius: 25px;\">\n                <div class=\"p-4 text-white d-flex justify-content-between align-items-center\" style=\"background: linear-gradient(45deg, #1e4d2b, #28a745);\">\n                    <div>\n                        <h2 class=\"fw-bold mb-0\">Alta Hospitalaria</h2>\n                        <p class=\"mb-0 opacity-75 italic\">Plan de Cuidados en Domicilio</p>\n                    </div>\n                    <i class=\"bi bi-door-open fs-1\"></i>\n                </div>\n\n                <div class=\"card-body p-4 p-md-5 bg-white\">\n                    \n                    <div class=\"mb-5\">\n                        <div class=\"d-flex align-items-center mb-4\">\n                            <span class=\"badge bg-success bg-opacity-10 text-success p-2 rounded-circle me-3\">\n                                <i class=\"bi bi-person-check fs-4\"></i>\n                            </span>\n                            <h4 class=\"fw-bold mb-0 text-dark\">Condición del Paciente (48h)</h4>\n                        </div>\n                        \n                        <div class=\"row g-3\">\n                            <div class=\"col-sm-6\">\n                                <div class=\"p-3 border rounded-4 d-flex align-items-center\">\n                                    <i class=\"bi bi-activity text-success me-3 fs-4\"></i>\n                                    <span class=\"text-secondary fw-semibold\">Hemodinámicamente estable</span>\n                                </div>\n                            </div>\n                            <div class=\"col-sm-6\">\n                                <div class=\"p-3 border rounded-4 d-flex align-items-center\">\n                                    <i class=\"bi bi-patch-check text-success me-3 fs-4\"></i>\n                                    <span class=\"text-secondary fw-semibold\">Sin datos de infección</span>\n                                </div>\n                            </div>\n                            <div class=\"col-sm-6\">\n                                <div class=\"p-3 border rounded-4 d-flex align-items-center\">\n                                    <i class=\"bi bi-egg-fried text-success me-3 fs-4\"></i>\n                                    <span class=\"text-secondary fw-semibold\">Tolerancia a vía oral</span>\n                                </div>\n                            </div>\n                            <div class=\"col-sm-6\">\n                                <div class=\"p-3 border rounded-4 d-flex align-items-center\">\n                                    <i class=\"bi bi-bandaid text-success me-3 fs-4\"></i>\n                                    <span class=\"text-secondary fw-semibold\">Heridas limpias y sanas</span>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n\n                    <div class=\"p-4 rounded-4\" style=\"background-color: #f8fcf9; border: 2px dashed #28a745;\">\n                        <h5 class=\"fw-bold text-dark mb-4 text-center text-uppercase\" style=\"letter-spacing: 2px;\">\n                            <i class=\"bi bi-file-earmark-medical me-2\"></i>Receta e Indicaciones\n                        </h5>\n                        \n                        <div class=\"row g-4\">\n                            <div class=\"col-md-6\">\n                                <div class=\"d-flex align-items-start\">\n                                    <div class=\"bg-white p-2 rounded-3 shadow-sm me-3\">\n                                        <i class=\"bi bi-capsule text-success fs-4\"></i>\n                                    </div>\n                                    <div>\n                                        <h6 class=\"fw-bold mb-1\">Esquema Antibiótico</h6>\n                                        <p class=\"text-muted small\">Continuar vía oral por 5 días adicionales para completar ciclo.</p>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"col-md-6\">\n                                <div class=\"d-flex align-items-start\">\n                                    <div class=\"bg-white p-2 rounded-3 shadow-sm me-3\">\n                                        <i class=\"bi bi-pills text-danger fs-4\"></i>\n                                    </div>\n                                    <div>\n                                        <h6 class=\"fw-bold mb-1\">Analgesia</h6>\n                                        <p class=\"text-muted small\">Manejo de rescate a demanda (PRN) según escala de dolor.</p>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"col-md-6\">\n                                <div class=\"d-flex align-items-start\">\n                                    <div class=\"bg-white p-2 rounded-3 shadow-sm me-3\">\n                                        <i class=\"bi bi-house-heart text-info fs-4\"></i>\n                                    </div>\n                                    <div>\n                                        <h6 class=\"fw-bold mb-1\">Cuidados Generales</h6>\n                                        <p class=\"text-muted small\">Reposo relativo. Evitar esfuerzos físicos intensos y carga de peso.</p>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"col-md-6\">\n                                <div class=\"d-flex align-items-start\">\n                                    <div class=\"bg-white p-2 rounded-3 shadow-sm me-3\">\n                                        <i class=\"bi bi-calendar-event text-primary fs-4\"></i>\n                                    </div>\n                                    <div>\n                                        <h6 class=\"fw-bold mb-1\">Control Post-Op</h6>\n                                        <p class=\"text-muted small\">Cita programada en 7 días para retiro de puntos y valoración final.</p>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n\n                </div>\n            </div>\n\n            <div class=\"alert mt-4 bg-danger bg-opacity-10 border-danger border-start border-5 text-white\" style=\"border-radius: 15px;\">\n                <h6 class=\"fw-bold\"><i class=\"bi bi-exclamation-octagon-fill text-danger me-2\"></i>Signos de Alarma para Reingreso:</h6>\n                <p class=\"small mb-0\">Fiebre >38°C, dolor abdominal intenso que no cede, vómito persistente o salida de material purulento por heridas.</p>\n            </div>\n\n        </div>\n    </div>\n</div>','',0,NULL),(25,1,23,'texto','Reservado a evolución clínica','<div class=\"container my-5\">\n    <div class=\"row justify-content-center\">\n        <div class=\"col-lg-10\">\n            \n            <div class=\"card border-0 shadow-lg overflow-hidden\" style=\"border-radius: 20px;\">\n                <div class=\"card-body p-0\">\n                    <div class=\"row g-0\">\n                        \n                        <div class=\"col-md-4 bg-dark d-flex flex-column justify-content-center p-4 text-center\">\n                            <div class=\"mb-3\">\n                                <i class=\"bi bi-heart-pulse text-success\" style=\"font-size: 4rem;\"></i>\n                            </div>\n                            <h5 class=\"text-white fw-bold mb-1\">Pronóstico</h5>\n                            <span class=\"badge bg-success px-3 py-2 rounded-pill\">Bueno para la vida</span>\n                            <div class=\"mt-4 pt-3 border-top border-secondary\">\n                                <p class=\"text-white-50 small mb-0\">Basado en resolución quirúrgica oportuna y éxito terapéutico.</p>\n                            </div>\n                        </div>\n\n                        <div class=\"col-md-8 bg-white p-4 p-md-5\">\n                            <div class=\"mb-4\">\n                                <h6 class=\"text-muted fw-bold text-uppercase small mb-2\" style=\"letter-spacing: 1px;\">Estado del Paciente</h6>\n                                <h3 class=\"fw-bold text-dark\">Reservado a evolución clínica</h3>\n                            </div>\n\n                            <div class=\"d-flex flex-column gap-4\">\n                                <div class=\"d-flex align-items-start\">\n                                    <div class=\"bg-success bg-opacity-10 p-2 rounded-3 me-3\">\n                                        <i class=\"bi bi-shield-check text-success fs-4\"></i>\n                                    </div>\n                                    <div>\n                                        <h6 class=\"fw-bold mb-1\">Bajo riesgo de complicaciones</h6>\n                                        <p class=\"text-muted mb-0 small\">La intervención en Fase III sin perforación disminuye drásticamente la probabilidad de abscesos residuales o reintervenciones.</p>\n                                    </div>\n                                </div>\n\n                                <div class=\"d-flex align-items-start\">\n                                    <div class=\"bg-primary bg-opacity-10 p-2 rounded-3 me-3\">\n                                        <i class=\"bi bi-person-up text-primary fs-4\"></i>\n                                    </div>\n                                    <div>\n                                        <h6 class=\"fw-bold mb-1\">Recuperación Funcional Ad Integrum</h6>\n                                        <p class=\"text-muted mb-0 small\">Se espera un retorno a las actividades habituales tras el periodo de convalecencia estándar.</p>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <div class=\"mt-5\">\n                                <div class=\"d-flex justify-content-between mb-2\">\n                                    <span class=\"small fw-bold text-muted\">Probabilidad de Éxito</span>\n                                    <span class=\"small fw-bold text-success\">Alta</span>\n                                </div>\n                                <div class=\"progress\" style=\"height: 10px; border-radius: 5px;\">\n                                    <div class=\"progress-bar bg-success progress-bar-striped progress-bar-animated\" role=\"progressbar\" style=\"width: 95%\"></div>\n                                </div>\n                            </div>\n                        </div>\n\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"text-center mt-5\">\n                <p class=\"text-muted small mb-4 italic\">“El éxito del tratamiento quirúrgico es el reflejo de un diagnóstico clínico preciso y a tiempo.”</p>\n                <div class=\"d-grid d-md-flex justify-content-center gap-3\">\n                    <button class=\"btn btn-dark btn-lg px-5 rounded-pill shadow-sm\" onclick=\"location.reload();\">\n                        <i class=\"bi bi-arrow-clockwise me-2\"></i>Reiniciar Caso\n                    </button>\n                    <button\n    class=\"btn btn-outline-dark btn-lg px-5 rounded-pill shadow-sm\"\n    onclick=\"verResumenFinal()\">\n\n    <i class=\"bi bi-journal-check me-2\"></i>\n\n    Ver Resumen Final\n\n</button>\n                </div>\n            </div>\n\n        </div>\n    </div>\n</div>','',0,NULL),(26,5,1,'texto','Introduccion','Objetivo educativo del módulo\n\n•	Al finalizar el caso clínico interactivo, el participante será capaz de:\n<br>\n•	Reconocer los datos clínicos sugestivos de fractura de Colles\n<br>\n•	Identificar mecanismos de lesión frecuentes en fracturas de radio distal\n<br>\n•	Aplicar criterios clínicos y radiográficos de inestabilidad\n<br>\n•	Seleccionar estudios de imagen adecuados\n<br>\n•	Integrar manejo inicial en urgencias\n<br>\n•	Reconocer indicaciones de reducción cerrada y manejo quirúrgico\n<br>\n•	Evaluar complicaciones tempranas y tardías\n<br>\n•	Aplicar vigilancia neurovascular adecuada\n\n<br>\n<hr>\n<br>\n\nPerfil del usuario\n<br>\n•	Médicos generales\n<br>\n•	Médicos internos de pregrado\n<br>\n•	Residentes de urgencias y traumatología, medicina de urgencias.\n<br>\n•	Personal de salud en formación continua\n\n','',0,NULL),(27,3,2,'Escenario','Consulta inicial de medicina familiar','<div class=\"container my-5\">\n    <div class=\"row\">\n        <div class=\"col-12\">\n            <div class=\"card border-0 shadow-lg\" style=\"border-radius: 20px; overflow: hidden;\">\n                <div class=\"row g-0 align-items-center\">\n                    \n                    <div class=\"col-md-6 col-lg-7 bg-black d-flex align-items-center justify-content-center\">\n                        <div class=\"ratio ratio-16x9\">\n                            <video id=\"videoEscenario\" autoplay muted loop playsinline class=\"w-100\" style=\"object-fit: cover;\">\n                                <source src=\"../video/hombligo.mp4\" type=\"video/mp4\">\n                                Tu navegador no soporta la reproducción de video.\n                            </video>\n                        </div>\n                    </div>\n                    \n                    <div class=\"col-md-6 col-lg-5 p-5 bg-white\">\n                        <div class=\"d-flex align-items-center mb-4\">\n                            \n                            \n\n\n                        <div class=\"mt-4 d-flex align-items-center text-primary small fw-bold\">\n                            <span class=\"spinner-grow spinner-grow-sm me-2\" role=\"status\"></span>\n                            Análisis en curso...\n                        </div>\n\n\n                        </div>\n                        \n                        <div class=\"p-4 bg-light rounded-3\" style=\"border-left: 4px solid #dee2e6;\">\n                            <p class=\"card-text text-muted mb-0 lh-lg\" style=\"font-size: 1.1rem;\">\n                                Paciente <strong class=\"text-dark\">masculino de 48 años</strong>, presenta abultamiento umbilical.\n                            </p>\n                        </div>\n                        \n                        \n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n\n                    ','',0,''),(28,3,3,'texto','Evolución clínica','<div class=\"container my-5\">\n    <div class=\"row\">\n        <div class=\"col-lg-10 mx-auto\">\n            <div class=\"card border-0 shadow-sm\" style=\"border-radius: 20px;\">\n                <div class=\"card-body p-4 p-md-5\">\n                    \n                    <div class=\"d-flex align-items-center mb-5\">\n                        <div class=\"bg-danger bg-opacity-10 p-2 rounded-circle me-3\">\n                            <i class=\"bi bi-activity text-danger fs-3\"></i>\n                        </div>\n                        <h2 class=\"card-title mb-0 fw-bold text-dark\">Historia de la Enfermedad Actual</h2>\n                    </div>\n\n                    <div class=\"row g-4\">\n                        <div class=\"col-md-6\">\n                            <h6 class=\"text-uppercase text-muted fw-bold mb-4 small tracking-wider\">Antecedentes</h6>\n                            \n                            <div class=\"position-relative ps-4 border-start border-2 border-primary border-opacity-25\">\n\n                                <div class=\"mb-4 position-relative\">\n                                    <div class=\"position-absolute start-0 translate-middle-x bg-danger rounded-circle\" style=\"width: 12px; height: 12px; left: -25px !important; top: 8px;\"></div>\n                                    <h6 class=\"fw-bold mb-1\">Inicio:</h6>\n                                    <p class=\"text-muted small mb-0\">Abultamiento en ombligo desde hace varios años</p>\n                                </div>\n\n                                <div class=\"mb-4 position-relative\">\n                                    <div class=\"position-absolute start-0 translate-middle-x bg-danger rounded-circle\" style=\"width: 12px; height: 12px; left: -25px !important; top: 8px;\"></div>\n                                    <h6 class=\"fw-bold mb-1\">Observación:</h6>\n                                    <p class=\"text-muted small mb-0\">Ha incrementado de tamaño y causa dolor al esfuerzo.</p>\n                                </div>\n\n                                <div class=\"mb-4 position-relative\">\n                                    <div class=\"position-absolute start-0 translate-middle-x bg-danger rounded-circle\" style=\"width: 12px; height: 12px; left: -25px !important; top: 8px;\"></div>\n                                    <h6 class=\"fw-bold mb-1\">Heredofamiliares:</h6>\n                                    <p class=\"text-muted small mb-0\">Padre portado de Diabetes mellitus tipo 2 de 20 años.</p>\n                                </div>\n                                \n                                <div class=\"mb-0 position-relative\">\n                                    <div class=\"position-absolute start-0 translate-middle-x bg-danger rounded-circle\" style=\"width: 12px; height: 12px; left: -25px !important; top: 8px;\"></div>\n                                    <h6 class=\"fw-bold mb-1\">Personales patológicos:</h6>\n                                    <p class=\"text-muted small mb-0\">Diabetes mellitus tipo 2 de 8 años de evolución, en manejo con Metformina 850mg vía oral cada 12hrs, Hipertensión arterial sistémica de 8 años de diagnóstico en tratamiento con Losartan 50mg vía oral cada 12hrs. Niega antecedentes quirúrgicos, alergias negadas, tabaquismo positivo, suspendido hace 3 años, ingesta de bebidas alcohólicas de manera ocasional.</p>\n                                </div>\n                            </div>\n                        </div>\n\n                        <div class=\"col-md-6\">\n                            <h6 class=\"text-uppercase text-muted fw-bold mb-4 small tracking-wider\">Padecimiento actual</h6>\n                            \n                            <div class=\"d-flex flex-column gap-3\">\n                                <div class=\"p-3 rounded-3 bg-light d-flex align-items-center\">\n                                    <i class=\"bi bi-plus-circle-fill text-success me-3 fs-5\"></i>\n                                    <div>\n                                        <p class=\"mb-0 fw-medium\">Trabajador operativo de empresa refresquera (carga y descarga de producto), hasta 50 kilos de peso por carga, refiere le gusta agilizar tiempos.</p>\n                                        <small class=\"text-muted\">Acude a consulta ya que refiere aumento progresivo de volumen en región umbilical desde hace aproximadamente 8 años, inicialmente reductible y asintomático. Desde hace 6 meses presenta dolor tipo punzante posterior a esfuerzos físicos laborales (levantamiento de cajas de refresco), presentando aumento de tamaño de la hernia y dificultad para la reducción manual de la misma, niega náusea, menciona canaliza gases, evacuaciones al corriente. </small>\n                                    </div>\n                                </div>\n\n                                \n                            </div>\n                        </div>\n                    </div>\n\n                </div>\n            </div>\n        </div>\n    </div>\n</div>','',0,NULL),(29,3,4,'pregunta','Exploración física en UMF','<div class=\"container mt-5 mb-5\">\n    <div class=\"row justify-content-center\">\n        <div class=\"col-lg-6\">\n            <div class=\"card border-0 shadow-lg overflow-hidden\" style=\"border-radius: 20px;\">\n                <div class=\"bg-dark p-2 text-center text-white-50 small tracking-wider\">\n                    <i class=\"bi bi-activity me-2\"></i> MONITOR DE SIGNOS VITALES\n                </div>\n                <div class=\"bg-light p-3 text-center\">\n                    <img src=\"../img/signosVitales2.png\" class=\"img-fluid rounded\" alt=\"Signos Vitales\" style=\"max-height: 400px; width: auto;\">\n                </div>\n            </div>\n        </div>\n        <div class=\"col-lg-6\">\n            \n            <div class=\"container my-4\">\n\n    <div class=\"text-center mb-4\">\n\n<h4 class=\"text-primary\">En el paciente con hernia umbilical reductible programado para cirugía electiva con antecedente de Diabetes Mellitus tipo 2...</h4>\n\n        <h4 class=\"mb-0\">\n\n            ¿Cuál es el parámetro más útil para evaluar el control glucémico preoperatorio a mediano plazo?\n\n        </h4>\n\n    </div>\n\n    <div id=\"retroalimentacion\" class=\"mb-4\"></div>\n\n    <div class=\"row g-3\">\n\n        \n\n    <div class=\"col-md-6\">\n\n        <button\n\n            class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2 d-flex align-items-center\"\n\n            style=\"border-radius:15px;\"\n\n            onclick=\"\n\n                guardarRespuesta(\'A\',0);\n\n                document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                <div\n                    class=\'alert alert-danger border-0 shadow animate__animated animate__shakeX\'\n                    style=\'border-radius:20px;\'>\n\n                    <div class=\'d-flex align-items-center mb-2\'>\n\n                        <i class=\'bi bi-x-circle-fill text-danger fs-4 me-2\'></i>\n\n                        <h5 class=\'fw-bold mb-0\'>\n                            Retroalimentación\n                        </h5>\n\n                    </div>\n\n                    <hr>\n\n                    <p class=\'mb-1\'>\n\n                        <strong>\n\n                            Respuesta correcta:\n                            C\n\n                        </strong>\n\n                    </p>\n\n                    <p class=\'small mb-0 text-dark\'>\n\n                        Respuesta incorrecta, la respuesta correcta es la C\n\n                    </p>\n\n                </div>\n\n                `;\n\n            \">\n\n            <span class=\"badge bg-dark me-3\">\n\n                A\n\n            </span>\n\n            <span>\n\n                Glucosa sérica en ayuno\n\n            </span>\n\n        </button>\n\n    </div>\n\n    \n\n        \n\n    <div class=\"col-md-6\">\n\n        <button\n\n            class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2 d-flex align-items-center\"\n\n            style=\"border-radius:15px;\"\n\n            onclick=\"\n\n                guardarRespuesta(\'B\',0);\n\n                document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                <div\n                    class=\'alert alert-danger border-0 shadow animate__animated animate__shakeX\'\n                    style=\'border-radius:20px;\'>\n\n                    <div class=\'d-flex align-items-center mb-2\'>\n\n                        <i class=\'bi bi-x-circle-fill text-danger fs-4 me-2\'></i>\n\n                        <h5 class=\'fw-bold mb-0\'>\n                            Retroalimentación\n                        </h5>\n\n                    </div>\n\n                    <hr>\n\n                    <p class=\'mb-1\'>\n\n                        <strong>\n\n                            Respuesta correcta:\n                            C\n\n                        </strong>\n\n                    </p>\n\n                    <p class=\'small mb-0 text-dark\'>\n\n                        Respuesta incorrecta, la respuesta correcta es la C\n\n                    </p>\n\n                </div>\n\n                `;\n\n            \">\n\n            <span class=\"badge bg-dark me-3\">\n\n                B\n\n            </span>\n\n            <span>\n\n                Insulina basal\n\n            </span>\n\n        </button>\n\n    </div>\n\n    \n\n        \n\n    <div class=\"col-md-6\">\n\n        <button\n\n            class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2 d-flex align-items-center\"\n\n            style=\"border-radius:15px;\"\n\n            onclick=\"\n\n                guardarRespuesta(\'C\',1);\n\n                document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                <div\n                    class=\'alert alert-success border-0 shadow animate__animated animate__bounceIn\'\n                    style=\'border-radius:20px;\'>\n\n                    <div class=\'d-flex align-items-center mb-2\'>\n\n                        <i class=\'bi bi-check-circle-fill text-success fs-4 me-2\'></i>\n\n                        <h5 class=\'fw-bold mb-0\'>\n                            ¡Excelente!\n                        </h5>\n\n                    </div>\n\n                    <hr>\n\n                    <p class=\'mb-1\'>\n\n                        <strong>\n\n                            Respuesta correcta:\n                            C\n\n                        </strong>\n\n                    </p>\n\n                    <p class=\'small mb-0 text-dark\'>\n\n                        La HbA1c permite evaluar el control glucémico promedio en los últimos 2-3 meses, siendo un predictor importante del riesgo de complicaciones postoperatorias como infección de sitio quirúrgico y dehiscencia de herida en pacientes diabéticos. Se recomienda optimizar el control glucémico precio a cirugía electiva cuando HbA1c>8%.\n\n                    </p>\n\n                </div>\n\n                `;\n\n            \">\n\n            <span class=\"badge bg-dark me-3\">\n\n                C\n\n            </span>\n\n            <span>\n\n                Hemoglobina glucosilada (HbA1c)\n\n            </span>\n\n        </button>\n\n    </div>\n\n    \n\n        \n\n    <div class=\"col-md-6\">\n\n        <button\n\n            class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2 d-flex align-items-center\"\n\n            style=\"border-radius:15px;\"\n\n            onclick=\"\n\n                guardarRespuesta(\'D\',0);\n\n                document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                <div\n                    class=\'alert alert-danger border-0 shadow animate__animated animate__shakeX\'\n                    style=\'border-radius:20px;\'>\n\n                    <div class=\'d-flex align-items-center mb-2\'>\n\n                        <i class=\'bi bi-x-circle-fill text-danger fs-4 me-2\'></i>\n\n                        <h5 class=\'fw-bold mb-0\'>\n                            Retroalimentación\n                        </h5>\n\n                    </div>\n\n                    <hr>\n\n                    <p class=\'mb-1\'>\n\n                        <strong>\n\n                            Respuesta correcta:\n                            C\n\n                        </strong>\n\n                    </p>\n\n                    <p class=\'small mb-0 text-dark\'>\n\n                        Respuesta incorrecta, la respuesta correcta es la C\n\n                    </p>\n\n                </div>\n\n                `;\n\n            \">\n\n            <span class=\"badge bg-dark me-3\">\n\n                D\n\n            </span>\n\n            <span>\n\n                Glucosa postprandial\n\n            </span>\n\n        </button>\n\n    </div>\n\n    \n\n    </div>\n\n</div>\n\n\n\n        </div>\n    </div>\n</div>','',1,'C'),(30,3,5,'texto','Impresión clínica inicial','<div class=\"container my-5\">\n    <div class=\"row justify-content-center\">\n        <div class=\"col-lg-10\">\n            <div class=\"card border-0 shadow-lg\" style=\"border-radius: 20px; background: linear-gradient(145deg, #ffffff, #f8f9ff);\">\n                <div class=\"card-body p-4 p-md-5\">\n                    \n                    <div class=\"d-flex align-items-center mb-4\">\n                        <div class=\"bg-primary p-3 rounded-3 shadow-sm me-4\">\n                            <i class=\"bi bi-clipboard2-pulse text-white fs-2\"></i>\n                        </div>\n                        <div>\n                            <h6 class=\"text-primary fw-bold text-uppercase mb-1\" style=\"letter-spacing: 1px;\">Fase de Análisis</h6>\n                            <h2 class=\"fw-bold text-dark mb-0\">Impresión Clínica Inicial</h2>\n                        </div>\n                    </div>\n\n                    <div class=\"row g-4\">\n                        <div class=\"col-md-4\">\n                            <div class=\"p-4 h-100 rounded-4 border-start border-4 border-primary bg-white shadow-sm\">\n                                <div class=\"d-flex align-items-center mb-3\">\n                                    <span class=\"badge rounded-pill bg-primary me-2\">1</span>\n                                    <h5 class=\"fw-bold mb-0\">Hernia umbilical no complicada</h5>\n                                </div>\n                                <h4 class=\"text-dark fw-bold mb-3\">Defecto herniario umbilical reductible</h4>\n                                <p class=\"text-muted small mb-0\">\n                                    Presencia de saco herniario reducible, doloroso a la palpación profunda, sin datos clínicos de incarceración, estrangulación ni compromiso vascular agudo.\n                                </p>\n                            </div>\n                        </div>\n\n                        <div class=\"col-md-4\">\n                            <div class=\"p-4 h-100 rounded-4 border-start border-4 border-primary bg-white shadow-sm\">\n                                <div class=\"d-flex align-items-center mb-3\">\n                                    <span class=\"badge rounded-pill bg-primary me-2\">2</span>\n                                    <h5 class=\"fw-bold mb-0\">Diabetes Mellitus 2 </h5>\n                                </div>\n                                <h4 class=\"text-dark fw-bold mb-3\">Comorbilidad metabólica crónica</h4>\n                                <p class=\"text-muted small mb-0\">\n                                    Antecedente de diabetes mellitus tipo 2 que incrementa el riesgo de complicaciones metabólicas, retraso en cicatrización y eventos infecciosos postquirúrgicos.\n                                </p>\n                            </div>\n                        </div>\n\n                        <div class=\"col-md-4\">\n                            <div class=\"p-4 h-100 rounded-4 border-start border-4 border-danger bg-white shadow-sm\">\n                                <div class=\"d-flex align-items-center mb-3\">\n                                    <span class=\"badge rounded-pill bg-danger me-2\">2</span>\n                                    <h5 class=\"fw-bold mb-0\">Hipertensión arterial sistémica</h5>\n                                </div>\n                                <h4 class=\"text-dark fw-bold mb-3\">Comorbilidad cardiovascular asociada</h4>\n                                <p class=\"text-muted small mb-0\">\n                                    Paciente con antecedente de hipertensión arterial sistémica, actualmente con cifras tensionales elevadas, requiriendo vigilancia hemodinámica perioperatoria.\n                                </p>\n                            </div>\n                        </div>\n                    </div>\n\n                    <div class=\"mt-4 p-3 bg-warning bg-opacity-10 border border-warning border-opacity-25 rounded-3\">\n                        <div class=\"d-flex\">\n                            <i class=\"bi bi-exclamation-triangle-fill text-warning me-3 fs-4\"></i>\n                            <div>\n                                <span class=\"fw-bold text-dark d-block\">Nota de Guardia:</span>\n                                <span class=\"small text-white\">Paciente con hernia umbilical sintomática y comorbilidades crónicas asociadas. Se recomienda valoración por cirugía general para definir manejo definitivo y control integral de factores de riesgo metabólicos y cardiovasculares.</span>\n                            </div>\n                        </div>\n                    </div>\n\n                </div>\n            </div>\n        </div>\n    </div>\n</div>','',0,NULL),(31,3,6,'pregunta','En pacientes diabéticos programados para cirugía electiva, ¿cuál es la recomendación respecto al uso de Metformina?','<div class=\"container my-4\">\n\n    <div id=\"retroalimentacion\" class=\"mb-4\"></div>\n\n    <div class=\"row g-3\">\n\n        \n\n    <div class=\"col-md-6\">\n\n        <button\n\n            class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2 d-flex align-items-center\"\n\n            style=\"border-radius:15px;\"\n\n            onclick=\"\n\n                guardarRespuesta(\'A\',0);\n\n                document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                <div\n                    class=\'alert alert-danger border-0 shadow animate__animated animate__shakeX\'\n                    style=\'border-radius:20px;\'>\n\n                    <div class=\'d-flex align-items-center mb-2\'>\n\n                        <i class=\'bi bi-x-circle-fill text-danger fs-4 me-2\'></i>\n\n                        <h5 class=\'fw-bold mb-0\'>\n                            Retroalimentación\n                        </h5>\n\n                    </div>\n\n                    <hr>\n\n                    <p class=\'mb-1\'>\n\n                        <strong>\n\n                            Respuesta correcta:\n                            B\n\n                        </strong>\n\n                    </p>\n\n                    <p class=\'small mb-0 text-dark\'>\n\n                        Respuesta correcta: B    Suspender 24hrs previas\n\n                    </p>\n\n                </div>\n\n                `;\n\n            \">\n\n            <span class=\"badge bg-dark me-3\">\n\n                A\n\n            </span>\n\n            <span>\n\n                Continuar hasta el día de la cirugía\n\n            </span>\n\n        </button>\n\n    </div>\n\n    \n\n        \n\n    <div class=\"col-md-6\">\n\n        <button\n\n            class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2 d-flex align-items-center\"\n\n            style=\"border-radius:15px;\"\n\n            onclick=\"\n\n                guardarRespuesta(\'B\',1);\n\n                document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                <div\n                    class=\'alert alert-success border-0 shadow animate__animated animate__bounceIn\'\n                    style=\'border-radius:20px;\'>\n\n                    <div class=\'d-flex align-items-center mb-2\'>\n\n                        <i class=\'bi bi-check-circle-fill text-success fs-4 me-2\'></i>\n\n                        <h5 class=\'fw-bold mb-0\'>\n                            ¡Excelente!\n                        </h5>\n\n                    </div>\n\n                    <hr>\n\n                    <p class=\'mb-1\'>\n\n                        <strong>\n\n                            Respuesta correcta:\n                            B\n\n                        </strong>\n\n                    </p>\n\n                    <p class=\'small mb-0 text-dark\'>\n\n                        La Metformina debe suspenderse previo al procedimiento quirúrgico debido al riesgo potencial de acidosis láctica en situaciones de hipoperfusión o uso de medios de contraste.\n\n                    </p>\n\n                </div>\n\n                `;\n\n            \">\n\n            <span class=\"badge bg-dark me-3\">\n\n                B\n\n            </span>\n\n            <span>\n\n                Suspender 24hrs previas\n\n            </span>\n\n        </button>\n\n    </div>\n\n    \n\n        \n\n    <div class=\"col-md-6\">\n\n        <button\n\n            class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2 d-flex align-items-center\"\n\n            style=\"border-radius:15px;\"\n\n            onclick=\"\n\n                guardarRespuesta(\'C\',0);\n\n                document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                <div\n                    class=\'alert alert-danger border-0 shadow animate__animated animate__shakeX\'\n                    style=\'border-radius:20px;\'>\n\n                    <div class=\'d-flex align-items-center mb-2\'>\n\n                        <i class=\'bi bi-x-circle-fill text-danger fs-4 me-2\'></i>\n\n                        <h5 class=\'fw-bold mb-0\'>\n                            Retroalimentación\n                        </h5>\n\n                    </div>\n\n                    <hr>\n\n                    <p class=\'mb-1\'>\n\n                        <strong>\n\n                            Respuesta correcta:\n                            B\n\n                        </strong>\n\n                    </p>\n\n                    <p class=\'small mb-0 text-dark\'>\n\n                        Respuesta correcta: B    Suspender 24hrs previas\n\n                    </p>\n\n                </div>\n\n                `;\n\n            \">\n\n            <span class=\"badge bg-dark me-3\">\n\n                C\n\n            </span>\n\n            <span>\n\n                Suspender 7 días previos\n\n            </span>\n\n        </button>\n\n    </div>\n\n    \n\n        \n\n    <div class=\"col-md-6\">\n\n        <button\n\n            class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2 d-flex align-items-center\"\n\n            style=\"border-radius:15px;\"\n\n            onclick=\"\n\n                guardarRespuesta(\'D\',0);\n\n                document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                <div\n                    class=\'alert alert-danger border-0 shadow animate__animated animate__shakeX\'\n                    style=\'border-radius:20px;\'>\n\n                    <div class=\'d-flex align-items-center mb-2\'>\n\n                        <i class=\'bi bi-x-circle-fill text-danger fs-4 me-2\'></i>\n\n                        <h5 class=\'fw-bold mb-0\'>\n                            Retroalimentación\n                        </h5>\n\n                    </div>\n\n                    <hr>\n\n                    <p class=\'mb-1\'>\n\n                        <strong>\n\n                            Respuesta correcta:\n                            B\n\n                        </strong>\n\n                    </p>\n\n                    <p class=\'small mb-0 text-dark\'>\n\n                        Respuesta correcta: B    Suspender 24hrs previas\n\n                    </p>\n\n                </div>\n\n                `;\n\n            \">\n\n            <span class=\"badge bg-dark me-3\">\n\n                D\n\n            </span>\n\n            <span>\n\n                Duplicar dosis día previo\n\n            </span>\n\n        </button>\n\n    </div>\n\n    \n\n    </div>\n\n</div>\n\n','',1,'B'),(32,3,7,'texto','Estudios de laboratorio','<div class=\"container my-5\">\n    <div class=\"row justify-content-center\">\n        <div class=\"col-lg-11\">\n            <div class=\"card border-0 shadow-lg\" style=\"border-radius: 20px; background-color: #fcfcfc;\">\n                \n                <div class=\"d-flex\">\n                    <div class=\"bg-success text-white px-4 py-2\" style=\"border-radius: 20px 20px 0 0; font-size: 0.85rem; font-weight: bold; letter-spacing: 1px; background-color: #1a4d3a !important;\">\n                        <i class=\"bi bi-file-earmark-medical me-2\"></i>REPORTE DE RESULTADOS: FOLIO 250524\n                    </div>\n                </div>\n\n                <div class=\"card-body p-4 border-top border-success border-4\" style=\"border-radius: 0 15px 15px 15px;\">\n                    <div class=\"row align-items-center\">\n                        \n                        <div class=\"col-xl-7 text-center mb-4 mb-xl-0\">\n                            <div class=\"p-3 bg-white shadow-sm rounded border\">\n                                <img src=\"../img/estudiosLab2.png\" class=\"img-fluid rounded\" alt=\"Laboratorio IMSS\" style=\"max-height: 550px; width: auto;\">\n                            </div>\n                        </div>\n\n                        <div class=\"col-xl-5\">\n                            <div class=\"p-4 rounded-4 bg-white border shadow-sm\">\n                               <h5 class=\"fw-bold text-dark mb-4 d-flex align-items-center\">\n    <i class=\"bi bi-search me-2 text-success\"></i> Hallazgos Clave\n</h5>\n\n<div class=\"mb-4 p-3 rounded-3 bg-light border-start border-4 border-warning\">\n    <div class=\"d-flex justify-content-between align-items-center mb-1\">\n        <h6 class=\"fw-bold mb-0 text-warning text-dark\">Hiperglucemia</h6>\n        <span class=\"badge bg-warning text-dark\">162 mg/dL</span>\n    </div>\n    <p class=\"small text-muted mb-0\">\n        Glucosa sérica elevada compatible con descontrol metabólico en paciente con Diabetes Mellitus tipo 2.\n    </p>\n</div>\n\n<div class=\"mb-4 p-3 rounded-3 bg-light border-start border-4 border-danger\">\n    <div class=\"d-flex justify-content-between align-items-center mb-1\">\n        <h6 class=\"fw-bold mb-0 text-danger\">HbA1c Elevada</h6>\n        <span class=\"badge bg-danger\">8.1 %</span>\n    </div>\n    <p class=\"small text-muted mb-0\">\n        Indica control glucémico crónicamente inadecuado durante los últimos 3 meses.\n    </p>\n</div>\n\n<div class=\"mb-4 p-3 rounded-3 bg-light border-start border-4 border-success\">\n    <div class=\"d-flex justify-content-between align-items-center mb-1\">\n        <h6 class=\"fw-bold mb-0 text-success\">Función Renal Conservada</h6>\n        <span class=\"badge bg-success\">Cr 1.0 mg/dL</span>\n    </div>\n    <p class=\"small text-muted mb-0\">\n        Urea y creatinina dentro de parámetros normales, sin datos de deterioro renal agudo.\n    </p>\n</div>\n\n<div class=\"mb-4 p-3 rounded-3 bg-light border-start border-4 border-info\">\n    <div class=\"d-flex justify-content-between align-items-center mb-1\">\n        <h6 class=\"fw-bold mb-0 text-info\">Biometría Hemática Sin Alteraciones</h6>\n        <span class=\"badge bg-info\">Leucocitos 7,800/mm³</span>\n    </div>\n    <p class=\"small text-muted mb-0\">\n        Sin datos de leucocitosis ni respuesta inflamatoria sistémica activa al momento del estudio.\n    </p>\n</div>\n\n<div class=\"p-2 px-3 bg-success bg-opacity-10 rounded-pill text-center mt-2\">\n                                    <small class=\"text-white fw-bold\">\n                                        <i class=\"bi bi-shield-check me-1\"></i> \n        EGO, TP y TPT dentro de parámetros normales: sin evidencia de infección urinaria ni alteraciones de coagulación.\n    </small>\n</div>\n                            </div>\n                        </div>\n\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>','',0,NULL),(33,3,8,'pregunta','¿Cuál es la principal ventaja del ultrasonido abdominal en la evaluación preoperatoria de hernias umbilicales?','<div class=\"container my-4\">\n\n    <div class=\"text-center mb-4\">\n\n        <p class=\"text-muted small mb-0\">\n\n            \n\n        </p>\n\n    </div>\n\n    <div id=\"retroalimentacion\" class=\"mb-4\"></div>\n\n    <div class=\"row g-3\">\n\n        \n\n    <div class=\"col-md-6\">\n\n        <button\n\n            class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2 d-flex align-items-center\"\n\n            style=\"border-radius:15px;\"\n\n            onclick=\"\n\n                guardarRespuesta(\'A\',0);\n\n                document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                <div\n                    class=\'alert alert-danger border-0 shadow animate__animated animate__shakeX\'\n                    style=\'border-radius:20px;\'>\n\n                    <div class=\'d-flex align-items-center mb-2\'>\n\n                        <i class=\'bi bi-x-circle-fill text-danger fs-4 me-2\'></i>\n\n                        <h5 class=\'fw-bold mb-0\'>\n                            Retroalimentación\n                        </h5>\n\n                    </div>\n\n                    <hr>\n\n                    <p class=\'mb-1\'>\n\n                        <strong>\n\n                            Respuesta correcta:\n                       