   <button\n\n            class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2 d-flex align-items-center\"\n\n            style=\"border-radius:15px;\"\n\n            onclick=\"\n\n                guardarRespuesta(\'D\',0);\n\n                document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                <div\n                    class=\'alert alert-danger border-0 shadow animate__animated animate__shakeX\'\n                    style=\'border-radius:20px;\'>\n\n                    <div class=\'d-flex align-items-center mb-2\'>\n\n                        <i class=\'bi bi-x-circle-fill text-danger fs-4 me-2\'></i>\n\n                        <h5 class=\'fw-bold mb-0\'>\n                            Retroalimentación\n                        </h5>\n\n                    </div>\n\n                    <hr>\n\n                    <p class=\'mb-1\'>\n\n                        <strong>\n\n                            Respuesta correcta:\n                            B\n\n                        </strong>\n\n                    </p>\n\n                    <p class=\'small mb-0 text-dark\'>\n\n                        Respuesta correcta: B\n\n                    </p>\n\n                </div>\n\n                `;\n\n            \">\n\n            <span class=\"badge bg-dark me-3\">\n\n                D\n\n            </span>\n\n            <span>\n\n                Dolor epigástrico irradiado a espalda\n\n            </span>\n\n        </button>\n\n    </div>\n\n    \n\n    </div>\n\n</div>\n\n','',1,'B'),(51,6,5,'pregunta','Exploración física','Signos vitales\n<br>\n•	TA: 100/60 mmHg\n<br>\n•	FC: 112 lpm\n<br>\n•	FR: 22 rpm\n<br>\n•	Temp: 37.8 °C\n<br>\n•	SatO₂: 96%\n<br>\n<hr>\n<br>\nExploración abdominal\n<br>\n•	Distensión importante\n<br>\n•	Dolor difuso\n<br>\n•	Ruidos intestinales metálicos\n<br>\n•	Timpanismo generalizado\n<br>\n•	Cicatriz quirúrgica infraumbilical antigua\n\n\n                    \n\n<div class=\"container my-4\">\n\n    <div class=\"text-center mb-4\">\n\n        <p class=\"text-muted small mb-0\">\n\n            ¿Cuál es el diagnóstico más probable?\n\n        </p>\n\n    </div>\n\n    <div id=\"retroalimentacion\" class=\"mb-4\"></div>\n\n    <div class=\"row g-3\">\n\n        \n\n    <div class=\"col-md-6\">\n\n        <button\n\n            class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2 d-flex align-items-center\"\n\n            style=\"border-radius:15px;\"\n\n            onclick=\"\n\n                guardarRespuesta(\'A\',0);\n\n                document.getElementById(\'retroalimentacion\').innerHTML = `\n\n                <div\n                    class=\'alert alert-danger border-0 shadow animate__animated animate__shakeX\'\n                    style=\'border-radius:20px;\'>\n\n                    <div class=\'d-flex align-items-center mb-2\'>\n\n                        <i class=\'bi bi-x-circle-fill text-danger fs-4 me-2\'></i>\n\n                        <h5 class=\'fw-bold mb-0\'>\n                            Retroalimentación\n                        </h5>\n\n                    </div>\n\n                    <hr>\n\n                    <p class=\'mb-1\'>\n\n                        <strong>\n\n                            Respuesta correcta:\n                            C\n\n                        </strong>\n\n                    </p>\n\n                    <p class=\'small mb-0 text-dark\'>\n\n                        Respuesta correcta: C\n\n                    </p>\n\n                </div>\n\n                `;\n\n            \">\n\n            <span class=\"badge bg-dark me-3\">\n\n                A\n\n            </span>\n\n            <span>\n\n                Gastroenteritis aguda\n\n            </span>\n\n        </button>\n\n    </div>\n\n    \n\n        \n\n    <div class=\"col-md-6\">\n\n        <button\n\n            class=\"btn btn-outline-primary text-start p-3 w-100 h-100 shadow-sm border-2 d-flex align-items-center\