INSERT INTO `especialidades` VALUES (1,'ALERGIA E INMUNOLOGÍA','immunology','#235b4e',1),(2,'ANGIOLOGÍA Y CIR VAS','monitor_heart','#235b4e',1),(3,'MEDICINA DE URGENCIAS','emergency','#235b4e',1),(4,'CIRUGÍA GENERAL','surgical','#235b4e',1),(5,'CIRUGÍA MAXILO FACIAL','face','#235b4e',1),(6,'CARDIOLOGÍA','heart_plus','#235b4e',1),(7,'TRAUMATOLOGÍA Y ORTOPEDIA','orthopedics','#235b4e',1),(8,'FISIOPATOLOGÍA CARDIOPULMONAR','air','#235b4e',1),(9,'CARDIOLOGÍA INTERVENCIONISTA','cardiology','#235b4e',1),(10,'CIRUGÍA CARDIOTORÁCICA','favorite','#235b4e',1),(11,'texto de prueba','','#000000',1);
