--
-- Table structure for table `examen_preguntas`
--

DROP TABLE IF EXISTS `examen_preguntas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `examen_preguntas` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_examen` int(11) NOT NULL,
  `pregunta` text DEFAULT NULL,
  `opcion_a` text DEFAULT NULL,
  `opcion_b` text DEFAULT NULL,
  `opcion_c` text DEFAULT NULL,
  `opcion_d` text DEFAULT NULL,
  `respuesta_correcta` enum('A','B','C','D') DEFAULT NULL,
  `explicacion` text DEFAULT NULL,
  `dificultad` varchar(50) DEFAULT NULL,
  `orden_pregunta` int(11) DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_id_examen` (`id_examen`)
) ENGINE=InnoDB AUTO_INCREMENT=92 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

