INSERT INTO `examen_preguntas` VALUES (1,1,'¿Cuál es la causa más común de apendicitis aguda?','Infección viral','Obstrucción luminal por facalito','Trombosis arterial','Perforación intestina','B','La fisiopatología clásica inicia con obstrucción luminal, siendo el fecalito la causa más frecuente en adultos, lo que genera aumento de la presión intraluminal, compromiso vascular, proliferación bacteriana e inflamación.','media',1),(2,2,'¿Qué obtendría si añado polvo de raíces de asfódelo a una infusión de ajenjo?','Poción Filtro de Muertos en Vida','Una poción multijugos','Un filtro de invisibilidad','Un bezoar','A','Es claro que la fama no lo es todo, para tu información el asfódelo y el ajenjo hacen una poción de sueño tan poderosa, que se conoce como la posima de los muertos vivientes','media',0),(3,3,'¿Qué obtendría si añado polvo de raíces de asfódelo a una infusión de ajenjo?','Poción Filtro de Muertos en Vida','Una poción multijugos','Un filtro de invisibilidad','Un bezoar','A','Es claro que la fama no lo es todo, para tu información el asfódelo y el ajenjo hacen una poción de sueño tan poderosa, que se conoce como la posima de los muertos vivientes','media',0),(4,1,'El punto de máximo dolor abdominal en apendicitis aguda se localiza en:','Punto de Lanz','Punto de Mc Burney','Punto de Murphy','Punto de Traube ','B','El punto de McBurney corresponde a la unión del tercio medio con el tercio externo de la línea entre la espina iliaca anterosuperior derecha y el ombligo, siendo el sitio clásico de dolor somático. ','media',2),(5,1,'¿Cuál es el síntoma inicial más común en apendicitis aguda?','Fiebre','Dolor en fosa iliaca derecha','Dolor periumbilical','Diarrea ','C','El dolor visceral inicial se presenta en región periumbilical por estimulación de fibras aferentes viscerales T8-T10.','media',3),(6,1,'Escala clínica más utilizada para el diagnóstico de apendicitis aguda:','Glasgow','Alvarado','SOFA','APACHE II','B','La escala de Alvarado permite estratificar el riesgo clínico mediante síntomas, signos y laboratorio.','media',4),(7,1,'Un valor de >7pts en escala de Alvarado índica: ','Bajo riesgo','Riesgo Intermedio','Alto riesgo','Diagnóstico descartado','C','Una puntuación >7 sugiere alta probabilidad de apendicitis y generalmente indica intervención quirúrgica','media',5),(8,1,'¿Cuál es el estudio de imagen de elección en adultos para escrutinio de apendicitis aguda?','Radiografía simple','Ultrasonido abdominal','Tomografía simple contrastada','Resonancia Magnética','C','La tomografía tiene sensibilidad y especificidad superior al 90% en adultos.','media',6),(9,1,'Diámetro apendicular sugestivo de inflamación en TAC','>4mm','>5mm','>6mm','>10mm','C','Un diámetro >6mm con engrosamiento parietal es sugestivo de apendicitis aguda','media',7),(10,1,'Signo clínico de apendicitis aguda por irritación del músculo psoas:','Rovsing','Blumberg','Obturador','Psoas','D','Sugiere apéndice en posición retrocecal con contacto al psoas.','media',8),(11,1,'Principal Bacteria implicada en apendicitis aguda:','Streptococcus pneumoniae','Escherichia coli','Clostridium difficile','Mycobacterium','B','E. coli es el microorganismo más frecuentemente aislado','media',9),(12,1,'Complicación más frecuente de apendicitis aguda no tratada','Perforación','Sepsis','Obstrucción intestinal','Íleo paralítico','A','La perforación es la complicación más frecuente y aumenta la morbimortalidad.','media',10),(13,1,'El signo de Rovsing evalúa:','Irritación vesical','Irritación peritoneal','Inflamación hepática','Compresión renal ','B','Dolor en fosa iliaca derecha al comprimir fosa iliaca izquierda sugiere irritación peritoneal.','media',11),(14,1,'Según escalas de riesgo y evolución clínica del paciente, ¿a partir de que cifra en la cuenta leucocitaria, es sospecha de apendicitis aguda?','<4,000','5,000 – 7,000','>10,000','<2,000','C','Presente en el 80% de los pacientes.','media',12),(15,1,'¿Cuál escala predice mejor apendicitis complicada?','RIPASA','AIR score','APGAR','MELD','B','AIR score, tiene mejor discriminación para apendicitis complicada','media',13),(16,1,'Tratamiento estándar en apendicitis aguda:','Antibióticos ','Apendicectomía','Dieta','Observación ','B','La apendicetomía sigue siendo el estándar de oro.','media',14),(17,1,'Técnica quirúrgica de elección actual','Abierta ','Laparoscópica','Endoscópica','Percutánea','B','Menor estancia hospitalaria y menor tasa de infección.','media',15),(18,1,'Tiempo ideal de intervención quirúrgica','>72 horas','24-48hrs ','<24hrs','7 días','C','La intervención temprana reduce perforación.','media',16),(19,1,'Hallazgo histopatológico característico:','Necrosis grasa','infiltrado neutrofilico transmural','Fibrosis ','Calcificación','B','El diagnóstico definitivo se basa en infiltrado neutrofilico transmural','media',17),(20,1,'Factor de riesgo de perforación:','Edad joven','Diagnóstico temprano','Retraso diagnóstico','Uso de antibióticos','C','Retraso >48hrs incrementa riesgo de perforación.','media',18),(21,1,'Marcador bioquímico de respuesta inflamatoria útil en el diagnóstico complementario de apendicitis aguda:','PCR','Troponina','Bilirrubina','Creatinina','A','La PCR se asocia con severidad y apendicitis complicada','media',19),(22,1,'¿Cuál de las siguientes escalas incorpora proteína C reactiva (PCR) como parte de sus variables para predecir apendicitis complicada?','Escala AIR','Escala Alvarado','Escala de Fenyo','Escala de Ohmann','A','La Appendicitis Inflammatory Response Score (AIR) incluye PCR, lo cual mejora su capacidad para identificar apendicitis complicada. La elevación significativa de PCR se ha relacionado con perforación, absceso o gangrena apendicular.','media',20),(23,1,'¿Cuál de las siguientes escalas clínicas incluye parámetros como migración del dolor, anorexia, náusea, rebote, leucocitosis y neutrofilia para estratificar el riesgo de apendicitis aguda? ','Escala de Alvarado','Escala RIPASA','Escala AIR','Escala de Lintula','A','La Escala de Alvarado (también conocida como MANTRELS) es una de las herramientas más utilizadas para evaluar la probabilidad de apendicitis aguda. Incluye síntomas, signos clínicos y datos de laboratorio. Un puntaje ≥7 sugiere alta probabilidad y se asocia con mayor riesgo de progresión a formas complicadas si no se interviene oportunamente.','media',21),(24,1,'En la escala AIR, un puntaje mayor de 9 se interpreta como: ','Riesgo bajo de apendicitis','Riesgo intermedio de apendicitis no complicada','Alta probabilidad de apendicitis complicada','Apendicitis descartada','C','Un puntaje alto en la Escala AIR indica una intensa respuesta inflamatoria sistémica, la cual se correlaciona con formas avanzadas de la enfermedad como perforación o peritonitis localizada.','media',22),(25,1,'¿Cuál es el principal objetivo de utilizar escalas de riesgo en pacientes con sospecha de apendicitis aguda complicada? ','Sustituir estudios de imagen','Confirmar diagnóstico histopatológico','Determinar tipo de incisión quirúrgica','Estratificar riesgo y guiar conducta terapéutica','D','Las escalas permiten clasificar a los pacientes en grupos de bajo, mediano o alto riesgo, facilitando decisiones clínicas como observación, solicitud de imagen o intervención quirúrgica temprana, disminuyendo así complicaciones.','media',23),(26,4,'La hernia umbilical en el adulto se produce principalmente por:','Alteración congénita','Debilidad adquirida en la fascia umbilical','Necrosis muscular','Traumatismo abdominal','B','En el adulto, la hernia umbilical es una patología adquirida, secundaria a debilidad del anillo umbilical asociada a aumento de la presión intra abdominal.','media',1),(27,4,'Principal factor de riesgo para desarrollo de hernia umbilical en adultos:','Hipertensión','Obesidad','Tabaquismo','Diabetes','B','La obesidad incrementa la presión intraabdominal favoreciendo la protrusión del contenido abdominal','media',2),(28,4,'Contenido más frecuente del saco herniario:','Estómago','Colon sigmoides','Epiplón','Hígado','C','El epiplón es el contenido más frecuente debido a su movilidad intraabdominal. ','media',3),(29,4,'Principal complicación de la hernia umbilical no tratada:','Isquemia renal','Estrangulación','Apendicitis','Pancreatitis','B','La estrangulación puede ocasionar compromiso vascular y necrosis intestinal.','media',4),(30,4,'Tratamiento definitivo de la hernia umbilical:','Antibióticos','Observación','Hernioplastia','Dieta','C','El tratamiento es quirúrgico mediante reparación del defecto fascial.','media',5),(31,4,'Técnica recomendada en defectos >2cm:','Sutura simple','Malla protésica','Ligadura','Laparotomía','B','La malla reduce la tasa de recurrencia.','media',6),(32,4,'Indicador clínico de incarceración:','Masa reductible','Dolor súbito irreductible','Hipotensión','Bradicardia','B','La irreductibilidad dolorosa indica incarceración.','media',7),(33,4,'La hernia umbilical complicada requiere:','Manejo ambulatorio','Cirugía urgente','Antiinflamatorios','Reposo','B','La sospecha de estrangulación requiere intervención urgente','media',8),(34,4,'Complicación postoperatoria más frecuente:','Hemorragia intracraneal','Seroma','IAM','Neumonía','B','El seroma es la complicación mas frecuente.','media',9),(35,4,'Técnica con menor recurrencia:','Sutura primaria','Reparación con malla','Observación','Ligadura','B','La reparación con malla reduce recurrencia','media',10),(36,4,'Indicación de cirugía programada:','Hernia estrangulada','Hernia reductible','Peritonitis','Sepsis','B','Las hernias reductibles se programan electivamente.','media',11),(37,4,'Estudio de imagen útil preoperatorio:','TAC','ECG','Colonoscopia','Radiografía ','A','Permite valorar contenido y complicaciones.','media',12),(38,4,'Clasificación que evalúa estado físico preoperatorio:','Glasgow','ASA','SOFA','APGAR','B','ASA III Implica enfermedad sistémica significativa','media',13),(39,4,'Paciente ASA III presenta:','Enfermedad leve','Enfermedad sistémica severa','Paciente sano','Muerte cerebral','B','ASA III implica enfermedad sistémica significativa','media',14),(40,4,'Tiempo de ayuno recomendado para líquidos claros:','8 hrs','6 hrs','2 hrs','12 hrs','C','Reduce riesgo de bronco aspiración','media',15),(41,4,'Estudio obligatorio en mayores de 40 años','TAG','ECG','Colonoscopia','Endoscopia','B','Permite detectar alteraciones cardiacas.','basica',16),(42,4,'Objetivo de valoración preoperatoria:','Diagnóstico','Evaluar riesgo quirúrgico','Alta hospitalaria','Nutrición','B','Permite disminuir complicaciones.','basica',17),(43,4,'Escala de riesgo cardiovascular:','RCRI','Glasgow','APACHE','MELD','A','Predice eventos cardiacos perioperatorios','basica',18),(44,4,'¿Cuál es la hemoglobina mínima recomendada para evento quirúrgico?','5g/dL','7g/dL','15g/dL','20g/dL','B','Evita hipoxia tisular.','basica',19),(45,4,'Consentimiento informado debe incluir:','Diagnóstico únicamente','Riesgos y beneficios','Nombre del hospital','Dirección','B','Es requisito legal y ético.','basica',20),(46,4,'En el paciente con hernia umbilical reductible programado para cirugía electiva con antecedente de Diabetes Mellitus tipo 2, ¿Cuál es el parámetro más útil para evaluar el control glucémico preoperatorio a mediano plazo?','Glucosa sérica en ayuno','Insulina basal','Hemoglobina glucosilada (HbA1c)','Glucosa postprandial','C','C  La HbA1c permite evaluar el control glucémico promedio en los últimos 2-3 meses, siendo un predictor importante del riesgo de complicaciones postoperatorias como infección de sitio quirúrgico y dehiscencia de herida en pacientes diabéticos. Se recomienda optimizar el control glucémico precio a cirugía electiva cuando HbA1c>8%.','media',21),(47,4,'En pacientes diabéticos programados para cirugía electiva, ¿cuál es la recomendación respecto al uso de Metformina?','Continuar hasta el día de la cirugía','Suspender 24hrs previas','Suspender 7 días previos','Duplicar dosis día previo','B','La Metformina debe suspenderse previo al procedimiento quirúrgico debido al riesgo potencial de acidosis láctica en situaciones de hipoperfusión o uso de medios de contraste.','media',22),(48,4,'¿Cuál es la principal ventaja del ultrasonido abdominal en la evaluación preoperatoria de   hernias umbilicales?','Determinar el tipo de anestesia','Medir presión intra abdominal','Identificar contenido del saco herniario','Evaluar función intestinal','C','El ultrasonido permite identificar ek tamaño del defecto herniario y el contenido del saco (epiplón o asas intestinales), además de evaluar complicaciones como incarceración o estrangulación. ','media',23),(49,4,'De acuerdo con la clasificación ASA, ¿Cómo se clasifica un paciente con Diabetes Mellitus tipo 2 e Hipertensión arterial sistémica controlado farmacológicamente?','ASA I','ASA II','ASA III','ASAIV','B','La clasificación ASA II incluye pacientes con enfermedad sistémica leve a moderada bien controlada, sin limitación funcional significativa, como diabetes o hipertensión controladas.','media',24),(50,4,'¿Cuál es la principal indicación para el uso de malla en la reparación de hernia umbilical en adultos?','Defectos menores de 1cm','Presentación de infección activa','Defectos mayores de 2cm','Hernia incarcerada','C',': Las guías actuales recomiendan el uso de malla en defectos mayores de 2cm debido a la significativa disminución en la tasa de recurrencia comparada con la reparación primaria con sutura.','media',25),(51,4,'¿Cuál es el principal factor de riesgo asociado a infección de sitio quirúrgico en el paciente  del caso clínico?','Edad','Ocupación','Diabetes Mellitus','Tipo de sutura','C','La hiperglucemia postoperatoria altera la función leucocitaria y la cicatrización, aumentando el riesgo de infección en el sitio quirúrgico en pacientes diabéticos sometidos a procedimientos quirúrgicos.','media',26),(52,5,'¿Cuál es la causa más frecuente de oclusión intestinal mecánica en adultos?','Hernia inguinal incarcerada','Adherencias postquirúrgicas','Enfermedad de Crohn','Vólvulo de sigmoides','B','Las adherencias postquirúrgicas representan la causa más frecuente de obstrucción intestinal mecánica en adultos, siendo responsables de aproximadamente 60–75% de los casos. Se originan posterior a procedimientos abdominales por formación de bandas fibrosas.','media',1),(53,5,'¿Cuál es el síntoma cardinal de la oclusión intestinal?','Hematemesis','Dolor abdominal tipo cólico','Melena','Disuria','B','El dolor abdominal tipo cólico es el síntoma cardinal de la oclusión intestinal mecánica y ocurre por el incremento del peristaltismo intestinal intentando vencer la obstrucción.','media',2),(54,5,'En una oclusión intestinal alta, el vómito suele presentarse:','Tardíamente y fecaloide','Ausente','Tempranamente y abundante','Solo con perforación','C','Las obstrucciones proximales generan vómitos tempranos y abundantes debido a la rápida acumulación de contenido gastrointestinal proximal al sitio obstructivo.','media',3),(55,5,'Hallazgo radiográfico clásico en oclusión intestinal:','Aire subdiafragmático','Niveles hidroaéreos múltiples','Calcificaciones pancreáticas','Neumoperitoneo masivo','B','Los niveles hidroaéreos múltiples y la dilatación de asas intestinales son hallazgos clásicos en radiografía simple de abdomen en pacientes con obstrucción intestinal.','basica',4),(56,5,'Diámetro sugestivo de dilatación patológica en intestino delgado:','>1 cm','>2 cm','>3 cm','>6 cm','C','Se considera dilatación patológica del intestino delgado cuando el diámetro supera los 3 cm.','media',5),(57,5,'¿Cuál es el principal riesgo de una oclusión intestinal estrangulada?','Pancreatitis','Isquemia intestinal','Gastritis','Hepatitis','B','La estrangulación compromete el flujo sanguíneo intestinal, causando isquemia, necrosis y eventual perforación intestinal.','media',6),(58,5,'¿Qué dato clínico orienta más a estrangulación intestinal?','Dolor leve intermitente','Ausencia de vómito','Dolor continuo intenso con irritación peritoneal','Hipotensión aislada','C','El dolor continuo intenso acompañado de datos de irritación peritoneal es sugestivo de compromiso vascular intestinal.','media',7),(59,5,'¿Cuál es el estudio de imagen de elección para confirmar oclusión intestinal?','Ultrasonido','Resonancia magnética','TAC abdominal contrastada','Colon por enema','C','La tomografía computada contrastada posee alta sensibilidad y especificidad para localizar el sitio obstructivo e identificar complicaciones.','media',8),(60,5,'Principal alteración hidroelectrolítica en vómito prolongado:','Acidosis metabólica','Hipercalcemia','Alcalosis metabólica hipoclorémica','Hipermagnesemia','C','La pérdida de ácido clorhídrico por vómito provoca alcalosis metabólica hipoclorémica e hipokalemia.','media',9),(61,5,'¿Cuál es la medida inicial más importante en el manejo de oclusión intestinal?','Cirugía inmediata en todos los casos','Ayuno y reanimación hídrica','Laxantes estimulantes','Dieta blanda','B','El manejo inicial incluye ayuno, reposición de líquidos intravenosos y corrección de alteraciones hidroelectrolíticas.','media',10),(62,5,'¿Cuál es la causa más frecuente de oclusión intestinal en pacientes sin cirugía previa?','Adherencias','Hernias','Íleo paralítico','Colitis','B','En pacientes sin antecedente quirúrgico abdominal, las hernias incarceradas son causa frecuente de obstrucción intestinal mecánica.','media',11),(63,5,'¿Qué segmento intestinal se afecta con mayor frecuencia en obstrucción mecánica?','Colon descendente','Duodeno','Intestino delgado','Recto','C','El intestino delgado es el sitio más comúnmente afectado por obstrucción mecánica.','media',12),(64,5,'¿Cuál es un dato clínico típico del íleo?','Peristalsis aumentada','Ruidos metálicos','Ausencia de ruidos intestinales','Dolor cólico intenso','C','El íleo cursa con disminución o ausencia de peristalsis intestinal.','media',13),(65,5,'Hallazgo tomográfico sugestivo de estrangulación:','Aire portal','Engrosamiento parietal y neumatosis intestinal','Ascitis leve aislada','Divertículos colónicos','B','La neumatosis intestinal y el engrosamiento mural son signos de isquemia intestinal.','media',14),(66,5,'¿Cuál es la principal indicación quirúrgica urgente?','Distensión leve','Náusea aislada','Datos de isquemia o perforación','Estreñimiento leve','C','La presencia de estrangulación, perforación o peritonitis requiere intervención quirúrgica inmediata.','media',15),(67,5,'¿Qué tipo de sonda se utiliza frecuentemente para descompresión gastrointestinal?','Foley','Levin o nasogástrica','Pezzer','Nelaton','B','La sonda nasogástrica disminuye distensión abdominal y riesgo de bronco aspiración.','media',16),(68,5,'¿Cuál es una complicación potencial de la obstrucción intestinal prolongada?','Hipotiroidismo','Necrosis intestinal','Colecistitis','Nefrolitiasis','B','La progresión de la isquemia puede producir necrosis intestinal y sepsis abdominal.','media',17),(69,5,'¿Cuál es el hallazgo clínico más frecuente en exploración física?','Rigidez generalizada inicial','Distensión abdominal','Ictericia','Bradicardia','B','La distensión abdominal es uno de los hallazgos más frecuentes en obstrucción intestinal.','media',18),(70,5,'¿Qué tipo de dolor suele presentarse en obstrucción intestinal mecánica?','Somático constante desde el inicio','Tipo cólico intermitente','Dolor pleurítico','Dolor lumbar irradiado','B','El aumento del peristaltismo intestinal genera dolor tipo cólico.','media',19),(71,5,'¿Cuál es el objetivo principal de la reanimación hídrica?','Disminuir la fiebre','Corregir hipovolemia y alteraciones electrolíticas','Evitar cirugía','Disminuir leucocitosis','B','La obstrucción intestinal ocasiona secuestro de líquidos intraluminales y deshidratación significativa.','media',20),(72,6,'¿Cuál es el mecanismo de lesión más frecuente en una fractura de Colles?','Golpe directo sobre codo flexionado','Caída sobre mano en extensión','Traumatismo rotacional de hombro','Compresión axial sobre cadera','B','La fractura de Colles clásicamente ocurre posterior a una caída sobre la mano extendida (FOOSH), generando transmisión axial de energía hacia el radio distal.','media',1),(73,6,'La deformidad clásica observada en fractura de Colles es:','Mano caída','Deformidad en bayoneta','Dorso de tenedor','Garra cubital','C','El desplazamiento dorsal del fragmento distal produce la deformidad típica denominada “dorso de tenedor” o “dorso de cuchara”.','media',2),(74,6,'¿Qué hueso se encuentra lesionado en la fractura de Colles?','Escafoides','Radio distal','Cúbito proximal','Semilunar','B','La fractura de Colles corresponde a una fractura metafisaria del radio distal con desplazamiento dorsal.','media',3),(75,6,'¿Cuál es el grupo poblacional más afectado?','Hombres jóvenes deportistas','Mujeres posmenopáusicas','Adolescentes masculinos','Niños escolares','B','La osteoporosis posmenopáusica incrementa significativamente el riesgo de fracturas de radio distal en mujeres mayores.','media',4),(76,6,'¿Cuál es el estudio inicial de elección para el diagnóstico?','Resonancia magnética','Ultrasonido','Radiografía AP y lateral de muñeca','Gammagrama óseo','C','Las radiografías AP y lateral permiten confirmar la fractura y valorar desplazamiento, angulación y compromiso articular.','media',5),(77,6,'Hallazgo radiográfico característico en fractura de Colles:','Desplazamiento volar','Luxación carpiana pura','Angulación dorsal distal','Fractura diafisaria cubital aislada','C','La angulación dorsal del fragmento distal constituye uno de los hallazgos clásicos de esta lesión.','media',6),(78,6,'¿Cuál nervio debe valorarse cuidadosamente por riesgo de compresión?','Nervio axilar','Nervio musculocutáneo','Nervio mediano','Nervio femoral','C','El edema y desplazamiento óseo pueden ocasionar síndrome del túnel del carpo agudo por compresión del nervio mediano.','media',7),(79,6,'¿Qué parámetro radiográfico normal corresponde al “volar tilt”?','45° dorsal','11° volar','30° radial','5° cubital','B','El radio distal normalmente presenta una inclinación volar aproximada de 11° en la proyección lateral.','media',8),(80,6,'¿Cuál es el principal objetivo de la reducción cerrada?','Disminuir fiebre','Restaurar alineación anatómica','Evitar analgesia','Disminuir edema exclusivamente','B','La reducción busca recuperar la anatomía del radio distal para preservar la función y disminuir complicaciones futuras.','media',9),(81,6,'Dato sugestivo de inestabilidad en fractura distal de radio:','Angulación dorsal >20°','Edema leve','Dolor controlado','Ausencia de equimosis','A','La angulación dorsal significativa incrementa el riesgo de pérdida de reducción y mal pronóstico funcional.','media',10),(82,6,'¿Cuál es la complicación neurológica más frecuente?','Lesión radial alta','Neuropatía cubital','Compresión del nervio mediano','Plexopatía braquial','C','La neuropatía del nervio mediano puede presentarse secundaria a edema, hematoma o desplazamiento fracturario.','media',11),(83,6,'¿Cuál es una indicación frecuente de tratamiento quirúrgico?','Fractura estable no desplazada','Consolidación completa','Fractura intra articular desplazada','Dolor leve aislado','C','Las fracturas intraarticulares desplazadas suelen requerir reducción abierta y fijación interna para restaurar congruencia articular.','media',12),(84,6,'¿Cuál es la inmovilización inicial más utilizada?','Yeso pelvipédico','Férula braquipalmar','Vendaje elástico simple','Tutor cervical','B','La férula braquipalmar permite inmovilización adecuada y control del edema inicial.','media',13),(85,6,'¿Qué complicación tardía puede presentarse por mala alineación?','Hipertiroidismo','Artrosis postraumática','Hepatitis','Pancreatitis','B','La consolidación viciosa altera la biomecánica articular favoreciendo artrosis y limitación funcional.','media',14),(86,6,'¿Qué factor incrementa más el riesgo de fractura de Colles en adultos mayores?','Hipertensión arterial','Osteoporosis','Migraña','Asma','B','La disminución de densidad mineral ósea incrementa la fragilidad del radio distal ante traumatismos de baja energía.','media',15),(87,6,'¿Qué dato obliga a vigilancia urgente posterior a inmovilización?','Dolor leve controlado','Parestesias progresivas','Equimosis local','Edema moderado','B','Las parestesias progresivas pueden indicar compresión neurovascular o síndrome compartimental.','media',16),(88,6,'¿Cuál es la principal ventaja de la placa volar?','Evita rehabilitación','Mayor estabilidad biomecánica','Elimina dolor inmediatamente','Disminuye osteoporosis','B','Las placas volares ofrecen estabilidad angular y permiten movilización más temprana.','media',17),(89,6,'¿Qué estructura anatómica participa en la estabilidad radiocubital distal?','Ligamento cruzado','Complejo fibrocartílago triangular','Tendón rotuliano','Manguito rotador','B','El complejo fibrocartílago triangular es esencial para estabilidad de la articulación radiocubital distal.','media',18),(90,6,'¿Cuál es un criterio radiográfico de mala alineación posterior a reducción?','Volar tilt normal','Acortamiento radial >5 mm','Ausencia de edema','Integridad cutánea','B','El acortamiento radial importante se asocia con limitación funcional y pérdida de fuerza.','media',19),(91,6,'¿Cuál es el objetivo principal de la rehabilitación temprana?','Incrementar edema','Evitar consolidación','Recuperar movilidad y función','Disminuir densidad ósea','C','La movilización y rehabilitación progresiva disminuyen rigidez y mejoran resultados funcionales.','media',20);
/*!40000 ALTER TABLE `examen_preguntas` ENABLE KEYS */;
