dad.html?id=4'),(14,'tema','Obstrucción intestinal','Obstrucción intestinal Interrupción parcial o total del tránsito intestinal sec... ','Interrupción parcial o total del tránsito intestinal sec... ',4,4,NULL,NULL,'../pages/especialidad.html?id=4'),(15,'tema','Síndrome coronario agudo (SCA)','Síndrome coronario agudo (SCA) UNIDAD DE EDUCACIÓN E INVESTIGACIÓN ','UNIDAD DE EDUCACIÓN E INVESTIGACIÓN ',3,5,NULL,NULL,'../pages/especialidad.html?id=3'),(16,'tema','Tema 2','Tema 2 UNIDAD DE EDUCACIÓN E INVESTIGACIÓN ','UNIDAD DE EDUCACIÓN E INVESTIGACIÓN ',3,6,NULL,NULL,'../pages/especialidad.html?id=3'),(17,'tema','Politrauma','Politrauma Multiples lesiones','Multiples lesiones',7,7,NULL,NULL,'../pages/especialidad.html?id=7'),(18,'caso','Apendicitis aguda complicada','Apendicitis aguda complicada Caso clínico interactivo de cirugía','Caso clínico interactivo de cirugía',4,1,1,NULL,'../pages/caso.html?id=1'),(19,'caso','Sindrome coronario agudo sin elevación del segmento ST','Sindrome coronario agudo sin elevación del segmento ST UNIDAD DE EDUCACIÓN E INVESTIGACIÓN ','UNIDAD DE EDUCACIÓN E INVESTIGACIÓN ',3,5,2,NULL,'../pages/caso.html?id=2'),(20,'caso','Hernia umbilical no complicada','Hernia umbilical no complicada UNIDAD DE EDUCACIÓN E INVESTIGACIÓN','UNIDAD DE EDUCACIÓN E INVESTIGACIÓN',4,2,3,NULL,'../pages/caso.html?id=3'),(21,'caso','Sindrome coronario agudo con elevación persistente del segmento ST','Sindrome coronario agudo con elevación persistente del segmento ST UNIDAD DE EDUCACIÓN E INVESTIGACIÓN ','UNIDAD DE EDUCACIÓN E INVESTIGACIÓN ',3,5,4,NULL,'../pages/caso.html?id=4'),(22,'caso','Politrauma en adulto mayor','Politrauma en adulto mayor lorem impsum','lorem impsum',7,7,5,NULL,'../pages/caso.html?id=5'),(23,'caso','Oclusión intestital','Oclusión intestital UNIDAD DE EDUCACIÓN E INVESTIGACIÓN','UNIDAD DE EDUCACIÓN E INVESTIGACIÓN',4,3,6,NULL,'../pages/caso.html?id=6'),(24,'escena','Introducción','\n    \n        \n        \n            \n                \n                    \n                        \n                            \n                        \n                        Objetivo educativo del módulo\n                    \n                    \n                        \n                            1\n                            Reconocer los datos clínicos sugestivos de apendicitis aguda complicada.\n                        \n                        \n                            2\n                            Aplicar escalas clínicas y de riesgo para la toma de decisiones.\n                        \n                        \n                            3\n                            Seleccionar estudios diagnósticos adecuados según el contexto.\n                        \n                        \n                            4\n                            Integrar un plan terapéutico oportuno.\n                        \n                        \n                            5\n                            Identificar hallazgos quirúrgicos y evaluar la evolución posoperatoria.\n                        \n                    \n                \n            \n        \n\n        \n        \n            \n                \n                    \n                        \n                            \n                        \n                        Perfil del usuario\n                    \n                    \n                        Médicos generales\n                        Médicos internos de pregrado\n                        Residentes de urgencias\n                        Cirugía general\n                        Personal en formación\n                    \n                    \n                    \n                         Contenido diseñado para fortalecer la toma de decisiones clínicas.\n                    \n                \n            \n        \n    \n','\n    \n        \n        \n            \n                \n                    \n                        \n                            \n                        \n                        Objetivo educativo del módulo\n                    \n                    \n                        \n                        ',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=1'),(25,'escena','Escenario clínico','\n    \n        \n            \n                \n                    \n                    \n                        \n                            \n                                \n                                Tu navegador no soporta la reproducción de video.\n                            \n                        \n                    \n                    \n                    \n                        \n                            \n                            \n\n\n\n                            \n                            Análisis en curso...\n                        \n\n\n                        \n                        \n                        \n                            \n                                Paciente masculino de 20 años acude a urgencias por dolor abdominal de 18 horas de evolución.\n                            \n                        \n                        \n                        \n                    \n                \n            \n        \n    \n','\n    \n        \n            \n                \n                    \n                    \n                        \n                            \n                                \n                                Tu navegador no soporta la reproducción de video.\n                            \n              ',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=2'),(26,'escena','Evolución clínica','\n    \n        \n            \n                \n                    \n                    \n                        \n                            \n                        \n                        Historia de la Enfermedad Actual\n                    \n\n                    \n                        \n                            Progreso del Dolor\n                            \n                            \n                                \n                                    \n                                    Inicio\n                                    Región periumbilical, intensidad moderada EVA 5/10\n                                \n                                \n                                \n                                    \n                                    Migración\n                                    Hacia fosa ilíaca derecha, aumento de intensidad EVA 8/10\n                                \n                            \n                        \n\n                        \n                            Hallazgos Clínicos\n                            \n                            \n                                \n                                    \n                                    \n                                        Síntomas asociados\n                                        Anorexia, náusea, fiebre subjetiva.\n                                    \n                                \n\n                                \n                                    \n                                    \n                                        Negativos funcionales\n                                        Diarrea, sangrado digestivo, síntomas urinarios.\n                                    \n                                \n                            \n                        \n                    \n\n                \n            \n        \n    \n','\n    \n        \n            \n                \n                    \n                    \n                        \n                            \n                        \n                        Historia de la Enfermedad Actual\n                    \n\n                    \n                        \n         ',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=3'),(27,'escena','¿Cuál es la presentación clínica sugestiva de apendicitis aguda en la población adulta?','Retroalimentación\n\n\n\n\n    \n        \n            A\n            Dolor de inicio súbito en fosa iliaca derecha\n        \n    \n\n    \n         \n            B\n            Dolor que inicia en región dorsal\n        \n    \n\n\n\n\n\n    \n        \n            C\n            \n                Dolor abdominal peri umbilical de 24-48 horas de evolución que migra y se localiza en la fosa iliaca derecha\n            \n        \n    \n\n    \n        \n            D\n            Dolor en fosa iliaca izquierda migrante a fosa iliaca derecha\n        \n    \n','Retroalimentación\n\n\n\n\n    \n        \n            A\n            Dolor de inicio súbito en fosa iliaca derecha\n        \n    \n\n    \n         \n            B\n            Dolor que inicia en región dorsal\n        \n    \n\n\n\n\n\n    \n        \n            C\n            \n                Dolor abdominal peri um',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=4'),(28,'escena','Exploración física','\n    \n        \n            \n                \n                     MONITOR DE SIGNOS VITALES\n                \n                \n                    \n                \n            \n        \n        \n            \n                Razonamiento Clínico\n                ¿Cuál es el diagnóstico más probable con la información inicial?\n            \n\n            \n\n            \n                \n                    \n                        A\n                        Gastroenteritis\n                    \n                \n\n                \n                    \n                        B\n                        Apendicitis aguda\n                    \n                \n            \n            \n            \n                \n                    \n                        C\n                        Cólico renal\n                    \n                \n\n                \n                    \n                        D\n                        Obstrucción intestinal\n                    \n                \n            \n\n        \n    \n','\n    \n        \n            \n                \n                     MONITOR DE SIGNOS VITALES\n                \n                \n                    \n                \n            \n        \n        \n            \n                Razonamiento Clínico\n                ¿Cuál es el diagnóstico más probab',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=5'),(29,'escena','Impresión clínica inicial','\n    \n        \n            \n                \n                    \n                    \n                        \n                            \n                        \n                        \n                            Fase de Análisis\n                            Impresión Clínica Inicial\n                        \n                    \n\n                    \n                        \n                            \n                                \n                                    1\n                                    Análisis Sindromático\n                                \n                                Abdomen agudo quirúrgico probable\n                                \n                                    Se establece por la presencia de dolor abdominal progresivo, datos de irritación peritoneal y respuesta inflamatoria sistémica en evolución.\n                                \n                            \n                        \n\n                        \n                            \n                                \n                                    2\n                                    Sospecha Diagnóstica\n                                \n                                Apendicitis aguda complicada\n                                \n                                    Basado en la Cronología de Murphy positiva y el tiempo de evolución (>18 horas), lo que incrementa el riesgo de perforación o plastrón.\n                                \n                            \n                        \n                    \n\n                    \n                        \n                            \n                            \n                                Nota de Guardia:\n                                Se requiere integración inmediata de estudios paraclínicos y valoración por cirugía general para definir conducta definitiva.\n                            \n                        \n                    \n\n                \n            \n        \n    \n','\n    \n        \n            \n                \n                    \n                    \n                        \n                            \n                        \n                        \n                            Fase de Análisis\n                            Impresión Clínica Inicial\n       ',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=6'),(30,'escena','Estudios de laboratorio','\n    \n        \n            \n                \n                \n                    \n                        REPORTE DE RESULTADOS: FOLIO 250523\n                    \n                \n\n                \n                    \n                        \n                        \n                            \n                                \n                            \n                        \n\n                        \n                            \n                                \n                                     Hallazgos Clave\n                                \n                                \n                                \n                                    \n                                        Leucocitosis Severa\n                                        14,000/mm³\n                                    \n                                    Indica una respuesta inmunológica activa ante el proceso infeccioso/inflamatorio.\n                                \n\n                                \n                                    \n                                        Desviación a la izquierda\n                                        85% Neutrófilos\n                                    \n                                    La predominancia de neutrófilos confirma la etiología bacteriana aguda.\n                                \n\n                                \n                                    \n                                        Reactante de Fase Aguda\n                                        PCR 9 mg/dL\n                                    \n                                    La PCR elevada (>5 mg/dL) apoya el diagnóstico de apendicitis en fase avanzada.\n                                \n\n                                \n                                    \n                                         EGO y PFH normales: Se descarta foco urinario y hepatopatía.\n                                    \n                                \n                            \n                        \n\n                    \n                \n            \n        \n    \n','\n    \n        \n            \n                \n                \n                    \n                        REPORTE DE RESULTADOS: FOLIO 250523\n                    \n                \n\n                \n                    \n                        \n                        \n                            \n ',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=7'),(31,'escena','Rayos X de abdomen','\n    \n        \n            \n                \n                \n                    \n                        \n                            \n                        \n                        \n                            Rayos X de Abdomen\n                            Proyecciones: AP de pie y Decúbito\n                        \n                    \n                    DICOM Viewer v2.0\n                \n\n                \n                    \n                        \n                            \n                                \n                                PROYECCIÓN A\n                            \n                        \n                        \n                        \n                            \n                                \n                                PROYECCIÓN B\n                            \n                        \n                    \n\n                    \n                        \n                             Correlación Radiológica\n                        \n                        \n                        \n                            \n                                \n                                    \n                                    Gas Intestinal: Discreta dilatación de asas de intestino delgado en cuadrante inferior derecho.\n                                \n                            \n                            \n                                \n                                    \n                                    Niveles Hidroaéreos: Presencia de niveles en fosa ilíaca derecha (FID), sugestivos de íleo regional.\n                                \n                            \n                            \n                                \n                                    \n                                    Signos Opacos: Ausencia de aire en el colon distal (recto) y posible borramiento de la línea del psoas.\n                                \n                            \n                        \n                    \n                \n\n                \n                    \n                         Recordatorio: La radiografía tiene baja sensibilidad para apendicitis, pero ayuda a descartar obstrucción o perforación.\n                    \n                \n            \n        \n    \n','\n    \n        \n            \n                \n                \n                    \n                        \n                            \n                        \n                        \n                            Rayos X de Abdomen\n                            Proyecciones: AP de pie y Decúbito\n  ',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=8'),(32,'escena','Tomografía Computarizada (TAC o CT Scan)','\n    \n        \n            \n                \n                \n                    \n                        \n                            \n                        \n                        \n                            Tomografía Computarizada de Abdomen\n                            Visualización Avanzada con Contraste\n                        \n                    \n                    \n                        3D Reconst. v4.1\n                    \n                \n\n                \n                    \n                        \n                        \n                            \n                                \n                                    \n                                        \n                                        CORONAL\n                                    \n                                \n                                \n                                \n                                    \n                                        \n                                        AXIAL\n                                    \n                                \n                            \n                        \n\n                        \n                            \n                                \n                                    \n                                    \n                                        Análisis de Imagen\n                                        Haga correlación clínica con los siguientes hallazgos\n                                    \n                                \n                                \n                                \n                                    \n                                    \n                                        \n                                        \n                                            \n                                                Diámetro Aumentado\n                                                10 mm\n                                            \n                                            \n                                            Un diámetro >7 mm en la TAC es altamente predictivo de apendicitis aguda en el contexto clínico adecuado.\n                                        \n                                    \n\n                                    \n                                        \n                                        \n                                            Engrosamiento Mural\n                                            Sugiere inflamación y edema de la mucosa apendicular, a menudo con realce al contraste.\n                                        \n                                    \n\n                                    \n                                        \n                                        \n                                            Estriación de Grasa\n                                            \"Grasa sucia\" (aumento de la densidad peri-apendicular), indicativo de inflamación circundante.\n                                        \n                                    \n\n                                    \n                                        \n                                        \n                                            Líquido Libre Pericecal\n                                            Pequeña colección fluida cerca del ciego, sugiriendo complicación en fase temprana.\n                                        \n                                    \n\n                                    \n                                        \n                                        \n                                            Ausencia de Absceso\n                                            Dato crucial para la planificación quirúrgica: no se visualiza colección organizada.\n                                        \n                                    \n\n                                \n                            \n                        \n\n                    \n                \n\n                \n                    \n                         La TAC de Abdomen con contraste es el estándar de oro diagnóstico con sensibilidad y especificidad >95%.\n                    \n                \n            \n        \n    \n','\n    \n        \n            \n                \n                \n                    \n                        \n                            \n                        \n                        \n                            Tomografía Computarizada de Abdomen\n                            Visualización Avanz',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=9'),(33,'escena','Conclusión radiológica','\n    \n        \n            \n                \n                    \n                    \n                        \n                            \n                        \n                        Dictamen Final\n                        Hallazgos Concluyentes\n                    \n\n                    \n                        \n                            \n                                Servicio de Radiodiagnóstico\n                                Conclusión Radiológica\n                            \n                            \n                        \n\n                        \n                            \n                                \n                                \n                                    Apendicitis aguda complicada\n                                    Fase III (Fibrinopurulenta)\n                                \n                            \n\n                            \n                                \n                                \n                                    Probable apendicitis gangrenosa\n                                    Correlación con estriación grasa y líquido libre pericecal.\n                                \n                            \n                        \n\n                        \n                            \n                                Dr. Radiólogo de Turno\n                                Céd. Especialidad 7654321\n                            \n                            \n                                Validación Electrónica\n                                \n                            \n                        \n                    \n\n                \n            \n\n        \n    \n','\n    \n        \n            \n                \n                    \n                    \n                        \n                            \n                        \n                        Dictamen Final\n                        Hallazgos Concluyentes\n                    \n\n                    \n     ',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=10'),(34,'escena','Caso Simulado','\n\n    \n\n\n\n','\n\n    \n\n\n\n',3,NULL,NULL,NULL,'../pages/caso.html?id=2&escena=11'),(35,'escena','Introducción','\n    \n        \n        \n            \n                \n                    \n                        \n                            \n                        \n                        Objetivo educativo del módulo\n                    \n                    \n                        \n                            1\n                            Reconocer los datos clínicos sugestivos de apendicitis aguda complicada.\n                        \n                        \n                            2\n                            Aplicar escalas clínicas y de riesgo para la toma de decisiones.\n                        \n                        \n                            3\n                            Seleccionar estudios diagnósticos adecuados según el contexto.\n                        \n                        \n                            4\n                            Integrar un plan terapéutico oportuno.\n                        \n                        \n                            5\n                            Identificar hallazgos quirúrgicos y evaluar la evolución posoperatoria.\n                        \n                    \n                \n            \n        \n\n        \n        \n            \n                \n                    \n                        \n                            \n                        \n                        Perfil del usuario\n                    \n                    \n                        Médicos generales\n                        Médicos internos de pregrado\n                        Residentes de urgencias\n                        Cirugía general\n                        Personal en formación\n                    \n                    \n                    \n                         Contenido diseñado para fortalecer la toma de decisiones clínicas.\n                    \n                \n            \n        \n    \n','\n    \n        \n        \n            \n                \n                    \n                        \n                            \n                        \n                        Objetivo educativo del módulo\n                    \n                    \n                        \n                        ',4,NULL,NULL,NULL,'../pages/caso.html?id=3&escena=12'),(36,'escena','¿Cuál es la  posición anatómica más frecuente del apéndice?','\n\n    \n\n        \n\n            Seleccione la opción que considere correcta basándose en la incidencia epidemiológica.\n\n        \n\n    \n\n    \n\n    \n\n        \n        \n\n            \n\n                A\n\n            \n\n            \n\n                Retrocecal\n\n            \n\n        \n\n        \n        \n\n            \n\n                B\n\n            \n\n            \n\n                Pélvica\n\n            \n\n        \n\n        \n        \n\n            \n\n                C\n\n            \n\n            \n\n                Paracecal\n\n            \n\n        \n\n        \n        \n\n            \n\n                D\n\n            \n\n            \n\n                Subcecal\n\n            \n\n        \n\n    \n\n','\n\n    \n\n        \n\n            Seleccione la opción que considere correcta basándose en la incidencia epidemiológica.\n\n        \n\n    \n\n    \n\n    \n\n        \n        \n\n            \n\n                A\n\n            \n\n            \n\n                Retrocecal\n\n            \n\n        \n\n        \n        \n\n',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=13'),(37,'escena','Integración diagnóstica','\n    \n        \n            \n                \n                    \n                    \n                        Fase Final de Diagnóstico\n                        Integración Diagnóstica\n                        \n                    \n\n                    \n                        \n\n                        \n                            \n                            \n                                \n                                    \n                                        Diagnóstico Clínico\n                                        \n                                            \n                                        \n                                    \n                                    Basado en la tríada de Murphy y los hallazgos de irritación peritoneal localizados en fosa ilíaca derecha.\n                                \n                            \n\n                              \n                                \n                                    \n                                        \n                                            \n                                        \n                                        Escala AIR: Alto Riesgo\n                                    \n                                    Puntuación sugerente de alta probabilidad de apendicitis aguda, justificando la intervención inmediata.\n                                \n                            \n\n                            \n                                \n                                    \n                                        TC Confirmatoria\n                                        \n                                            \n                                        \n                                    \n                                    Evidencia de proceso inflamatorio apendicular (10mm), estriación de grasa y ausencia de gas distal.\n                                \n                            \n\n                        \n                    \n\n                    \n                        \n                            \n                                \n                                    \"La correlación de los tres pilares diagnósticos establece una indicación quirúrgica absoluta, minimizando el riesgo de una laparotomía negativa.\"\n                                \n                            \n                            \n                                CASO INTEGRADO\n                            \n                        \n                    \n\n                \n            \n        \n    \n','\n    \n        \n            \n                \n                    \n                    \n                        Fase Final de Diagnóstico\n                        Integración Diagnóstica\n                        \n                    \n\n                    \n                        \n\n                  ',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=14'),(38,'escena','¿Cuál de las siguientes escalas incorpora proteína C reactiva (PCR) como parte de sus variables para predecir apendicitis complicada?','\n\n    \n    \n\n        \n\n            \n\n                \n\n                \n                    SAS 2.0\n                \n\n            \n\n        \n\n        \n\n            \n\n                \n\n                \n                    Alvarado\n                \n\n            \n\n        \n\n        \n\n            \n\n                \n\n                \n                    AIR Score\n                \n\n            \n\n        \n\n        \n\n            \n\n                \n\n                \n                    RIPASA\n                \n\n            \n\n        \n\n    \n\n    \n    \n\n        \n\n            Evaluación de Riesgo\n\n        \n\n    \n\n    \n    \n\n    \n    \n\n        \n        \n\n            \n\n                \n                    A\n                \n\n                Escala AIR\n\n            \n\n        \n\n        \n        \n\n            \n\n                \n                    B\n                \n\n                Escala Alvarado\n\n            \n\n        \n\n        \n        \n\n            \n\n                \n                    C\n                \n\n                Escala de Fenyo\n\n            \n\n        \n\n        \n        \n\n            \n\n                \n                    D\n                \n\n                Escala de Ohmann\n\n            \n\n        \n\n    \n\n','\n\n    \n    \n\n        \n\n            \n\n                \n\n                \n                    SAS 2.0\n                \n\n            \n\n        \n\n        \n\n            \n\n                \n\n                \n                    Alvarado\n                \n\n            \n\n        \n\n        \n\n            \n\n    ',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=15'),(39,'escena','Diagnóstico final','\n    \n        \n            \n            \n                \n                    \n                    \n                        \n                            CRÍTICO • QUIRÚRGICO\n                        \n                    \n\n                    \n                        \n                            \n                                Correlación Anatomopatológica\n                                Diagnóstico Final\n                            \n                            \n                                \n                            \n                        \n\n                        \n                            Apendicitis aguda fase III (gangrenosa)\n                            \n                                Compromiso Vascular\n                                Urgencia Quirúrgica\n                            \n                        \n\n                        \n                            \n                                \n                                    \n                                \n                            \n                            \n                                Sin perforación evidente\n                                Integridad de la pared apendicular conservada a pesar de la necrosis transmural.\n                            \n                        \n\n                        \n                            \n                                Fecha de registro: 10 de Mayo, 2026\n                                Estatus: Confirmado por hallazgo macroscópico\n                            \n                            \n                                \n                            \n                        \n                    \n\n                \n            \n\n            \n                \n                La Fase III se caracteriza por la presencia de microperforaciones y compromiso del retorno venoso/arterial.\n            \n\n        \n    \n','\n    \n        \n            \n            \n                \n                    \n                    \n                        \n                            CRÍTICO • QUIRÚRGICO\n                        \n                    \n\n                    \n                        \n                            \n',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=16'),(40,'escena','¿Cuál es el siguiente paso terapéutico ideal?','\n\n    \n\n        \n\n            \n\n                Fase de Resolución\n\n            \n\n\n        \n\n    \n\n    \n    \n\n    \n    \n\n        \n        \n\n            \n\n                \n                    A\n                \n\n                \n                    Alta médica con analgésicos\n                \n\n            \n\n        \n\n        \n        \n\n            \n\n                \n                    B\n                \n\n                \n                    Antibióticos y preparación quirúrgica\n                \n\n            \n\n        \n\n        \n        \n\n            \n\n                \n                    C\n                \n\n                \n                    Observación sin intervención\n                \n\n            \n\n        \n\n        \n        \n\n            \n\n                \n                    D\n                \n\n                \n                    Solo antibióticos y alta médica\n                \n\n            \n\n        \n\n    \n\n','\n\n    \n\n        \n\n            \n\n                Fase de Resolución\n\n            \n\n\n        \n\n    \n\n    \n    \n\n    \n    \n\n        \n        \n\n            \n\n                \n                    A\n                \n\n                \n                    Alta médica con analgésicos\n                \n\n   ',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=17'),(41,'escena','Tratamiento instaurado','\n    \n        \n            \n            \n                \n                    \n                    \n                        \n                            Conducta Terapéutica\n                            Tratamiento Instaurado\n                        \n                        \n                            Estatus: Prioridad Quirúrgica\n                        \n                    \n\n                    \n                        \n                            \n                                \n                            \n                            Resolución vía quirúrgica\n                        \n\n                        \n                            \n                                \n                                    \n                                    \n                                        Régimen\n                                        Ayuno absoluto\n                                    \n                                \n                            \n                            \n                            \n                                \n                                    \n                                    \n                                        Vía Parenteral\n                                        Solución Hartmann (IV)\n                                    \n                                \n                            \n\n                            \n                                \n                                    \n                                    \n                                        Manejo de Dolor\n                                        Ketorolaco (IV)\n                                    \n                                \n                            \n\n                            \n                                \n                                    \n                                    \n                                        Profilaxis\n                                        Tromboprofilaxis mecánica\n                                    \n                                \n                            \n                        \n                    \n\n                    \n                        \n                            \n                                \n                                \n                                    Esquema Antibiótico Empírico\n                                    Ceftriaxona + Metronidazol (IV)\n                                \n                            \n                        \n                    \n\n                    \n                        \n                            Documento generado según protocolo IMSS\n                        \n                        \n                    \n\n                \n            \n\n        \n    \n','\n    \n        \n            \n            \n                \n                    \n                    \n                        \n                            Conducta Terapéutica\n                            Tratamiento Instaurado\n                        \n                        \n                        ',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=18'),(42,'escena','¿Cuál es el principal objetivo de utilizar escalas de riesgo en pacientes con sospecha de apendicitis aguda complicada?','\n\n    \n\n        \n\n            Estratificación de Riesgo\n\n        \n\n    \n\n    \n    \n\n    \n    \n\n        \n        \n\n            \n\n                \n                    A\n                \n\n                Sustituir estudios de imagen\n\n            \n\n        \n\n        \n        \n\n            \n\n                \n                    B\n                \n\n                Confirmar diagnóstico histopatológico\n\n            \n\n        \n\n        \n        \n\n            \n\n                \n                    C\n                \n\n                Estratificar riesgo y guiar conducta\n\n            \n\n        \n\n        \n        \n\n            \n\n                \n                    D\n                \n\n                Determinar tipo de incisión\n\n            \n\n        \n\n    \n\n','\n\n    \n\n        \n\n            Estratificación de Riesgo\n\n        \n\n    \n\n    \n    \n\n    \n    \n\n        \n        \n\n            \n\n                \n                    A\n                \n\n                Sustituir estudios de imagen\n\n            \n\n        \n\n        \n        \n\n            \n\n           ',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=19'),(43,'escena','Tratamiento quirúrgico','\n    \n        \n            \n            \n                \n                    \n                \n                \n                    Procedimiento en Curso\n                    Apendicectomía Laparoscópica de Urgencia\n                \n            \n\n            \n                \n                    \n                        ● REC\n                        Cam_01 / Laparoscopía\n                    \n                    \n                        \n                        \n                    \n                \n                \n                \n                    \n                        \n                        Tu navegador no soporta la reproducción de video.\n                    \n                \n\n                \n                    \n                        \n                            \n                                \n                                \n                                    Técnica\n                                    Tri-Port (3 Trocares)\n                                \n                            \n                        \n                        \n                            \n                                \n                                \n                                    Hallazgo\n                                    Fase III (Gangrenosa)\n                                \n                            \n                        \n                        \n                            \n                                \n                                \n                                    Seguridad\n                                    Aseo Peritoneal\n                                \n                            \n                        \n                    \n                \n            \n\n            \n                \n                \n                    Paso Clave: Observa la identificación de la base apendicular y el uso de energía ultrasónica o clips para el control del mesoapéndice.\n                \n            \n\n        \n    \n\n                    ','\n    \n        \n            \n            \n                \n                    \n                \n                \n                    Procedimiento en Curso\n                    Apendicectomía Laparoscópica de Urgencia\n                \n            \n\n            \n                \n                    ',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=20'),(44,'escena','Hallazgos trans operatorios','\n    \n        \n            \n            \n                \n                    \n                    \n                        \n                            \n                        \n                        Descripción Macroscópica\n                    \n\n                    \n                        \n                            \n                                Estado del Órgano\n                                \n                                    \n                                        \n                                        Apéndice edematoso y congestivo con áreas necróticas.\n                                    \n                                    \n                                        \n                                        Serosa opaca y friable al tacto instrumental.\n                                    \n                                \n                            \n                        \n\n                        \n                            \n                                Cavidad y Adyacentes\n                                \n                                    \n                                        \n                                        Presencia de líquido inflamatorio pericecal.\n                                    \n                                    \n                                        \n                                        Ciego sin lesiones aparentes.\n                                    \n                                    \n                                        \n                                        Sin evidencia de perforación o abscesos.\n                                    \n                                \n                            \n                        \n                    \n\n                    \n                        \n                            \n                                \n                            \n                            \n                                Clasificación Intraoperatoria\n                                Apendicitis gangrenosa (Fase III)\n                            \n                        \n                    \n\n                \n            \n\n        \n    \n','\n    \n        \n            \n            \n                \n                    \n                    \n                        \n                            \n                        \n                        Descripción Macroscópica\n                    \n\n                    \n                        \n  ',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=21'),(45,'escena','¿Cuál es la complicación más grave de una apendicitis no tratada?','\n\n    \n\n        \n\n            Análisis de Riesgo\n\n        \n\n        \n\n            ¿Cuál es la principal complicación de una\n            apendicitis aguda no tratada?\n\n        \n\n    \n\n    \n    \n\n    \n    \n\n        \n        \n\n            \n\n                \n                    A\n                \n\n                \n                    Pancreatitis\n                \n\n            \n\n        \n\n        \n        \n\n            \n\n                \n                    B\n                \n\n                \n                    Perforación y peritonitis\n                \n\n            \n\n        \n\n        \n        \n\n            \n\n                \n                    C\n                \n\n                \n                    Cirrosis hepática\n                \n\n            \n\n        \n\n        \n        \n\n            \n\n                \n                    D\n                \n\n                \n                    Aneurisma aórtico\n                \n\n            \n\n        \n\n    \n\n','\n\n    \n\n        \n\n            Análisis de Riesgo\n\n        \n\n        \n\n            ¿Cuál es la principal complicación de una\n            apendicitis aguda no tratada?\n\n        \n\n    \n\n    \n    \n\n    \n    \n\n        \n        \n\n            \n\n                \n                    A\n                \n\n ',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=22'),(46,'escena','Evolución Postquirúrgica','\n    \n        \n            \n            \n                \n                    \n                \n                \n                    Seguimiento Hospitalario\n                \n            \n\n            \n                \n                    \n                        \n                            Primeras 24–48 horas\n                        \n                        \n                            \n                                \n                                    \n                                    Evolución clínica favorable\n                                \n                                \n                                    \n                                    Paciente afebril\n                                \n                                \n                                    \n                                    Dolor controlado (Analgesia)\n                                \n                                \n                                    \n                                    Vía oral progresiva iniciada\n                                \n                                \n                                    \n                                    Leucocitos en descenso gradual\n                                \n                            \n                        \n                    \n                \n\n                \n                    \n                        \n                            Manejo Terapéutico\n                        \n                        \n                            \n                                \n                                    \n                                    \n                                        Antibioticoterapia IV\n                                        Continuación por 48 h (Esquema dirigido)\n                                    \n                                \n                                \n                                    \n                                    \n                                        Analgesia Multimodal\n                                        Combinación de fármacos para optimizar confort\n                                    \n                                \n                                \n                                    \n                                    \n                                        Movilización Temprana\n                                        Prevención de íleo y eventos trombóticos\n                                    \n                                \n                            \n                        \n                    \n                \n            \n\n            \n                \n                \n                    La recuperación exitosa en una Apendicitis Fase III depende estrictamente del cumplimiento del esquema antibiótico y la deambulación precoz.\n                \n            \n\n        \n    \n','\n    \n        \n            \n            \n                \n                    \n                \n                \n                    Seguimiento Hospitalario\n                \n            \n\n            \n                \n                    \n                        \n                            Primera',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=23'),(47,'escena','Egreso hospitalario','\n    \n        \n            \n            \n                \n                    \n                        Alta Hospitalaria\n                        Plan de Cuidados en Domicilio\n                    \n                    \n                \n\n                \n                    \n                    \n                        \n                            \n                                \n                            \n                            Condición del Paciente (48h)\n                        \n                        \n                        \n                            \n                                \n                                    \n                                    Hemodinámicamente estable\n                                \n                            \n                            \n                                \n                                    \n                                    Sin datos de infección\n                                \n                            \n                            \n                                \n                                    \n                                    Tolerancia a vía oral\n                                \n                            \n                            \n                                \n                                    \n                                    Heridas limpias y sanas\n                                \n                            \n                        \n                    \n\n                    \n                        \n                            Receta e Indicaciones\n                        \n                        \n                        \n                            \n                                \n                                    \n                                        \n                                    \n                                    \n                                        Esquema Antibiótico\n                                        Continuar vía oral por 5 días adicionales para completar ciclo.\n                                    \n                                \n                            \n                            \n                                \n                                    \n                                        \n                                    \n                                    \n                                        Analgesia\n                                        Manejo de rescate a demanda (PRN) según escala de dolor.\n                                    \n                                \n                            \n                            \n                                \n                                    \n                                        \n                                    \n                                    \n                                        Cuidados Generales\n                                        Reposo relativo. Evitar esfuerzos físicos intensos y carga de peso.\n                                    \n                                \n                            \n                            \n                                \n                                    \n                                        \n                                    \n                                    \n                                        Control Post-Op\n                                        Cita programada en 7 días para retiro de puntos y valoración final.\n                                    \n                                \n                            \n                        \n                    \n\n                \n            \n\n            \n                Signos de Alarma para Reingreso:\n                Fiebre >38°C, dolor abdominal intenso que no cede, vómito persistente o salida de material purulento por heridas.\n            \n\n        \n    \n','\n    \n        \n            \n            \n                \n                    \n                        Alta Hospitalaria\n                        Plan de Cuidados en Domicilio\n                    \n                    \n                \n\n                \n                    \n                    \n      ',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=24'),(48,'escena','Reservado a evolución clínica','\n    \n        \n            \n            \n                \n                    \n                        \n                        \n                            \n                                \n                            \n                            Pronóstico\n                            Bueno para la vida\n                            \n                                Basado en resolución quirúrgica oportuna y éxito terapéutico.\n                            \n                        \n\n                        \n                            \n                                Estado del Paciente\n                                Reservado a evolución clínica\n                            \n\n                            \n                                \n                                    \n                                        \n                                    \n                                    \n                                        Bajo riesgo de complicaciones\n                                        La intervención en Fase III sin perforación disminuye drásticamente la probabilidad de abscesos residuales o reintervenciones.\n                                    \n                                \n\n                                \n                                    \n                                        \n                                    \n                                    \n                                        Recuperación Funcional Ad Integrum\n                                        Se espera un retorno a las actividades habituales tras el periodo de convalecencia estándar.\n                                    \n                                \n                            \n\n                            \n                                \n                                    Probabilidad de Éxito\n                                    Alta\n                                \n                                \n                                    \n                                \n                            \n                        \n\n                    \n                \n            \n\n            \n                “El éxito del tratamiento quirúrgico es el reflejo de un diagnóstico clínico preciso y a tiempo.”\n                \n                    \n                        Reiniciar Caso\n                    \n                    \n\n    \n\n    Ver Resumen Final\n\n\n                \n            \n\n        \n    \n','\n    \n        \n            \n            \n                \n                    \n                        \n                        \n                            \n                                \n                            \n                            Pronóstico\n                            Bueno para l',4,NULL,NULL,NULL,'../pages/caso.html?id=1&escena=25'),(49,'escena','Introduccion','\n\n    Este es un texto de prueba UEI\n\n\n\n                    ','\n\n    Este es un texto de prueba UEI\n\n\n\n                    ',7,NULL,NULL,NULL,'../pages/caso.html?id=5&escena=26'),(50,'escena','Consulta inicial de medicina familiar','\n    \n        \n            \n                \n                    \n                    \n                        \n                            \n                                \n                                Tu navegador no soporta la reproducción de video.\n                            \n                        \n                    \n                    \n                    \n                        \n                            \n                            \n\n\n                        \n                            \n                            Análisis en curso...\n                        \n\n\n                        \n                        \n                        \n                            \n                                Paciente masculino de 48 años, presenta abultamiento umbilical.\n                            \n                        \n                        \n                        \n                    \n                \n            \n        \n    \n\n\n                    ','\n    \n        \n            \n                \n                    \n                    \n                        \n                            \n                                \n                                Tu navegador no soporta la reproducción de video.\n                            \n              ',4,NULL,NULL,NULL,'../pages/caso.html?id=3&escena=27'),(51,'escena','Evolución clínica','\n    \n        \n            \n                \n                    \n                    \n                        \n                            \n                        \n                        Historia de la Enfermedad Actual\n                    \n\n                    \n                        \n                            Antecedentes\n                            \n                            \n\n                                \n                                    \n                                    Inicio:\n                                    Abultamiento en ombligo desde hace varios años\n                                \n\n                                \n                                    \n                                    Observación:\n                                    Ha incrementado de tamaño y causa dolor al esfuerzo.\n                                \n\n                                \n                                    \n                                    Heredofamiliares:\n                                    Padre portado de Diabetes mellitus tipo 2 de 20 años.\n                                \n                                \n                                \n                                    \n                                    Personales patológicos:\n                                    Diabetes mellitus tipo 2 de 8 años de evolución, en manejo con Metformina 850mg vía oral cada 12hrs, Hipertensión arterial sistémica de 8 años de diagnóstico en tratamiento con Losartan 50mg vía oral cada 12hrs. Niega antecedentes quirúrgicos, alergias negadas, tabaquismo positivo, suspendido hace 3 años, ingesta de bebidas alcohólicas de manera ocasional.\n                                \n                            \n                        \n\n                        \n                            Padecimiento actual\n                            \n                            \n                                \n                                    \n                                    \n                                        Trabajador operativo de empresa refresquera (carga y descarga de producto), hasta 50 kilos de peso por carga, refiere le gusta agilizar tiempos.\n                                        Acude a consulta ya que refiere aumento progresivo de volumen en región umbilical desde hace aproximadamente 8 años, inicialmente reductible y asintomático. Desde hace 6 meses presenta dolor tipo punzante posterior a esfuerzos físicos laborales (levantamiento de cajas de refresco), presentando aumento de tamaño de la hernia y dificultad para la reducción manual de la misma, niega náusea, menciona canaliza gases, evacuaciones al corriente. \n                                    \n                                \n\n                                \n                            \n                        \n                    \n\n                \n            \n        \n    \n','\n    \n        \n            \n                \n                    \n                    \n                        \n                            \n                        \n                        Historia de la Enfermedad Actual\n                    \n\n                    \n                        \n         ',4,NULL,NULL,NULL,'../pages/caso.html?id=3&escena=28'),(52,'escena','Exploración física en UMF','\n    \n        \n            \n                \n                     MONITOR DE SIGNOS VITALES\n                \n                \n                    \n                \n            \n        \n        \n            \n            \n\n    \n\nEn el paciente con hernia umbilical reductible programado para cirugía electiva con antecedente de Diabetes Mellitus tipo 2...\n\n        \n\n            ¿Cuál es el parámetro más útil para evaluar el control glucémico preoperatorio a mediano plazo?\n\n        \n\n    \n\n    \n\n    \n\n        \n\n    \n\n        \n\n            \n\n                A\n\n            \n\n            \n\n                Glucosa sérica en ayuno\n\n            \n\n        \n\n    \n\n    \n\n        \n\n    \n\n        \n\n            \n\n                B\n\n            \n\n            \n\n                Insulina basal\n\n            \n\n        \n\n    \n\n    \n\n        \n\n    \n\n        \n\n            \n\n                C\n\n            \n\n            \n\n                Hemoglobina glucosilada (HbA1c)\n\n            \n\n        \n\n    \n\n    \n\n        \n\n    \n\n        \n\n            \n\n                D\n\n            \n\n            \n\n                Glucosa postprandial\n\n            \n\n        \n\n    \n\n    \n\n    \n\n\n\n\n\n        \n    \n','\n    \n        \n            \n                \n                     MONITOR DE SIGNOS VITALES\n                \n                \n                    \n                \n            \n        \n        \n            \n            \n\n    \n\nEn el paciente con hernia umbilical reductible programado para cirugía ',4,NULL,NULL,NULL,'../pages/caso.html?id=3&escena=29'),(53,'escena','Impresión clínica inicial','\n    \n        \n            \n                \n                    \n                    \n                        \n                            \n                        \n                        \n                            Fase de Análisis\n                            Impresión Clínica Inicial\n                        \n                    \n\n                    \n                        \n                            \n                                \n                                    1\n                                    Hernia umbilical no complicada\n                                \n                                Defecto herniario umbilical reductible\n                                \n                                    Presencia de saco herniario reducible, doloroso a la palpación profunda, sin datos clínicos de incarceración, estrangulación ni compromiso vascular agudo.\n                                \n                            \n                        \n\n                        \n                            \n                                \n                                    2\n                                    Diabetes Mellitus 2 \n                                \n                                Comorbilidad metabólica crónica\n                                \n                                    Antecedente de diabetes mellitus tipo 2 que incrementa el riesgo de complicaciones metabólicas, retraso en cicatrización y eventos infecciosos postquirúrgicos.\n                                \n                            \n                        \n\n                        \n                            \n                                \n                                    2\n                                    Hipertensión arterial sistémica\n                                \n                                Comorbilidad cardiovascular asociada\n                                \n                                    Paciente con antecedente de hipertensión arterial sistémica, actualmente con cifras tensionales elevadas, requiriendo vigilancia hemodinámica perioperatoria.\n                                \n                            \n                        \n                    \n\n                    \n                        \n                            \n                            \n                                Nota de Guardia:\n                                Paciente con hernia umbilical sintomática y comorbilidades crónicas asociadas. Se recomienda valoración por cirugía general para definir manejo definitivo y control integral de factores de riesgo metabólicos y cardiovasculares.\n                            \n                        \n                    \n\n                \n            \n        \n    \n','\n    \n        \n            \n                \n                    \n                    \n                        \n                            \n                        \n                        \n                            Fase de Análisis\n                            Impresión Clínica Inicial\n       ',4,NULL,NULL,NULL,'../pages/caso.html?id=3&escena=30'),(54,'escena','En pacientes diabéticos programados para cirugía electiva, ¿cuál es la recomendación respecto al uso de Metformina?','\n\n    \n\n    \n\n        \n\n    \n\n        \n\n            \n\n                A\n\n            \n\n            \n\n                Continuar hasta el día de la cirugía\n\n            \n\n        \n\n    \n\n    \n\n        \n\n    \n\n        \n\n            \n\n                B\n\n            \n\n            \n\n                Suspender 24hrs previas\n\n            \n\n        \n\n    \n\n    \n\n        \n\n    \n\n        \n\n            \n\n                C\n\n            \n\n            \n\n                Suspender 7 días previos\n\n            \n\n        \n\n    \n\n    \n\n        \n\n    \n\n        \n\n            \n\n                D\n\n            \n\n            \n\n                Duplicar dosis día previo\n\n            \n\n        \n\n    \n\n    \n\n    \n\n\n\n','\n\n    \n\n    \n\n        \n\n    \n\n        \n\n            \n\n                A\n\n            \n\n            \n\n                Continuar hasta el día de la cirugía\n\n            \n\n        \n\n    \n\n    \n\n        \n\n    \n\n        \n\n            \n\n                B\n\n            \n\n            \n\n                Susp',4,NULL,NULL,NULL,'../pages/caso.html?id=3&escena=31'),(55,'escena','Estudios de laboratorio','\n    \n        \n            \n                \n                \n                    \n                        REPORTE DE RESULTADOS: FOLIO 250524\n                    \n                \n\n                \n                    \n                        \n                        \n                            \n                                \n                            \n                        \n\n                        \n                            \n                               \n     Hallazgos Clave\n\n\n\n    \n        Hiperglucemia\n        162 mg/dL\n    \n    \n        Glucosa sérica elevada compatible con descontrol metabólico en paciente con Diabetes Mellitus tipo 2.\n    \n\n\n\n    \n        HbA1c Elevada\n        8.1 %\n    \n    \n        Indica control glucémico crónicamente inadecuado durante los últimos 3 meses.\n    \n\n\n\n    \n        Función Renal Conservada\n        Cr 1.0 mg/dL\n    \n    \n        Urea y creatinina dentro de parámetros normales, sin datos de deterioro renal agudo.\n    \n\n\n\n    \n        Biometría Hemática Sin Alteraciones\n        Leucocitos 7,800/mm³\n    \n    \n        Sin datos de leucocitosis ni respuesta inflamatoria sistémica activa al momento del estudio.\n    \n\n\n\n                                    \n                                         \n        EGO, TP y TPT dentro de parámetros normales: sin evidencia de infección urinaria ni alteraciones de coagulación.\n    \n\n                            \n                        \n\n                    \n                \n            \n        \n    \n','\n    \n        \n            \n                \n                \n                    \n                        REPORTE DE RESULTADOS: FOLIO 250524\n                    \n                \n\n                \n                    \n                        \n                        \n                            \n ',4,NULL,NULL,NULL,'../pages/caso.html?id=3&escena=32'),(56,'escena','¿Cuál es la principal ventaja del ultrasonido abdominal en la evaluación preoperatoria de hernias umbilicales?','\n\n    \n\n        \n\n            \n\n        \n\n    \n\n    \n\n    \n\n        \n\n    \n\n        \n\n            \n\n                A\n\n            \n\n            \n\n                Determinar el tipo de anestesia\n\n            \n\n        \n\n    \n\n    \n\n        \n\n    \n\n        \n\n            \n\n                B\n\n            \n\n            \n\n                Medir presión intra abdominal\n\n            \n\n        \n\n    \n\n    \n\n        \n\n    \n\n        \n\n            \n\n                C\n\n            \n\n            \n\n                Identificar contenido del saco herniario\n\n            \n\n        \n\n    \n\n    \n\n        \n\n    \n\n        \n\n            \n\n                D\n\n            \n\n            \n\n                d)	Evaluar función intestinal\n\n            \n\n        \n\n    \n\n    \n\n    \n\n\n\n','\n\n    \n\n        \n\n            \n\n        \n\n    \n\n    \n\n    \n\n        \n\n    \n\n        \n\n            \n\n                A\n\n            \n\n            \n\n                Determinar el tipo de anestesia\n\n            \n\n        \n\n    \n\n    \n\n        \n\n    \n\n        \n\n            \n\n                B\n\n         ',4,NULL,NULL,NULL,'../pages/caso.html?id=3&escena=33'),(57,'escena','Envío a consulta de cirugía general','Se integra diagnóstico de:\n•	Hernia umbilical reductible sintomática\n\n•	Defecto herniario >2cm\n\n•	Comorbilidades: DM2 Y HAS\nPlan quirúrgico:\n\n•	Plastia umbilical abierta con colocación de malla\n\n\n                    ','Se integra diagnóstico de:\n•	Hernia umbilical reductible sintomática\n\n•	Defecto herniario >2cm\n\n•	Comorbilidades: DM2 Y HAS\nPlan quirúrgico:\n\n•	Plastia umbilical abierta con colocación de malla\n\n\n                    ',4,NULL,NULL,NULL,'../pages/caso.html?id=3&escena=34'),(58,'escena','Valoración preoperatoria','Riesgo cardiovascular\n\n•	Clasificación ASA: ASA  II\n\n•	Índice de Goldman: Clase I (Bajo riesgo)\nEvaluación metabólica\n\n•	HbA1c: 8.1%\n\n•	Se índica optimización glucémica pre quirúrgica\n\n•	Ajuste de hipoglucemiantes orales\n\n•	Meta pre quirúrgica de glucosa: ','Riesgo cardiovascular\n\n•	Clasificación ASA: ASA  II\n\n•	Índice de Goldman: Clase I (Bajo riesgo)\nEvaluación metabólica\n\n•	HbA1c: 8.1%\n\n•	Se índica optimización glucémica pre quirúrgica\n\n•	Ajuste de hipoglucemiantes orales\n\n•	Meta pre quirúrgica de glucosa: ',4,NULL,NULL,NULL,'../pages/caso.html?id=3&escena=35'),(59,'escena','De acuerdo con la clasificación ASA, ¿Cómo se clasifica un paciente con Diabetes Mellitus tipo 2 e Hipertensión arterial sistémica controlado farmacológicamente?','\n\n                    \n\n\n\n    \n\n        \n\n            \n\n        \n\n    \n\n    \n\n    \n\n        \n\n    \n\n        \n\n            \n\n                A\n\n            \n\n            \n\n                ASA I\n\n            \n\n        \n\n    \n\n    \n\n        \n\n    \n\n        \n\n            \n\n                B\n\n            \n\n            \n\n                ASA II\n\n            \n\n        \n\n    \n\n    \n\n        \n\n    \n\n        \n\n            \n\n                C\n\n            \n\n            \n\n                ASA III\n\n            \n\n        \n\n    \n\n    \n\n        \n\n    \n\n        \n\n            \n\n                D\n\n            \n\n            \n\n                ASAIV\n\n            \n\n     